import { createRoute, z } from '@hono/zod-openapi'

type TypesIdType = string

type TypesDurationType = string | '-1' | '0'

type TypesMetadataType = { [key: string]: { [key: string]: unknown } }

type TypesFieldValueType = number | number | string | boolean | (string | null)

const TypesLatLonGeoLocationSchema = z
  .object({
    lat: z.number().openapi({ description: 'Latitude' }),
    lon: z.number().openapi({ description: 'Longitude' }),
  })
  .openapi({ required: ['lat', 'lon'] })
  .openapi('TypesLatLonGeoLocation')

const TypesGeoHashSchema = z.string().openapi('TypesGeoHash')

const TypesGeoHashLocationSchema = z
  .object({ geohash: TypesGeoHashSchema })
  .openapi({ required: ['geohash'] })
  .openapi('TypesGeoHashLocation')

type TypesGeoLocationType =
  | z.infer<typeof TypesLatLonGeoLocationSchema>
  | z.infer<typeof TypesGeoHashLocationSchema>
  | number[]
  | string

const TypesCoordsGeoBoundsSchema = z
  .object({ top: z.number(), bottom: z.number(), left: z.number(), right: z.number() })
  .openapi({ required: ['top', 'bottom', 'left', 'right'] })
  .openapi('TypesCoordsGeoBounds')

const TypesGeoLocationSchema: z.ZodType<TypesGeoLocationType> = z
  .xor([TypesLatLonGeoLocationSchema, TypesGeoHashLocationSchema, z.array(z.number()), z.string()])
  .openapi({
    description:
      'A latitude/longitude as a 2 dimensional point. It can be represented in various ways:\n- as a `{lat, long}` object\n- as a geo hash value\n- as a `[lon, lat]` array\n- as a string in `"<lat>, <lon>"` or WKT point formats',
  })
  .openapi('TypesGeoLocation')

const TypesTopLeftBottomRightGeoBoundsSchema = z
  .object({ top_left: TypesGeoLocationSchema, bottom_right: TypesGeoLocationSchema })
  .openapi({ required: ['top_left', 'bottom_right'] })
  .openapi('TypesTopLeftBottomRightGeoBounds')

const TypesTopRightBottomLeftGeoBoundsSchema = z
  .object({ top_right: TypesGeoLocationSchema, bottom_left: TypesGeoLocationSchema })
  .openapi({ required: ['top_right', 'bottom_left'] })
  .openapi('TypesTopRightBottomLeftGeoBounds')

const TypesWktGeoBoundsSchema = z
  .object({ wkt: z.string() })
  .openapi({ required: ['wkt'] })
  .openapi('TypesWktGeoBounds')

type TypesGeoBoundsType =
  | z.infer<typeof TypesCoordsGeoBoundsSchema>
  | z.infer<typeof TypesTopLeftBottomRightGeoBoundsSchema>
  | z.infer<typeof TypesTopRightBottomLeftGeoBoundsSchema>
  | z.infer<typeof TypesWktGeoBoundsSchema>

type TypesDurationLargeType = string

const TypesFieldValueSchema: z.ZodType<TypesFieldValueType> = z
