const GlobalSearchTypesHitSchema: z.ZodType<GlobalSearchTypesHitType> = z
  .lazy(() =>
    z
      .object({
        _index: TypesIndexNameSchema,
        _id: TypesIdSchema.exactOptional(),
        _score: z.xor([z.number(), z.string().nullable()]).exactOptional(),
        _explanation: GlobalExplainExplanationSchema.exactOptional(),
        fields: z.record(z.string(), z.object({})).exactOptional(),
        highlight: z.record(z.string(), z.array(z.string())).exactOptional(),
        inner_hits: z.record(z.string(), GlobalSearchTypesInnerHitsResultSchema).exactOptional(),
        matched_queries: z
          .xor([z.array(z.string()), z.record(z.string(), z.number())])
          .exactOptional(),
        _nested: GlobalSearchTypesNestedIdentitySchema.exactOptional(),
        _ignored: z.array(z.string()).exactOptional(),
        ignored_field_values: z.record(z.string(), z.array(z.object({}))).exactOptional(),
        _shard: z.string().exactOptional(),
        _node: z.string().exactOptional(),
        _routing: z.string().exactOptional(),
        _source: z.object({}).exactOptional(),
        _rank: z.number().exactOptional(),
        _seq_no: TypesSequenceNumberSchema.exactOptional(),
        _primary_term: z.number().exactOptional(),
        _version: TypesVersionNumberSchema.exactOptional(),
        sort: TypesSortResultsSchema.exactOptional(),
      })
      .openapi({ required: ['_index'] }),
  )
  .openapi('GlobalSearchTypesHit')

