type TypesAggregationsBucketKsAggregationType = z.infer<
  typeof TypesAggregationsBucketPathAggregationSchema
> & { alternative?: string[]; fractions?: number[]; sampling_method?: string }

const TypesAggregationsBucketKsAggregationSchema: z.ZodType<TypesAggregationsBucketKsAggregationType> =
  TypesAggregationsBucketPathAggregationSchema.and(
    z
      .object({
        alternative: z
          .array(z.string())
          .exactOptional()
          .openapi({
            description:
              'A list of string values indicating which K-S test alternative to calculate. The valid values\nare: "greater", "less", "two_sided". This parameter is key for determining the K-S statistic used\nwhen calculating the K-S test. Default value is all possible alternative hypotheses.',
          }),
        fractions: z
          .array(z.number())
          .exactOptional()
          .openapi({
            description:
              'A list of doubles indicating the distribution of the samples with which to compare to the `buckets_path` results.\nIn typical usage this is the overall proportion of documents in each bucket, which is compared with the actual\ndocument proportions in each bucket from the sibling aggregation counts. The default is to assume that overall\ndocuments are uniformly distributed on these buckets, which they would be if one used equal percentiles of a\nmetric to define the bucket end points.',
          }),
        sampling_method: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'Indicates the sampling methodology when calculating the K-S test. Note, this is sampling of the returned values.\nThis determines the cumulative distribution function (CDF) points used comparing the two samples. Default is\n`upper_tail`, which emphasizes the upper end of the CDF points. Valid options are: `upper_tail`, `uniform`,\nand `lower_tail`.',
          }),
      })
      .openapi({ required: [] }),
  )
    .openapi({
      description:
        'A sibling pipeline aggregation which executes a two sample Kolmogorov–Smirnov test (referred\nto as a "K-S test" from now on) against a provided distribution, and the distribution implied\nby the documents counts in the configured sibling aggregation. Specifically, for some metric,\nassuming that the percentile intervals of the metric are known beforehand or have been computed\nby an aggregation, then one would use range aggregation for the sibling to compute the p-value\nof the distribution difference between the metric and the restriction of that metric to a subset\nof the documents. A natural use case is if the sibling aggregation range aggregation nested in a\nterms aggregation, in which case one compares the overall distribution of metric to its restriction\nto each term.',
    })
    .openapi('TypesAggregationsBucketKsAggregation')

