const TypesAggregationsCategorizeTextAggregationSchema: z.ZodType<TypesAggregationsCategorizeTextAggregationType> =
  TypesAggregationsAggregationSchema.and(
    z
      .object({
        field: TypesFieldSchema.openapi({
          description: 'The semi-structured text field to categorize.',
        }),
        max_unique_tokens: z
          .number()
          .default(50)
          .exactOptional()
          .openapi({
            description:
              'The maximum number of unique tokens at any position up to max_matched_tokens. Must be larger than 1.\nSmaller values use less memory and create fewer categories. Larger values will use more memory and\ncreate narrower categories. Max allowed value is 100.',
          }),
        max_matched_tokens: z
          .number()
          .default(5)
          .exactOptional()
          .openapi({
            description:
              'The maximum number of token positions to match on before attempting to merge categories. Larger\nvalues will use more memory and create narrower categories. Max allowed value is 100.',
          }),
        similarity_threshold: z
          .number()
          .default(50)
          .exactOptional()
          .openapi({
            description:
              'The minimum percentage of tokens that must match for text to be added to the category bucket. Must\nbe between 1 and 100. The larger the value the narrower the categories. Larger values will increase memory\nusage and create narrower categories.',
          }),
        categorization_filters: z
          .array(z.string())
          .exactOptional()
          .openapi({
            description:
              'This property expects an array of regular expressions. The expressions are used to filter out matching\nsequences from the categorization field values. You can use this functionality to fine tune the categorization\nby excluding sequences from consideration when categories are defined. For example, you can exclude SQL\nstatements that appear in your log files. This property cannot be used at the same time as categorization_analyzer.\nIf you only want to define simple regular expression filters that are applied prior to tokenization, setting\nthis property is the easiest method. If you also want to customize the tokenizer or post-tokenization filtering,\nuse the categorization_analyzer property instead and include the filters as pattern_replace character filters.',
          }),
        categorization_analyzer:
          TypesAggregationsCategorizeTextAnalyzerSchema.exactOptional().openapi({
            externalDocs: {
              url: 'https://www.elastic.co/docs/api/doc/elasticsearch/operation/operation-indices-analyze',
            },
            description:
              'The categorization analyzer specifies how the text is analyzed and tokenized before being categorized.\nThe syntax is very similar to that used to define the analyzer in the analyze API. This property\ncannot be used at the same time as `categorization_filters`.',
          }),
        shard_size: z
          .number()
          .exactOptional()
          .openapi({
            description:
              'The number of categorization buckets to return from each shard before merging all the results.',
          }),
        size: z
          .number()
          .default(10)
          .exactOptional()
          .openapi({ description: 'The number of buckets to return.' }),
        min_doc_count: z
          .number()
          .exactOptional()
          .openapi({
            description:
              'The minimum number of documents in a bucket to be returned to the results.',
          }),
        shard_min_doc_count: z
          .number()
          .exactOptional()
          .openapi({
            description:
              'The minimum number of documents in a bucket to be returned from the shard before merging.',
          }),
      })
      .openapi({ required: ['field'] }),
  )
    .openapi({
      description:
        'A multi-bucket aggregation that groups semi-structured text into buckets. Each text\nfield is re-analyzed using a custom analyzer. The resulting tokens are then categorized\ncreating buckets of similarly formatted text values. This aggregation works best with machine\ngenerated text like system logs. Only the first 100 analyzed tokens are used to categorize the text.',
    })
    .openapi('TypesAggregationsCategorizeTextAggregation')

