const IndicesTypesTranslogRetentionSchema = z
  .object({
    size: TypesByteSizeSchema.default('512mb')
      .exactOptional()
      .openapi({
        description:
          'This controls the total size of translog files to keep for each shard. Keeping more translog files increases\nthe chance of performing an operation based sync when recovering a replica. If the translog files are not\nsufficient, replica recovery will fall back to a file based sync. This setting is ignored, and should not be\nset, if soft deletes are enabled. Soft deletes are enabled by default in indices created in Elasticsearch\nversions 7.0.0 and later.',
      }),
    age: TypesDurationSchema.default('12h')
      .exactOptional()
      .openapi({
        description:
          'This controls the maximum duration for which translog files are kept by each shard. Keeping more\ntranslog files increases the chance of performing an operation based sync when recovering replicas. If\nthe translog files are not sufficient, replica recovery will fall back to a file based sync. This setting\nis ignored, and should not be set, if soft deletes are enabled. Soft deletes are enabled by default in\nindices created in Elasticsearch versions 7.0.0 and later.',
      }),
  })
  .openapi({ required: [] })
  .openapi('IndicesTypesTranslogRetention')

