const TypesMappingDenseVectorIndexOptionsSchema: z.ZodType<TypesMappingDenseVectorIndexOptionsType> =
  z
    .object({
      confidence_interval: z
        .number()
        .exactOptional()
        .openapi({
          deprecated: true,
          description:
            'The confidence interval to use when quantizing the vectors. Can be any value between and including `0.90` and\n`1.0` or exactly `0`. When the value is `0`, this indicates that dynamic quantiles should be calculated for\noptimized quantization. When between `0.90` and `1.0`, this value restricts the values used when calculating\nthe quantization thresholds.\n\nFor example, a value of `0.95` will only use the middle `95%` of the values when calculating the quantization\nthresholds (e.g. the highest and lowest `2.5%` of values will be ignored).\n\nDefaults to `1/(dims + 1)` for `int8` quantized vectors and `0` for `int4` for dynamic quantile calculation.\n\nOnly applicable to `int8_hnsw`, `int4_hnsw`, `int8_flat`, and `int4_flat` index types.',
        }),
      ef_construction: z
        .number()
        .default(100)
        .exactOptional()
        .openapi({
          description:
            'The number of candidates to track while assembling the list of nearest neighbors for each new node.\n\nOnly applicable to `hnsw`, `int8_hnsw`, `bbq_hnsw`, and `int4_hnsw` index types.',
        }),
      m: z
        .number()
        .default(16)
        .exactOptional()
        .openapi({
          description:
            'The number of neighbors each node will be connected to in the HNSW graph.\n\nOnly applicable to `hnsw`, `int8_hnsw`, `bbq_hnsw`, and `int4_hnsw` index types.',
        }),
      type: TypesMappingDenseVectorIndexOptionsTypeSchema.openapi({
        description: 'The type of kNN algorithm to use.',
      }),
      rescore_vector:
        TypesMappingDenseVectorIndexOptionsRescoreVectorSchema.exactOptional().openapi({
          description:
            'The rescore vector options. This is only applicable to `bbq_disk`, `bbq_hnsw`, `int4_hnsw`, `int8_hnsw`, `bbq_flat`, `int4_flat`, and `int8_flat` index types.',
        }),
      on_disk_rescore: z
        .boolean()
        .default(false)
        .exactOptional()
        .openapi({
          description:
            '`true` if vector rescoring should be done on-disk\n\nOnly applicable to `bbq_disk`, `bbq_hnsw`, `int4_hnsw`, `int8_hnsw`',
          'x-state': 'Experimental; Added in 9.3.0',
        }),
      flat_index_threshold: z
        .number()
        .default(-1)
        .exactOptional()
        .openapi({
          description:
            'The segment document count threshold below which HNSW graph construction is skipped in favor of brute-force flat\nsearch. `-1` (default) defers to format defaults: `300` for `bbq_hnsw`, `150` for `hnsw`, `int8_hnsw`, and\n`int4_hnsw`. `0` always builds the graph. A positive value overrides the format default.\n\nOnly applicable to `hnsw`, `int8_hnsw`, `int4_hnsw`, `bbq_hnsw`, and `bbq_disk` index types.',
          'x-state': 'Generally available; Added in 9.4.0',
        }),
      cluster_size: z
        .number()
        .default(384)
        .exactOptional()
        .openapi({
          description:
            'Only applicable to `bbq_disk`. The number of vectors per cluster. Must be between 64 and 65536.',
          'x-state': 'Generally available; Added in 9.2.0',
        }),
      default_visit_percentage: z
        .number()
        .default(0)
        .exactOptional()
        .openapi({
          description:
            'Only applicable to `bbq_disk`. The percentage of clusters to visit during search. Must be between 0 and 100.\nA value of 0 defaults to using `num_candidates` for calculating the visit percentage.',
          'x-state': 'Generally available; Added in 9.2.0',
        }),
      bits: z
        .number()
        .default(1)
        .exactOptional()
        .openapi({
          description:
            'Only applicable to `bbq_disk`. The number of bits per dimension for quantization encoding.\nValid values are `1`, `2`, `4`, or `7`. When no `rescore_vector` is explicitly set,\nthe default oversampling is automatically adjusted based on the bits value.\nThis setting can be changed without reindexing.',
          'x-state': 'Generally available; Added in 9.4.0',
        }),
      precondition: z
        .boolean()
        .default(false)
        .exactOptional()
        .openapi({
          description:
            'Only applicable to `bbq_disk`. When `true`, transforms indexed vectors using a random orthogonal\nprojection before quantization, which can improve accuracy when vector components are not normally\ndistributed. Cannot be changed after the field is created.',
          'x-state': 'Generally available; Added in 9.4.0',
        }),
      auto_calibrate: z
        .boolean()
        .default(false)
        .exactOptional()
        .openapi({
          description:
            'Only applicable to `bbq_disk`. When `true`, Elasticsearch automatically selects the optimal\nquantization encoding, oversampling factor, and preconditioning for each merged segment based\non estimated recall characteristics. Cannot be changed after the field is created.',
          'x-state': 'Generally available; Added in 9.5.0',
        }),
    })
    .openapi({ required: ['type'] })
