const CatRecoveryRecoveryRecordSchema = z
  .object({
    index: TypesIndexNameSchema.exactOptional().openapi({ description: 'The index name.' }),
    shard: z.string().exactOptional().openapi({ description: 'The shard name.' }),
    start_time: TypesDateTimeSchema.exactOptional().openapi({
      description:
        'The recovery start time.\nFor recoveries in the `created` stage (not yet started), this value is the Unix epoch (1970-01-01T00:00:00.000Z).',
    }),
    start_time_millis: TypesEpochTimeUnitMillisSchema.exactOptional().openapi({
      description:
        'The recovery start time in epoch milliseconds.\nFor recoveries in the `created` stage (not yet started), this value is 0.',
    }),
    stop_time: TypesDateTimeSchema.exactOptional().openapi({
      description:
        'The recovery stop time.\nFor recoveries that have not yet completed, this value is the Unix epoch (1970-01-01T00:00:00.000Z).',
    }),
    stop_time_millis: TypesEpochTimeUnitMillisSchema.exactOptional().openapi({
      description:
        'The recovery stop time in epoch milliseconds.\nFor recoveries that have not yet completed, this value is 0.',
    }),
    time: TypesDurationSchema.exactOptional().openapi({
      description:
        'The recovery time.\nFor recoveries in the `created` stage (not yet started), this value is 0.',
    }),
    type: z.string().exactOptional().openapi({ description: 'The recovery type.' }),
    stage: z.string().exactOptional().openapi({ description: 'The recovery stage.' }),
    local_retries: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The number of times this recovery has failed in a way which is retried locally (i.e. on the data node).',
        'x-state': 'Generally available; Added in 9.6.0',
      }),
    priority: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The recovery priority.',
        'x-state': 'Generally available; Added in 9.6.0',
      }),
    gate: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The name of the recovery gate that blocked recovery on the target node.\n\nThe value is `n/a` unless the recovery is queued in the `created` stage and blocked by a recovery gate.',
        'x-state': 'Generally available; Added in 9.6.0',
      }),
    blocked_for_millis: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The elapsed time in milliseconds recovery is blocked for.\n\nThe value is `n/a` when the recovery is not blocked by a recovery gate.',
        'x-state': 'Generally available; Added in 9.6.0',
      }),
    source_host: z.string().exactOptional().openapi({ description: 'The source host.' }),
    source_node: z.string().exactOptional().openapi({ description: 'The source node name.' }),
    target_host: z.string().exactOptional().openapi({ description: 'The target host.' }),
    target_node: z.string().exactOptional().openapi({ description: 'The target node name.' }),
    repository: z.string().exactOptional().openapi({ description: 'The repository name.' }),
    snapshot: z.string().exactOptional().openapi({ description: 'The snapshot name.' }),
    files: z.string().exactOptional().openapi({ description: 'The number of files to recover.' }),
    files_recovered: z.string().exactOptional().openapi({ description: 'The files recovered.' }),
    files_percent: TypesPercentageSchema.exactOptional().openapi({
      description: 'The ratio of files recovered.',
    }),
    files_total: z.string().exactOptional().openapi({ description: 'The total number of files.' }),
    bytes: z.string().exactOptional().openapi({ description: 'The number of bytes to recover.' }),
    bytes_recovered: z.string().exactOptional().openapi({ description: 'The bytes recovered.' }),
    bytes_percent: TypesPercentageSchema.exactOptional().openapi({
      description: 'The ratio of bytes recovered.',
    }),
    bytes_total: z.string().exactOptional().openapi({ description: 'The total number of bytes.' }),
    translog_ops: z
      .string()
      .exactOptional()
      .openapi({ description: 'The number of translog operations to recover.' }),
    translog_ops_recovered: z
      .string()
      .exactOptional()
      .openapi({ description: 'The translog operations recovered.' }),
    translog_ops_percent: TypesPercentageSchema.exactOptional().openapi({
      description: 'The ratio of translog operations recovered.',
    }),
  })
  .openapi({ required: [] })
  .openapi('CatRecoveryRecoveryRecord')

