const CatSegmentsSegmentsRecordSchema = z
  .object({
    index: TypesIndexNameSchema.exactOptional().openapi({ description: 'The index name.' }),
    shard: z.string().exactOptional().openapi({ description: 'The shard name.' }),
    prirep: z
      .string()
      .exactOptional()
      .openapi({ description: 'The shard type: `primary` or `replica`.' }),
    ip: z
      .string()
      .exactOptional()
      .openapi({ description: 'The IP address of the node where it lives.' }),
    id: TypesNodeIdSchema.exactOptional().openapi({
      description: 'The unique identifier of the node where it lives.',
    }),
    segment: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The segment name, which is derived from the segment generation and used internally to create file names in the directory of the shard.',
      }),
    generation: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The segment generation number.\nElasticsearch increments this generation number for each segment written then uses this number to derive the segment name.',
      }),
    'docs.count': z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The number of documents in the segment.\nThis excludes deleted documents and counts any nested documents separately from their parents.\nIt also excludes documents which were indexed recently and do not yet belong to a segment.',
      }),
    'docs.deleted': z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The number of deleted documents in the segment, which might be higher or lower than the number of delete operations you have performed.\nThis number excludes deletes that were performed recently and do not yet belong to a segment.\nDeleted documents are cleaned up by the automatic merge process if it makes sense to do so.\nAlso, Elasticsearch creates extra deleted documents to internally track the recent history of operations on a shard.',
      }),
    size: TypesByteSizeSchema.exactOptional().openapi({
      description: 'The segment size in bytes.',
    }),
    'size.memory': TypesByteSizeSchema.exactOptional().openapi({
      description:
        'The segment memory in bytes.\nA value of `-1` indicates Elasticsearch was unable to compute this number.',
    }),
    committed: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'If `true`, the segment is synced to disk.\nSegments that are synced can survive a hard reboot.\nIf `false`, the data from uncommitted segments is also stored in the transaction log so that Elasticsearch is able to replay changes on the next start.',
      }),
    searchable: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'If `true`, the segment is searchable.\nIf `false`, the segment has most likely been written to disk but needs a refresh to be searchable.',
      }),
    version: TypesVersionStringSchema.exactOptional().openapi({
      description: 'The version of Lucene used to write the segment.',
    }),
    compound: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'If `true`, the segment is stored in a compound file.\nThis means Lucene merged all files from the segment in a single file to save file descriptors.',
      }),
  })
  .openapi({ required: [] })
  .openapi('CatSegmentsSegmentsRecord')

