const CatTransformsTransformsRecordSchema = z
  .object({
    id: TypesIdSchema.exactOptional().openapi({ description: 'The transform identifier.' }),
    state: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The status of the transform.\nReturned values include:\n`aborting`: The transform is aborting.\n`failed: The transform failed. For more information about the failure, check the `reason` field.\n`indexing`: The transform is actively processing data and creating new documents.\n`started`: The transform is running but not actively indexing data.\n`stopped`: The transform is stopped.\n`stopping`: The transform is stopping.',
      }),
    checkpoint: z
      .string()
      .exactOptional()
      .openapi({ description: 'The sequence number for the checkpoint.' }),
    documents_processed: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The number of documents that have been processed from the source index of the transform.',
      }),
    checkpoint_progress: z
      .xor([z.string(), z.string().nullable()])
      .exactOptional()
      .openapi({
        description: 'The progress of the next checkpoint that is currently in progress.',
      }),
    last_search_time: z
      .xor([z.string(), z.string().nullable()])
      .exactOptional()
      .openapi({
        description:
          'The timestamp of the last search in the source indices.\nThis field is shown only if the transform is running.',
      }),
    changes_last_detection_time: z
      .xor([z.string(), z.string().nullable()])
      .exactOptional()
      .openapi({
        description: 'The timestamp when changes were last detected in the source indices.',
      }),
    create_time: z
      .string()
      .exactOptional()
      .openapi({ description: 'The time the transform was created.' }),
    version: TypesVersionStringSchema.exactOptional().openapi({
      description:
        'The version of Elasticsearch that existed on the node when the transform was created.',
    }),
    source_index: z
      .string()
      .exactOptional()
      .openapi({ description: 'The source indices for the transform.' }),
    dest_index: z
      .string()
      .exactOptional()
      .openapi({ description: 'The destination index for the transform.' }),
    pipeline: z
      .string()
      .exactOptional()
      .openapi({ description: 'The unique identifier for the ingest pipeline.' }),
    description: z
      .string()
      .exactOptional()
      .openapi({ description: 'The description of the transform.' }),
    transform_type: z
      .string()
      .exactOptional()
      .openapi({ description: 'The type of transform: `batch` or `continuous`.' }),
    frequency: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The interval between checks for changes in the source indices when the transform is running continuously.',
      }),
    max_page_search_size: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The initial page size that is used for the composite aggregation for each checkpoint.',
      }),
    docs_per_second: z
      .string()
      .exactOptional()
      .openapi({ description: 'The number of input documents per second.' }),
    reason: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'If a transform has a `failed` state, these details describe the reason for failure.',
      }),
    search_total: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The total number of search operations on the source index for the transform.',
      }),
    search_failure: z
      .string()
      .exactOptional()
      .openapi({ description: 'The total number of search failures.' }),
    search_time: z
      .string()
      .exactOptional()
      .openapi({ description: 'The total amount of search time, in milliseconds.' }),
    index_total: z
      .string()
      .exactOptional()
      .openapi({ description: 'The total number of index operations done by the transform.' }),
    index_failure: z
      .string()
      .exactOptional()
      .openapi({ description: 'The total number of indexing failures.' }),
    index_time: z
      .string()
      .exactOptional()
      .openapi({ description: 'The total time spent indexing documents, in milliseconds.' }),
    documents_indexed: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The number of documents that have been indexed into the destination index for the transform.',
      }),
    delete_time: z
      .string()
      .exactOptional()
      .openapi({ description: 'The total time spent deleting documents, in milliseconds.' }),
    documents_deleted: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The number of documents deleted from the destination index due to the retention policy for the transform.',
      }),
    trigger_count: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The number of times the transform has been triggered by the scheduler.\nFor example, the scheduler triggers the transform indexer to check for updates or ingest new data at an interval specified in the `frequency` property.',
      }),
    pages_processed: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The number of search or bulk index operations processed.\nDocuments are processed in batches instead of individually.',
      }),
    processing_time: z
      .string()
      .exactOptional()
      .openapi({ description: 'The total time spent processing results, in milliseconds.' }),
    checkpoint_duration_time_exp_avg: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The exponential moving average of the duration of the checkpoint, in milliseconds.',
      }),
    indexed_documents_exp_avg: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The exponential moving average of the number of new documents that have been indexed.',
      }),
    processed_documents_exp_avg: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The exponential moving average of the number of documents that have been processed.',
      }),
  })
  .openapi({ required: [] })
  .openapi('CatTransformsTransformsRecord')

