const CcrTypesShardStatsSchema = z
  .object({
    bytes_read: z
      .number()
      .openapi({
        description:
          'The total of transferred bytes read from the leader.\nThis is only an estimate and does not account for compression if enabled.',
      }),
    failed_read_requests: z.number().openapi({ description: 'The number of failed reads.' }),
    failed_write_requests: z
      .number()
      .openapi({ description: 'The number of failed bulk write requests on the follower.' }),
    fatal_exception: TypesErrorCauseSchema.exactOptional(),
    follower_aliases_version: TypesVersionNumberSchema.openapi({
      description: 'The index aliases version the follower is synced up to.',
    }),
    follower_global_checkpoint: z
      .number()
      .openapi({
        description:
          'The current global checkpoint on the follower.\nThe difference between the `leader_global_checkpoint` and the `follower_global_checkpoint` is an indication of how much the follower is lagging the leader.',
      }),
    follower_index: z.string().openapi({ description: 'The name of the follower index.' }),
    follower_mapping_version: TypesVersionNumberSchema.openapi({
      description: 'The mapping version the follower is synced up to.',
    }),
    follower_max_seq_no: TypesSequenceNumberSchema.openapi({
      description: 'The current maximum sequence number on the follower.',
    }),
    follower_settings_version: TypesVersionNumberSchema.openapi({
      description: 'The index settings version the follower is synced up to.',
    }),
    last_requested_seq_no: TypesSequenceNumberSchema.openapi({
      description:
        'The starting sequence number of the last batch of operations requested from the leader.',
    }),
    leader_global_checkpoint: z
      .number()
      .openapi({
        description: 'The current global checkpoint on the leader known to the follower task.',
      }),
    leader_index: z
      .string()
      .openapi({ description: 'The name of the index in the leader cluster being followed.' }),
    leader_max_seq_no: TypesSequenceNumberSchema.openapi({
      description: 'The current maximum sequence number on the leader known to the follower task.',
    }),
    operations_read: z
      .number()
      .openapi({ description: 'The total number of operations read from the leader.' }),
    operations_written: z
      .number()
      .openapi({ description: 'The number of operations written on the follower.' }),
    outstanding_read_requests: z
      .number()
      .openapi({ description: 'The number of active read requests from the follower.' }),
    outstanding_write_requests: z
      .number()
      .openapi({ description: 'The number of active bulk write requests on the follower.' }),
    read_exceptions: z
      .array(CcrTypesReadExceptionSchema)
      .openapi({ description: 'An array of objects representing failed reads.' }),
    remote_cluster: z
      .string()
      .openapi({ description: 'The remote cluster containing the leader index.' }),
    shard_id: z
      .number()
      .openapi({
        description:
          'The numerical shard ID, with values from 0 to one less than the number of replicas.',
      }),
    successful_read_requests: z
      .number()
      .openapi({ description: 'The number of successful fetches.' }),
    successful_write_requests: z
      .number()
      .openapi({ description: 'The number of bulk write requests run on the follower.' }),
    time_since_last_read: TypesDurationSchema.exactOptional(),
    time_since_last_read_millis: TypesDurationValueUnitMillisSchema.openapi({
      description:
        'The number of milliseconds since a read request was sent to the leader.\nWhen the follower is caught up to the leader, this number will increase up to the configured `read_poll_timeout` at which point another read request will be sent to the leader.',
    }),
    total_read_remote_exec_time: TypesDurationSchema.exactOptional(),
    total_read_remote_exec_time_millis: TypesDurationValueUnitMillisSchema.openapi({
      description: 'The total time reads spent running on the remote cluster.',
    }),
    total_read_time: TypesDurationSchema.exactOptional(),
    total_read_time_millis: TypesDurationValueUnitMillisSchema.openapi({
      description:
        'The total time reads were outstanding, measured from the time a read was sent to the leader to the time a reply was returned to the follower.',
    }),
    total_write_time: TypesDurationSchema.exactOptional(),
    total_write_time_millis: TypesDurationValueUnitMillisSchema.openapi({
      description: 'The total time spent writing on the follower.',
    }),
    write_buffer_operation_count: z
      .number()
      .openapi({ description: 'The number of write operations queued on the follower.' }),
    write_buffer_size_in_bytes: TypesByteSizeSchema.openapi({
      description: 'The total number of bytes of operations currently queued for writing.',
    }),
  })
  .openapi({
    required: [
      'bytes_read',
      'failed_read_requests',
      'failed_write_requests',
      'follower_aliases_version',
      'follower_global_checkpoint',
      'follower_index',
      'follower_mapping_version',
      'follower_max_seq_no',
      'follower_settings_version',
      'last_requested_seq_no',
      'leader_global_checkpoint',
      'leader_index',
      'leader_max_seq_no',
      'operations_read',
      'operations_written',
      'outstanding_read_requests',
      'outstanding_write_requests',
      'read_exceptions',
      'remote_cluster',
      'shard_id',
      'successful_read_requests',
      'successful_write_requests',
      'time_since_last_read_millis',
      'total_read_remote_exec_time_millis',
      'total_read_time_millis',
      'total_write_time_millis',
      'write_buffer_operation_count',
      'write_buffer_size_in_bytes',
    ],
  })
  .openapi('CcrTypesShardStats')

