const InferenceTypesInferenceChunkingSettingsSchema = z
  .object({
    max_chunk_size: z
      .number()
      .default(250)
      .exactOptional()
      .openapi({
        description:
          'The maximum size of a chunk in words.\nThis value cannot be lower than `20` (for `sentence` strategy) or `10` (for `word` strategy).\nThis value should not exceed the window size for the associated model.',
      }),
    overlap: z
      .number()
      .default(100)
      .exactOptional()
      .openapi({
        description:
          'The number of overlapping words for chunks.\nIt is applicable only to a `word` chunking strategy.\nThis value cannot be higher than half the `max_chunk_size` value.',
      }),
    sentence_overlap: z
      .number()
      .default(1)
      .exactOptional()
      .openapi({
        description:
          'The number of overlapping sentences for chunks.\nIt is applicable only for a `sentence` chunking strategy.\nIt can be either `1` or `0`.',
      }),
    separator_group: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Only applicable to the `recursive` strategy and required when using it.\n\nSets a predefined list of separators in the saved chunking settings based on the selected text type.\nValues can be `markdown` or `plaintext`.\n\nUsing this parameter is an alternative to manually specifying a custom `separators` list.',
      }),
    separators: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'Only applicable to the `recursive` strategy and required when using it.\n\nA list of strings used as possible split points when chunking text.\n\nEach string can be a plain string or a regular expression (regex) pattern.\nThe system tries each separator in order to split the text, starting from the first item in the list.\n\nAfter splitting, it attempts to recombine smaller pieces into larger chunks that stay within\nthe `max_chunk_size` limit, to reduce the total number of chunks generated.',
      }),
    strategy: z
      .string()
      .default('sentence')
      .exactOptional()
      .openapi({
        externalDocs: {
          url: 'https://www.elastic.co/docs/explore-analyze/elastic-inference/inference-api#chunking-strategies',
        },
        description:
          'The chunking strategy: `sentence`, `word`, `none` or `recursive`.\n\n * If `strategy` is set to `recursive`, you must also specify:\n\n- `max_chunk_size`\n- either `separators` or`separator_group`\n\nLearn more about different chunking strategies in the linked documentation.',
      }),
  })
  .openapi({ description: 'Chunking configuration object', required: [] })
  .openapi('InferenceTypesInferenceChunkingSettings')

