const MlTypesHyperparametersSchema = z
  .object({
    alpha: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Advanced configuration option.\nMachine learning uses loss guided tree growing, which means that the decision trees grow where the regularized loss decreases most quickly.\nThis parameter affects loss calculations by acting as a multiplier of the tree depth.\nHigher alpha values result in shallower trees and faster training times.\nBy default, this value is calculated during hyperparameter optimization.\nIt must be greater than or equal to zero.',
      }),
    lambda: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Advanced configuration option.\nRegularization parameter to prevent overfitting on the training data set.\nMultiplies an L2 regularization term which applies to leaf weights of the individual trees in the forest.\nA high lambda value causes training to favor small leaf weights.\nThis behavior makes the prediction function smoother at the expense of potentially not being able to capture relevant relationships between the features and the dependent variable.\nA small lambda value results in large individual trees and slower training.\nBy default, this value is calculated during hyperparameter optimization.\nIt must be a nonnegative value.',
      }),
    gamma: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Advanced configuration option.\nRegularization parameter to prevent overfitting on the training data set.\nMultiplies a linear penalty associated with the size of individual trees in the forest.\nA high gamma value causes training to prefer small trees.\nA small gamma value results in larger individual trees and slower training.\nBy default, this value is calculated during hyperparameter optimization.\nIt must be a nonnegative value.',
      }),
    eta: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Advanced configuration option.\nThe shrinkage applied to the weights.\nSmaller values result in larger forests which have a better generalization error.\nHowever, larger forests cause slower training.\nBy default, this value is calculated during hyperparameter optimization.\nIt must be a value between `0.001` and `1`.',
      }),
    eta_growth_rate_per_tree: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Advanced configuration option.\nSpecifies the rate at which `eta` increases for each new tree that is added to the forest.\nFor example, a rate of 1.05 increases `eta` by 5% for each extra tree.\nBy default, this value is calculated during hyperparameter optimization.\nIt must be between `0.5` and `2`.',
      }),
    feature_bag_fraction: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Advanced configuration option.\nDefines the fraction of features that will be used when selecting a random bag for each candidate split.\nBy default, this value is calculated during hyperparameter optimization.',
      }),
    downsample_factor: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Advanced configuration option.\nControls the fraction of data that is used to compute the derivatives of the loss function for tree training.\nA small value results in the use of a small fraction of the data.\nIf this value is set to be less than 1, accuracy typically improves.\nHowever, too small a value may result in poor convergence for the ensemble and so require more trees.\nBy default, this value is calculated during hyperparameter optimization.\nIt must be greater than zero and less than or equal to 1.',
      }),
    max_attempts_to_add_tree: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'If the algorithm fails to determine a non-trivial tree (more than a single leaf), this parameter determines how many of such consecutive failures are tolerated.\nOnce the number of attempts exceeds the threshold, the forest training stops.',
      }),
    max_optimization_rounds_per_hyperparameter: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Advanced configuration option.\nA multiplier responsible for determining the maximum number of hyperparameter optimization steps in the Bayesian optimization procedure.\nThe maximum number of steps is determined based on the number of undefined hyperparameters times the maximum optimization rounds per hyperparameter.\nBy default, this value is calculated during hyperparameter optimization.',
      }),
    max_trees: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Advanced configuration option.\nDefines the maximum number of decision trees in the forest.\nThe maximum value is 2000.\nBy default, this value is calculated during hyperparameter optimization.',
      }),
    num_folds: z
      .number()
      .exactOptional()
      .openapi({ description: 'The maximum number of folds for the cross-validation procedure.' }),
    num_splits_per_feature: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Determines the maximum number of splits for every feature that can occur in a decision tree when the tree is trained.',
      }),
    soft_tree_depth_limit: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Advanced configuration option.\nMachine learning uses loss guided tree growing, which means that the decision trees grow where the regularized loss decreases most quickly.\nThis soft limit combines with the `soft_tree_depth_tolerance` to penalize trees that exceed the specified depth; the regularized loss increases quickly beyond this depth.\nBy default, this value is calculated during hyperparameter optimization.\nIt must be greater than or equal to 0.',
      }),
    soft_tree_depth_tolerance: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Advanced configuration option.\nThis option controls how quickly the regularized loss increases when the tree depth exceeds `soft_tree_depth_limit`.\nBy default, this value is calculated during hyperparameter optimization.\nIt must be greater than or equal to 0.01.',
      }),
  })
  .openapi({ required: [] })
  .openapi('MlTypesHyperparameters')

