const XpackUsageGpuNodeStatsSchema = z
  .object({
    type: z
      .string()
      .openapi({ description: 'GPU device type (e.g., "NVIDIA L4", "NVIDIA A100").' }),
    memory_in_bytes: z.number().openapi({ description: 'GPU memory in bytes.' }),
    enabled: z
      .boolean()
      .openapi({ description: 'Whether GPU vector indexing is enabled on this node.' }),
    index_build_count: z
      .number()
      .openapi({ description: 'Number of GPU index builds performed on this node.' }),
  })
  .openapi({
    description: 'Per-node GPU statistics for vector indexing.',
    required: ['type', 'memory_in_bytes', 'enabled', 'index_build_count'],
  })
  .openapi('XpackUsageGpuNodeStats')

const XpackUsageGpuVectorIndexingSchema = XpackUsageBaseSchema.and(
  z
    .object({
      index_build_count: z
        .number()
        .openapi({ description: 'Total GPU index builds across the cluster.' }),
      nodes_with_gpu: z.number().openapi({ description: 'Count of data nodes with GPU support.' }),
      nodes: z
        .array(XpackUsageGpuNodeStatsSchema)
        .openapi({
          description:
            'Per-node GPU details including type, memory, enabled status, and build count.',
        }),
    })
    .openapi({ required: ['index_build_count', 'nodes_with_gpu', 'nodes'] }),
)
  .openapi({ description: 'GPU vector indexing usage statistics.' })
  .openapi('XpackUsageGpuVectorIndexing')

const XpackUsageInvocationsSchema = z
  .object({ total: z.number() })
