const BulkRequestBody = {
  content: {
    'application/json': {
      schema: z.array(
        z.xor([GlobalBulkOperationContainerSchema, GlobalBulkUpdateActionSchema, z.object({})]),
      ),
      examples: {
        BulkRequestExample1: {
          summary: 'Multiple operations',
          description: 'Run `POST _bulk` to perform multiple operations.',
          value:
            '{ "index" : { "_index" : "test", "_id" : "1" } }\n{ "field1" : "value1" }\n{ "delete" : { "_index" : "test", "_id" : "2" } }\n{ "create" : { "_index" : "test", "_id" : "3" } }\n{ "field1" : "value3" }\n{ "update" : {"_id" : "1", "_index" : "test"} }\n{ "doc" : {"field2" : "value2"} }',
        },
        BulkRequestExample2: {
          summary: 'Bulk updates',
          description:
            'When you run `POST _bulk` and use the `update` action, you can use `retry_on_conflict` as a field in the action itself (not in the extra payload line) to specify how many times an update should be retried in the case of a version conflict.\n',
          value:
            '{ "update" : {"_id" : "1", "_index" : "index1", "retry_on_conflict" : 3} }\n{ "doc" : {"field" : "value"} }\n{ "update" : { "_id" : "0", "_index" : "index1", "retry_on_conflict" : 3} }\n{ "script" : { "source": "ctx._source.counter += params.param1", "lang" : "painless", "params" : {"param1" : 1}}, "upsert" : {"counter" : 1}}\n{ "update" : {"_id" : "2", "_index" : "index1", "retry_on_conflict" : 3} }\n{ "doc" : {"field" : "value"}, "doc_as_upsert" : true }\n{ "update" : {"_id" : "3", "_index" : "index1", "_source" : true} }\n{ "doc" : {"field" : "value"} }\n{ "update" : {"_id" : "4", "_index" : "index1"} }\n{ "doc" : {"field" : "value"}, "_source": true}',
        },
        BulkRequestExample3: {
          summary: 'Filter for failed operations',
          description:
            'To return only information about failed operations, run `POST /_bulk?filter_path=items.*.error`.\n',
          value:
            '{ "update": {"_id": "5", "_index": "index1"} }\n{ "doc": {"my_field": "foo"} }\n{ "update": {"_id": "6", "_index": "index1"} }\n{ "doc": {"my_field": "foo"} }\n{ "create": {"_id": "7", "_index": "index1"} }\n{ "my_field": "foo" }',
        },
        BulkRequestExample4: {
          summary: 'Dynamic templates',
          description:
            'Run `POST /_bulk` to perform a bulk request that consists of index and create actions with the `dynamic_templates` parameter. The bulk request creates two new fields `work_location` and `home_location` with type `geo_point` according to the `dynamic_templates` parameter. However, the `raw_location` field is created using default dynamic mapping rules, as a text field in that case since it is supplied as a string in the JSON document.\n',
          value:
            '{ "index" : { "_index" : "my_index", "_id" : "1", "dynamic_templates": {"work_location": "geo_point"}} }\n{ "field" : "value1", "work_location": "41.12,-71.34", "raw_location": "41.12,-71.34"}\n{ "create" : { "_index" : "my_index", "_id" : "2", "dynamic_templates": {"home_location": "geo_point"}} }\n{ "field" : "value2", "home_location": "41.12,-71.34"}',
        },
      },
    },
  },
  required: true,
}

