const SearchMvtRequestBody = {
  content: {
    'application/json': {
      schema: z
        .object({
          aggs: z
            .record(z.string(), TypesAggregationsAggregationContainerSchema)
            .exactOptional()
            .openapi({
              description:
                "Sub-aggregations for the geotile_grid.\n\nIt supports the following aggregation types:\n\n- `avg`\n- `boxplot`\n- `cardinality`\n- `extended stats`\n- `max`\n- `median absolute deviation`\n- `min`\n- `percentile`\n- `percentile-rank`\n- `stats`\n- `sum`\n- `value count`\n\nThe aggregation names can't start with `_mvt_`. The `_mvt_` prefix is reserved for internal aggregations.",
            }),
          buffer: z
            .number()
            .default(5)
            .exactOptional()
            .openapi({
              description:
                'The size, in pixels, of a clipping buffer outside the tile. This allows renderers\nto avoid outline artifacts from geometries that extend past the extent of the tile.',
            }),
          exact_bounds: z
            .boolean()
            .default(false)
            .exactOptional()
            .openapi({
              description:
                "If `false`, the meta layer's feature is the bounding box of the tile.\nIf `true`, the meta layer's feature is a bounding box resulting from a\n`geo_bounds` aggregation. The aggregation runs on <field> values that intersect\nthe `<zoom>/<x>/<y>` tile with `wrap_longitude` set to `false`. The resulting\nbounding box may be larger than the vector tile.",
            }),
          extent: z
            .number()
            .default(4096)
            .exactOptional()
            .openapi({
              description:
                'The size, in pixels, of a side of the tile. Vector tiles are square with equal sides.',
            }),
          fields: TypesFieldsSchema.exactOptional().openapi({
            description:
              'The fields to return in the `hits` layer.\nIt supports wildcards (`*`).\nThis parameter does not support fields with array values. Fields with array\nvalues may return inconsistent results.',
          }),
          grid_agg: GlobalSearchMvtTypesGridAggregationTypeSchema.exactOptional().openapi({
            description: 'The aggregation used to create a grid for the `field`.',
          }),
          grid_precision: z
            .number()
            .default(8)
            .exactOptional()
            .openapi({
              description:
                "Additional zoom levels available through the aggs layer. For example, if `<zoom>` is `7`\nand `grid_precision` is `8`, you can zoom in up to level 15. Accepts 0-8. If 0, results\ndon't include the aggs layer.",
            }),
          grid_type: GlobalSearchMvtTypesGridTypeSchema.default('grid')
            .exactOptional()
            .openapi({
              description:
                'Determines the geometry type for features in the aggs layer. In the aggs layer,\neach feature represents a `geotile_grid` cell. If `grid, each feature is a polygon\nof the cells bounding box. If `point`, each feature is a Point that is the centroid\nof the cell.',
            }),
          query: TypesQueryDslQueryContainerSchema.exactOptional().openapi({
            description: 'The query DSL used to filter documents for the search.',
          }),
          runtime_mappings: TypesMappingRuntimeFieldsSchema.exactOptional().openapi({
            description:
              'Defines one or more runtime fields in the search request. These fields take\nprecedence over mapped fields with the same name.',
          }),
          size: z
            .number()
            .default(10000)
            .exactOptional()
            .openapi({
              description:
                "The maximum number of features to return in the hits layer. Accepts 0-10000.\nIf 0, results don't include the hits layer.",
            }),
          sort: TypesSortSchema.exactOptional().openapi({
            description:
              "Sort the features in the hits layer. By default, the API calculates a bounding\nbox for each feature. It sorts features based on this box's diagonal length,\nfrom longest to shortest.",
          }),
          track_total_hits: GlobalSearchTypesTrackHitsSchema.default('10000')
            .exactOptional()
            .openapi({
              description:
                'The number of hits matching the query to count accurately. If `true`, the exact number\nof hits is returned at the cost of some performance. If `false`, the response does\nnot include the total number of hits matching the query.',
            }),
          with_labels: z
            .boolean()
            .exactOptional()
            .openapi({
              description:
                'If `true`, the hits and aggs layers will contain additional point features representing\nsuggested label positions for the original features.\n\n* `Point` and `MultiPoint` features will have one of the points selected.\n* `Polygon` and `MultiPolygon` features will have a single point generated, either the centroid, if it is within the polygon, or another point within the polygon selected from the sorted triangle-tree.\n* `LineString` features will likewise provide a roughly central point selected from the triangle-tree.\n* The aggregation results will provide one central point for each aggregation bucket.\n\nAll attributes from the original features will also be copied to the new label features.\nIn addition, the new features will be distinguishable using the tag `_mvt_label_position`.',
            }),
        })
        .openapi({ required: [] }),
      examples: {
        SearchMvtRequestExample1: {
          description:
            'Run `GET museums/_mvt/location/13/4207/2692` to search an index for `location` values that intersect the `13/4207/2692` vector tile.\n',
          value:
            '{\n  "grid_agg": "geotile",\n  "grid_precision": 2,\n  "fields": [\n    "name",\n    "price"\n  ],\n  "query": {\n    "term": {\n      "included": true\n    }\n  },\n  "aggs": {\n    "min_price": {\n      "min": {\n        "field": "price"\n      }\n    },\n    "max_price": {\n      "max": {\n        "field": "price"\n      }\n    },\n    "avg_price": {\n      "avg": {\n        "field": "price"\n      }\n    }\n  }\n}',
        },
      },
    },
  },
}

