const SnapshotCreateRequestBody = {
  content: {
    'application/json': {
      schema: z
        .object({
          expand_wildcards: TypesExpandWildcardsSchema.default('all')
            .exactOptional()
            .openapi({
              description:
                'Determines how wildcard patterns in the `indices` parameter match data streams and indices.\nIt supports comma-separated values such as `open,hidden`.',
            }),
          feature_states: z
            .array(z.string())
            .exactOptional()
            .openapi({
              externalDocs: {
                url: 'https://www.elastic.co/docs/deploy-manage/tools/snapshot-and-restore#feature-state',
              },
              description:
                'The feature states to include in the snapshot.\nEach feature state includes one or more system indices containing related data.\nYou can view a list of eligible features using the get features API.\n\nIf `include_global_state` is `true`, all current feature states are included by default.\nIf `include_global_state` is `false`, no feature states are included by default.\n\nNote that specifying an empty array will result in the default behavior.\nTo exclude all feature states, regardless of the `include_global_state` value, specify an array with only the value `none` (`["none"]`).',
            }),
          ignore_unavailable: z
            .boolean()
            .default(false)
            .exactOptional()
            .openapi({
              description:
                'If `true`, the request ignores data streams and indices in `indices` that are missing or closed.\nIf `false`, the request returns an error for any data stream or index that is missing or closed.',
            }),
          include_global_state: z
            .boolean()
            .default(true)
            .exactOptional()
            .openapi({
              description:
                'If `true`, the current cluster state is included in the snapshot.\nThe cluster state includes persistent cluster settings, composable index templates, legacy index templates, ingest pipelines, and ILM policies.\nIt also includes data stored in system indices, such as Watches and task records (configurable via `feature_states`).',
            }),
          indices: TypesIndicesSchema.exactOptional().openapi({
            description:
              "A comma-separated list of data streams and indices to include in the snapshot.\nIt supports a multi-target syntax.\nThe default is an empty array (`[]`), which includes all regular data streams and regular indices.\nTo exclude all data streams and indices, use `-*`.\n\nYou can't use this parameter to include or exclude system indices or system data streams from a snapshot.\nUse `feature_states` instead.",
          }),
          metadata: TypesMetadataSchema.exactOptional().openapi({
            description:
              'Arbitrary metadata to the snapshot, such as a record of who took the snapshot, why it was taken, or any other useful data.\nIt can have any contents but it must be less than 1024 bytes.\nThis information is not automatically generated by Elasticsearch.',
          }),
          partial: z
            .boolean()
            .default(false)
            .exactOptional()
            .openapi({
              description:
                'If `true`, allows the snapshot to proceed even if some of the target shards are unavailable.\nIn this case, the resulting snapshot will not contain snapshots of the unavailable target shards, and will report its state as `PARTIAL`.\nAdditionally, if `true`, allows index metadata operations such as deletions while the snapshot is in progress.\nThis is almost always preferable to failing the snapshot completely when a single shard is unavailable, and blocking index metadata operations.\n\nIf `false`, the entire restore operation will fail if one or more indices included in the snapshot do not have all primary shards available, and index metadata operations such as deletions will be forbidden until the snapshot completes.',
            }),
        })
        .openapi({ required: [] }),
      examples: {
        SnapshotCreateRequestExample1: {
          description:
            'Run `PUT /_snapshot/my_repository/snapshot_2?wait_for_completion=true` to take a snapshot of `index_1` and `index_2`.',
          value:
            '{\n  "partial": true,\n  "indices": "index_1,index_2",\n  "ignore_unavailable": true,\n  "include_global_state": false,\n  "metadata": {\n    "taken_by": "user123",\n    "taken_because": "backup before upgrading"\n  }\n}',
        },
      },
    },
  },
}

