const WatcherExecuteWatchRequestBody = {
  content: {
    'application/json': {
      schema: z
        .object({
          action_modes: z
            .record(z.string(), WatcherTypesActionExecutionModeSchema)
            .exactOptional()
            .openapi({
              description:
                'Determines how to handle the watch actions as part of the watch execution.',
            }),
          alternative_input: z
            .record(z.string(), z.object({}))
            .exactOptional()
            .openapi({
              description:
                'When present, the watch uses this object as a payload instead of executing its own input.',
            }),
          ignore_condition: z
            .boolean()
            .default(false)
            .exactOptional()
            .openapi({
              description:
                'When set to `true`, the watch execution uses the always condition. This can also be specified as an HTTP parameter.',
            }),
          record_execution: z
            .boolean()
            .default(false)
            .exactOptional()
            .openapi({
              description:
                'When set to `true`, the watch record representing the watch execution result is persisted to the `.watcher-history` index for the current time.\nIn addition, the status of the watch is updated, possibly throttling subsequent runs.\nThis can also be specified as an HTTP parameter.',
            }),
          simulated_actions: WatcherTypesSimulatedActionsSchema.exactOptional(),
          trigger_data: WatcherTypesScheduleTriggerEventSchema.exactOptional().openapi({
            description:
              'This structure is parsed as the data of the trigger event that will be used during the watch execution.',
          }),
          watch: WatcherTypesWatchSchema.default('null')
            .exactOptional()
            .openapi({
              description:
                'When present, this watch is used instead of the one specified in the request.\nThis watch is not persisted to the index and `record_execution` cannot be set.',
            }),
        })
        .openapi({ required: [] }),
      examples: {
        WatcherExecuteRequestExample1: {
          summary: 'Run a watch',
          description:
            'Run `POST _watcher/watch/my_watch/_execute` to run a watch. The input defined in the watch is ignored and the `alternative_input` is used as the payload. The condition as defined by the watch is ignored and is assumed to evaluate to true. The `force_simulate` action forces the simulation of `my-action`. Forcing the simulation means that throttling is ignored and the watch is simulated by Watcher instead of being run normally.\n',
          value:
            '{\n  "trigger_data" : { \n    "triggered_time" : "now",\n    "scheduled_time" : "now"\n  },\n  "alternative_input" : { \n    "foo" : "bar"\n  },\n  "ignore_condition" : true, \n  "action_modes" : {\n    "my-action" : "force_simulate" \n  },\n  "record_execution" : true \n}',
        },
        WatcherExecuteRequestExample2: {
          summary: 'Run a watch with multiple action modes',
          description:
            'Run `POST _watcher/watch/my_watch/_execute` and set a different mode for each action.\n',
          value:
            '{\n  "action_modes" : {\n    "action1" : "force_simulate",\n    "action2" : "skip"\n  }\n}',
        },
        WatcherExecuteRequestExample3: {
          summary: 'Run a watch inline',
          description:
            'Run `POST _watcher/watch/_execute` to run a watch inline. All other settings for this API still apply when inlining a watch. In this example, while the inline watch defines a compare condition, during the execution this condition will be ignored.\n',
          value:
            '{\n  "watch" : {\n    "trigger" : { "schedule" : { "interval" : "10s" } },\n    "input" : {\n      "search" : {\n        "request" : {\n          "indices" : [ "logs" ],\n          "body" : {\n            "query" : {\n              "match" : { "message": "error" }\n            }\n          }\n        }\n      }\n    },\n    "condition" : {\n      "compare" : { "ctx.payload.hits.total" : { "gt" : 0 }}\n    },\n    "actions" : {\n      "log_error" : {\n        "logging" : {\n          "text" : "Found {{ctx.payload.hits.total}} errors in the logs"\n        }\n      }\n    }\n  }\n}',
        },
      },
    },
  },
}

const WatcherPutWatchRequestBody = {
  content: {
    'application/json': {
      schema: z
        .object({
          actions: z
            .record(z.string(), WatcherTypesActionSchema)
            .exactOptional()
            .openapi({
              description: 'The list of actions that will be run if the condition matches.',
            }),
          condition: WatcherTypesConditionContainerSchema.exactOptional().openapi({
            description: 'The condition that defines if the actions should be run.',
          }),
          input: WatcherTypesInputContainerSchema.exactOptional().openapi({
            description: 'The input that defines the input that loads the data for the watch.',
          }),
          metadata: TypesMetadataSchema.exactOptional().openapi({
            description: 'Metadata JSON that will be copied into the history entries.',
          }),
          throttle_period: TypesDurationSchema.exactOptional().openapi({
            description:
              'The minimum time between actions being run.\nThe default is 5 seconds.\nThis default can be changed in the config file with the setting `xpack.watcher.throttle.period.default_period`.\nIf both this value and the `throttle_period_in_millis` parameter are specified, Watcher uses the last parameter included in the request.',
          }),
          throttle_period_in_millis: TypesDurationValueUnitMillisSchema.exactOptional().openapi({
            description:
              'Minimum time in milliseconds between actions being run. Defaults to 5000. If both this value and the throttle_period parameter are specified, Watcher uses the last parameter included in the request.',
          }),
          transform: TypesTransformContainerSchema.exactOptional().openapi({
            description:
              'The transform that processes the watch payload to prepare it for the watch actions.',
          }),
          trigger: WatcherTypesTriggerContainerSchema.exactOptional().openapi({
            description: 'The trigger that defines when the watch should run.',
          }),
        })
        .openapi({ required: [] }),
      examples: {
        WatcherPutWatchRequestExample1: {
          description:
            'Run `PUT _watcher/watch/my-watch` add a watch. The watch schedule triggers every minute. The watch search input looks for any 404 HTTP responses that occurred in the last five minutes. The watch condition checks if any search hits where found. When found, the watch action sends an email to an administrator.\n',
          value:
            '{\n  "trigger" : {\n    "schedule" : { "cron" : "0 0/1 * * * ?" }\n  },\n  "input" : {\n    "search" : {\n      "request" : {\n        "indices" : [\n          "logstash*"\n        ],\n        "body" : {\n          "query" : {\n            "bool" : {\n              "must" : {\n                "match": {\n                  "response": 404\n                }\n              },\n              "filter" : {\n                "range": {\n                  "@timestamp": {\n                    "from": "{{ctx.trigger.scheduled_time}}||-5m",\n                    "to": "{{ctx.trigger.triggered_time}}"\n                  }\n                }\n              }\n            }\n          }\n        }\n      }\n    }\n  },\n  "condition" : {\n    "compare" : { "ctx.payload.hits.total" : { "gt" : 0 }}\n  },\n  "actions" : {\n    "email_admin" : {\n      "email" : {\n        "to" : "admin@domain.host.com",\n        "subject" : "404 recently encountered"\n      }\n    }\n  }\n}',
        },
      },
    },
  },
  required: true,
}

