export const getAsyncSearchIdRoute = createRoute({
  method: 'get',
  path: '/_async_search/{id}',
  tags: ['search'],
  summary: 'Get async search results',
  description:
    'Retrieve the results of a previously submitted asynchronous search request.\nIf the Elasticsearch security features are enabled, access to the results of a specific async search is restricted to the user or API key that submitted it.',
  operationId: 'async-search-get',
  request: {
    params: z.object({
      id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'id',
          description: 'A unique identifier for the async search.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      keep_alive: TypesDurationSchema.openapi({
        param: {
          in: 'query',
          name: 'keep_alive',
          description:
            'The length of time that the async search should be available in the cluster.\nWhen not specified, the `keep_alive` set with the corresponding submit async request will be used.\nOtherwise, it is possible to override the value and extend the validity of the request.\nWhen this period expires, the search, if still running, is cancelled.\nIf the search is completed, its saved results are deleted.',
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Duration' },
          style: 'form',
          required: false,
        },
      }).exactOptional(),
      typed_keys: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'typed_keys',
            description:
              'Specify whether aggregation and suggester names should be prefixed by their respective types in the response',
            deprecated: false,
            schema: { type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      wait_for_completion_timeout: TypesDurationSchema.openapi({
        param: {
          in: 'query',
          name: 'wait_for_completion_timeout',
          description:
            'Specifies to wait for the search to be completed up until the provided timeout.\nFinal results will be returned if available before the timeout expires, otherwise the currently available results will be returned once the timeout expires.\nBy default no timeout is set meaning that the currently available results will be returned without any additional wait.',
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Duration' },
          style: 'form',
          required: false,
        },
      }).exactOptional(),
      return_intermediate_results: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'return_intermediate_results',
            description:
              'Specifies whether the response should contain intermediate results if the query is still running when the wait_for_completion_timeout\nexpires or if no wait_for_completion_timeout is specified.\nIf true and the search is still running, the search response\nwill include any hits and partial aggregations that are available.\nIf false and the search is still running, the search response will not include any hits (but possibly include\ntotal hits) nor will include any partial aggregations.\nWhen not specified, the intermediate results are returned for running queries.',
            deprecated: false,
            schema: { type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: AsyncSearchTypesAsyncSearchDocumentResponseBaseSchema,
          examples: {
            AsyncSearchGetResponseExample1: {
              description:
                'A succesful response from `GET /_async_search/FmRldE8zREVEUzA2ZVpUeGs2ejJFUFEaMkZ5QTVrSTZSaVN3WlNFVmtlWHJsdzoxMDc=`.',
              value:
                '{\n  "id" : "FmRldE8zREVEUzA2ZVpUeGs2ejJFUFEaMkZ5QTVrSTZSaVN3WlNFVmtlWHJsdzoxMDc=",\n  "is_partial" : false, \n  "is_running" : false, \n  "start_time_in_millis" : 1583945890986,\n  "expiration_time_in_millis" : 1584377890986, \n  "completion_time_in_millis" : 1583945903130, \n  "response" : {\n    "took" : 12144,\n    "timed_out" : false,\n    "num_reduce_phases" : 46, \n    "_shards" : {\n      "total" : 562,\n      "successful" : 188, \n      "skipped" : 0,\n      "failed" : 0\n    },\n    "hits" : {\n      "total" : {\n        "value" : 456433,\n        "relation" : "eq"\n      },\n      "max_score" : null,\n      "hits" : [ ]\n    },\n    "aggregations" : { \n      "sale_date" :  {\n        "buckets" : []\n      }\n    }\n  }\n}',
            },
          },
        },
      },
    },
    400: {
      description: '',
      content: {
        'application/json': { schema: AsyncSearchTypesAsyncSearchResponseExceptionSchema },
      },
    },
    404: {
      description: '',
      content: {
        'application/json': { schema: AsyncSearchTypesAsyncSearchResponseExceptionSchema },
      },
    },
    429: {
      description: '',
      content: {
        'application/json': { schema: AsyncSearchTypesAsyncSearchResponseExceptionSchema },
      },
    },
    500: {
      description: '',
      content: {
        'application/json': { schema: AsyncSearchTypesAsyncSearchResponseExceptionSchema },
      },
    },
  },
})

