      search_type: AsyncSearchSubmitSearchTypeParamsSchema,
      stats: AsyncSearchSubmitStatsParamsSchema,
      stored_fields: AsyncSearchSubmitStoredFieldsParamsSchema,
      suggest_field: AsyncSearchSubmitSuggestFieldParamsSchema,
      suggest_mode: AsyncSearchSubmitSuggestModeParamsSchema,
      suggest_size: AsyncSearchSubmitSuggestSizeParamsSchema,
      suggest_text: AsyncSearchSubmitSuggestTextParamsSchema,
      terminate_after: AsyncSearchSubmitTerminateAfterParamsSchema,
      timeout: AsyncSearchSubmitTimeoutParamsSchema,
      track_total_hits: AsyncSearchSubmitTrackTotalHitsParamsSchema,
      track_scores: AsyncSearchSubmitTrackScoresParamsSchema,
      typed_keys: AsyncSearchSubmitTypedKeysParamsSchema,
      rest_total_hits_as_int: AsyncSearchSubmitRestTotalHitsAsIntParamsSchema,
      version: AsyncSearchSubmitVersionParamsSchema,
      _source: AsyncSearchSubmitSourceParamsSchema,
      _source_excludes: AsyncSearchSubmitSourceExcludesParamsSchema,
