export const getCatHealthRoute = createRoute({
  method: 'get',
  path: '/_cat/health',
  tags: ['cat'],
  summary: 'Get a compact cluster health summary',
  description:
    'IMPORTANT: CAT APIs are only intended for human consumption using the command line or Kibana console.\nThey are not intended for use by applications. For application consumption, use the cluster health API.\nThis API is often used to check malfunctioning clusters.\nTo help you track cluster health alongside log files and alerting systems, the API returns timestamps in two formats:\n`HH:MM:SS`, which is human-readable but includes no date information;\n`Unix epoch time`, which is machine-sortable and includes date information.\nThe latter format is useful for cluster recoveries that take multiple days.\nYou can use the cat health API to verify cluster health across multiple nodes.\nYou also can use the API to track the recovery of a large cluster over a longer period of time.\n\n## Required authorization\n\n* Cluster privileges: `monitor`\n',
  operationId: 'cat-health',
  request: {
    query: z.object({
      ts: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'ts',
            description: 'If true, returns `HH:MM:SS` and Unix epoch timestamps.',
            deprecated: false,
            schema: { default: true, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      h: CatTypesCatHealthColumnsSchema.openapi({
        param: {
          in: 'query',
          name: 'h',
          description:
            'A comma-separated list of columns names to display. It supports simple wildcards.',
          deprecated: false,
          schema: { $ref: '#/components/schemas/cat._types.CatHealthColumns' },
          style: 'form',
          required: false,
        },
      }).exactOptional(),
      s: TypesNamesSchema.openapi({
        param: {
          in: 'query',
          name: 's',
          description:
            'List of columns that determine how the table should be sorted.\nSorting defaults to ascending and can be changed by setting `:asc`\nor `:desc` as a suffix to the column name.',
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Names' },
          style: 'form',
          required: false,
        },
      }).exactOptional(),
      format: SpecUtilsCommonCatQueryParametersFormatParamsSchema,
      help: SpecUtilsCommonCatQueryParametersHelpParamsSchema,
      v: SpecUtilsCommonCatQueryParametersVParamsSchema,
      bytes: SpecUtilsCommonCatQueryParametersBytesParamsSchema,
      time: SpecUtilsCommonCatQueryParametersTimeParamsSchema,
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z.array(CatHealthHealthRecordSchema),
          examples: {
            CatHealthResponseExample1: {
              description:
                'A successful response from `GET /_cat/health?v=true&format=json`. By default, it returns `HH:MM:SS` and Unix epoch timestamps.\n',
              value:
                '[\n  {\n    "epoch": "1475871424",\n    "timestamp": "16:17:04",\n    "cluster": "elasticsearch",\n    "status": "green",\n    "node.total": "1",\n    "node.data": "1",\n    "shards": "1",\n    "pri": "1",\n    "relo": "0",\n    "init": "0",\n    "unassign": "0",\n    "unassign.pri": "0",\n    "pending_tasks": "0",\n    "max_task_wait_time": "-",\n    "active_shards_percent": "100.0%"\n  }\n]',
            },
          },
        },
      },
    },
  },
})

