export const getCatRecoveryRoute = createRoute({
  method: 'get',
  path: '/_cat/recovery',
  tags: ['cat'],
  summary: 'Get shard recovery information',
  description:
    'Get information about ongoing and completed shard recoveries.\nShard recovery is the process of initializing a shard copy, such as restoring a primary shard from a snapshot or syncing a replica shard from a primary shard. When a shard recovery completes, the recovered shard is available for search and indexing.\nFor data streams, the API returns information about the stream’s backing indices.\nIMPORTANT: cat APIs are only intended for human consumption using the command line or Kibana console. They are not intended for use by applications. For application consumption, use the index recovery API.\n\n## Required authorization\n\n* Index privileges: `monitor`\n* Cluster privileges: `monitor`\n',
  operationId: 'cat-recovery',
  request: {
    query: z.object({
      active_only: CatRecoveryActiveOnlyParamsSchema,
      detailed: CatRecoveryDetailedParamsSchema,
      index: CatRecoveryIndex_2ParamsSchema,
      h: CatRecoveryHParamsSchema,
      s: CatRecoverySParamsSchema,
      format: SpecUtilsCommonCatQueryParametersFormatParamsSchema,
      help: SpecUtilsCommonCatQueryParametersHelpParamsSchema,
      v: SpecUtilsCommonCatQueryParametersVParamsSchema,
      bytes: SpecUtilsCommonCatQueryParametersBytesParamsSchema,
      time: SpecUtilsCommonCatQueryParametersTimeParamsSchema,
    }),
  },
  responses: { 200: CatRecovery_200Response },
})

