export const putIndexCcrFollowRoute = createRoute({
  method: 'put',
  path: '/{index}/_ccr/follow',
  tags: ['ccr'],
  summary: 'Create a follower',
  description:
    'Create a cross-cluster replication follower index that follows a specific leader index.\nWhen the API returns, the follower index exists and cross-cluster replication starts replicating operations from the leader index to the follower index.',
  operationId: 'ccr-follow',
  request: {
    params: z.object({
      index: TypesIndexNameSchema.openapi({
        param: {
          in: 'path',
          name: 'index',
          description: 'The name of the follower index.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.IndexName' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      master_timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'master_timeout',
            description: 'Period to wait for a connection to the master node.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
      wait_for_active_shards: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(TypesWaitForActiveShardsSchema)
        .default('0')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'wait_for_active_shards',
            description:
              'Specifies the number of shards to wait on being active before responding. This defaults to waiting on none of the shards to be\nactive.\nA shard must be restored from the leader index before being active. Restoring a follower shard requires transferring all the\nremote Lucene segment files to the follower index.',
            deprecated: false,
            schema: {
              default: '0',
              allOf: [{ $ref: '#/components/schemas/_types.WaitForActiveShards' }],
            },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              data_stream_name: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'If the leader index is part of a data stream, the name to which the local data stream for the followed index should be renamed.',
                }),
              leader_index: TypesIndexNameSchema.openapi({
                description: 'The name of the index in the leader cluster to follow.',
              }),
              max_outstanding_read_requests: z
                .number()
                .exactOptional()
                .openapi({
                  description:
                    'The maximum number of outstanding reads requests from the remote cluster.',
                }),
              max_outstanding_write_requests: z
                .number()
                .exactOptional()
                .openapi({
                  description: 'The maximum number of outstanding write requests on the follower.',
                }),
              max_read_request_operation_count: z
                .number()
                .exactOptional()
                .openapi({
                  description:
                    'The maximum number of operations to pull per read from the remote cluster.',
                }),
              max_read_request_size: TypesByteSizeSchema.exactOptional().openapi({
                description:
                  'The maximum size in bytes of per read of a batch of operations pulled from the remote cluster.',
              }),
              max_retry_delay: TypesDurationSchema.exactOptional().openapi({
                description:
                  'The maximum time to wait before retrying an operation that failed exceptionally. An exponential backoff strategy is employed when\nretrying.',
              }),
              max_write_buffer_count: z
                .number()
                .exactOptional()
                .openapi({
                  description:
                    'The maximum number of operations that can be queued for writing. When this limit is reached, reads from the remote cluster will be\ndeferred until the number of queued operations goes below the limit.',
                }),
              max_write_buffer_size: TypesByteSizeSchema.exactOptional().openapi({
                description:
                  'The maximum total bytes of operations that can be queued for writing. When this limit is reached, reads from the remote cluster will\nbe deferred until the total bytes of queued operations goes below the limit.',
              }),
              max_write_request_operation_count: z
                .number()
                .exactOptional()
                .openapi({
                  description:
                    'The maximum number of operations per bulk write request executed on the follower.',
                }),
              max_write_request_size: TypesByteSizeSchema.exactOptional().openapi({
                description:
                  'The maximum total bytes of operations per bulk write request executed on the follower.',
              }),
              read_poll_timeout: TypesDurationSchema.exactOptional().openapi({
                description:
                  'The maximum time to wait for new operations on the remote cluster when the follower index is synchronized with the leader index.\nWhen the timeout has elapsed, the poll for operations will return to the follower so that it can update some statistics.\nThen the follower will immediately attempt to read from the leader again.',
              }),
              remote_cluster: z
                .string()
                .openapi({ description: 'The remote cluster containing the leader index.' }),
              settings: IndicesTypesIndexSettingsSchema.exactOptional().openapi({
                description: 'Settings to override from the leader index.',
              }),
            })
            .openapi({ required: ['leader_index', 'remote_cluster'] }),
          examples: {
            CreateFollowIndexRequestExample1: {
              description:
                'Run `PUT /follower_index/_ccr/follow?wait_for_active_shards=1` to create a follower index named `follower_index`.',
              value:
                '{\n  "remote_cluster" : "remote_cluster",\n  "leader_index" : "leader_index",\n  "settings": {\n    "index.number_of_replicas": 0\n  },\n  "max_read_request_operation_count" : 1024,\n  "max_outstanding_read_requests" : 16,\n  "max_read_request_size" : "1024k",\n  "max_write_request_operation_count" : 32768,\n  "max_write_request_size" : "16k",\n  "max_outstanding_write_requests" : 8,\n  "max_write_buffer_count" : 512,\n  "max_write_buffer_size" : "512k",\n  "max_retry_delay" : "10s",\n  "read_poll_timeout" : "30s"\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              follow_index_created: z.boolean(),
              follow_index_shards_acked: z.boolean(),
              index_following_started: z.boolean(),
            })
            .openapi({
              required: [
                'follow_index_created',
                'follow_index_shards_acked',
                'index_following_started',
              ],
            }),
          examples: {
            CreateFollowIndexResponseExample1: {
              description:
                'A successful response from `PUT /follower_index/_ccr/follow?wait_for_active_shards=1`.',
              value:
                '{\n  "follow_index_created" : true,\n  "follow_index_shards_acked" : true,\n  "index_following_started" : true\n}',
            },
          },
        },
      },
    },
  },
})

