export const postIndexCcrForgetFollowerRoute = createRoute({
  method: 'post',
  path: '/{index}/_ccr/forget_follower',
  tags: ['ccr'],
  summary: 'Forget a follower',
  description:
    'Remove the cross-cluster replication follower retention leases from the leader.\n\nA following index takes out retention leases on its leader index.\nThese leases are used to increase the likelihood that the shards of the leader index retain the history of operations that the shards of the following index need to run replication.\nWhen a follower index is converted to a regular index by the unfollow API (either by directly calling the API or by index lifecycle management tasks), these leases are removed.\nHowever, removal of the leases can fail, for example when the remote cluster containing the leader index is unavailable.\nWhile the leases will eventually expire on their own, their extended existence can cause the leader index to hold more history than necessary and prevent index lifecycle management from performing some operations on the leader index.\nThis API exists to enable manually removing the leases when the unfollow API is unable to do so.\n\nNOTE: This API does not stop replication by a following index. If you use this API with a follower index that is still actively following, the following index will add back retention leases on the leader.\nThe only purpose of this API is to handle the case of failure to remove the following retention leases after the unfollow API is invoked.',
  externalDocs: {
    description: 'About cross-cluster replication',
    url: 'https://www.elastic.co/docs/deploy-manage/tools/cross-cluster-replication',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/ccr-post-forget-follower.html',
  },
  operationId: 'ccr-forget-follower',
  request: {
    params: z.object({
      index: TypesIndexNameSchema.openapi({
        param: {
          in: 'path',
          name: 'index',
          description:
            'Name of the leader index for which specified follower retention leases should be removed',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.IndexName' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'timeout',
            description:
              'Period to wait for a response. If no response is received before the timeout expires, the request fails and returns an error.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              follower_cluster: z.string().exactOptional(),
              follower_index: TypesIndexNameSchema.exactOptional(),
              follower_index_uuid: TypesUuidSchema.exactOptional(),
              leader_remote_cluster: z.string().exactOptional(),
            })
            .openapi({ required: [] }),
          examples: {
            ForgetFollowerIndexRequestExample1: {
              description: 'Run `POST /<leader_index>/_ccr/forget_follower`.',
              value:
                '{\n  "follower_cluster" : "<follower_cluster>",\n  "follower_index" : "<follower_index>",\n  "follower_index_uuid" : "<follower_index_uuid>",\n  "leader_remote_cluster" : "<leader_remote_cluster>"\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({ _shards: TypesShardStatisticsSchema })
            .openapi({ required: ['_shards'] }),
          examples: {
            ForgetFollowerIndexResponseExample1: {
              description:
                'A successful response for removing the follower retention leases from the leader index.\n',
              value:
                '{\n  "_shards" : {\n    "total" : 1,\n    "successful" : 1,\n    "failed" : 0,\n    "failures" : [ ]\n  }\n}',
            },
          },
        },
      },
    },
  },
})

