export const getCountRoute = createRoute({
  method: 'get',
  path: '/_count',
  tags: ['search'],
  summary: 'Count search results',
  description:
    'Get the number of documents matching a query.\n\nThe query can be provided either by using a simple query string as a parameter, or by defining Query DSL within the request body.\nThe query is optional. When no query is provided, the API uses `match_all` to count all the documents.\n\nThe count API supports multi-target syntax. You can run a single count API search across multiple data streams and indices.\n\nThe operation is broadcast across all shards.\nFor each shard ID group, a replica is chosen and the search is run against it.\nThis means that replicas increase the scalability of the count.\n\n## Required authorization\n\n* Index privileges: `read`\n',
  operationId: 'count-1',
  request: {
    query: z.object({
      allow_no_indices: CountAllowNoIndicesParamsSchema,
      analyzer: CountAnalyzerParamsSchema,
      analyze_wildcard: CountAnalyzeWildcardParamsSchema,
      default_operator: CountDefaultOperatorParamsSchema,
      df: CountDfParamsSchema,
      expand_wildcards: CountExpandWildcardsParamsSchema,
      ignore_throttled: CountIgnoreThrottledParamsSchema,
      ignore_unavailable: CountIgnoreUnavailableParamsSchema,
      lenient: CountLenientParamsSchema,
      min_score: CountMinScoreParamsSchema,
      preference: CountPreferenceParamsSchema,
      routing: CountRoutingParamsSchema,
      stats: CountStatsParamsSchema,
      terminate_after: CountTerminateAfterParamsSchema,
      q: CountQParamsSchema,
    }),
    body: CountRequestBody,
  },
  responses: { 200: Count_200Response },
})

