export const postEncryptionResetRoute = createRoute({
  method: 'post',
  path: '/_encryption/_reset',
  tags: ['security'],
  summary: 'Reset the project encryption key',
  description:
    'Destroy the current project encryption key (PEK) and generate a new one.\nThis is the recovery path for when the on-disk encrypted PEK becomes permanently\ninaccessible, for example because the key encryption material protecting it was lost.\n\nAll data that was encrypted under the destroyed key becomes permanently unrecoverable.\nEach feature that stores encrypted data decides how to handle its own data during the\nreset: some features drop the encrypted values entirely, while others preserve the rest\nof the affected data and only clear the values that can no longer be decrypted.\n\nBecause this operation causes permanent data loss, it requires the `accept_data_loss`\nquery parameter to be set to `true`.',
  operationId: 'encryption-reset',
  request: {
    query: z.object({
      accept_data_loss: z
        .stringbool()
        .openapi({
          param: {
            in: 'query',
            name: 'accept_data_loss',
            description:
              'Acknowledge that resetting the project encryption key permanently destroys all data\nthat was encrypted under the current key.\nThe request fails if this is not set to `true`.',
            required: true,
            deprecated: false,
            schema: { type: 'boolean' },
            style: 'form',
          },
        }),
      master_timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'master_timeout',
            description:
              'The period to wait for a connection to the master node.\nIf no response is received before the timeout expires, the request fails and returns an error.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
      timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'timeout',
            description:
              'The period to wait for a response.\nIf no response is received before the timeout expires, the request fails and returns an error.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: TypesAcknowledgedResponseBaseSchema,
          examples: {
            EncryptionResetResponseExample1: {
              summary: 'Reset the project encryption key',
              description:
                'A successful response from `POST /_encryption/_reset?accept_data_loss=true`.\n',
              value: '{\n  "acknowledged": true\n}',
            },
          },
        },
      },
    },
  },
})

