export const getEqlSearchStatusIdRoute = createRoute({
  method: 'get',
  path: '/_eql/search/status/{id}',
  tags: ['eql'],
  summary: 'Get the async EQL status',
  description:
    'Get the current status for an async EQL search or a stored synchronous EQL search without returning results.',
  operationId: 'eql-get-status',
  request: {
    params: z.object({
      id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'id',
          description: 'Identifier for the search.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              id: TypesIdSchema.openapi({ description: 'Identifier for the search.' }),
              is_partial: z
                .boolean()
                .openapi({
                  description:
                    'If true, the search request is still executing. If false, the search is completed.',
                }),
              is_running: z
                .boolean()
                .openapi({
                  description:
                    'If true, the response does not contain complete search results. This could be because either the search is still running (is_running status is false), or because it is already completed (is_running status is true) and results are partial due to failures or timeouts.',
                }),
              start_time_in_millis: TypesEpochTimeUnitMillisSchema.exactOptional().openapi({
                description:
                  'For a running search shows a timestamp when the eql search started, in milliseconds since the Unix epoch.',
              }),
              expiration_time_in_millis: TypesEpochTimeUnitMillisSchema.exactOptional().openapi({
                description:
                  'Shows a timestamp when the eql search will be expired, in milliseconds since the Unix epoch. When this time is reached, the search and its results are deleted, even if the search is still ongoing.',
              }),
              completion_status: z
                .number()
                .exactOptional()
                .openapi({
                  description:
                    'For a completed search shows the http status code of the completed search.',
                }),
            })
            .openapi({ required: ['id', 'is_partial', 'is_running'] }),
          examples: {
            EqlGetStatusResponseExample1: {
              description:
                'A successful response for getting status information for an async EQL search.',
              value:
                '{\n  "id": "FmNJRUZ1YWZCU3dHY1BIOUhaenVSRkEaaXFlZ3h4c1RTWFNocDdnY2FSaERnUTozNDE=",\n  "is_running" : true,\n  "is_partial" : true,\n  "start_time_in_millis" : 1611690235000,\n  "expiration_time_in_millis" : 1611690295000\n}',
            },
          },
        },
      },
    },
  },
})

