export const postQueryAsyncRoute = createRoute({
  method: 'post',
  path: '/_query/async',
  tags: ['esql'],
  summary: 'Run an async ES|QL query',
  description:
    'Asynchronously run an ES|QL (Elasticsearch query language) query, monitor its progress, and retrieve results when they become available.\n\nThe API accepts the same parameters and request body as the synchronous query API, along with additional async related properties.\n\n## Required authorization\n\n* Index privileges: `read`\n',
  externalDocs: {
    description: 'More about ES|QL reference',
    url: 'https://www.elastic.co/docs/explore-analyze/query-filter/languages/esql',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/esql-async-query-api.html',
  },
  operationId: 'esql-async-query',
  request: {
    query: z.object({
      allow_partial_results: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'allow_partial_results',
            description:
              'If `true`, partial results will be returned if there are shard failures, but the query can continue to execute on other clusters and shards.\nIf `false`, the query will fail if there are any failures.\n\nTo override the default behavior, you can set the `esql.query.allow_partial_results` cluster setting to `false`.',
            deprecated: false,
            schema: { default: true, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      delimiter: z
        .string()
        .default(',')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'delimiter',
            description:
              'The character to use between values within a CSV row.\nIt is valid only for the CSV format.',
            deprecated: false,
            schema: { default: ',', type: 'string' },
            style: 'form',
            required: false,
          },
        }),
      drop_null_columns: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'drop_null_columns',
            description:
              'Indicates whether columns that are entirely `null` will be removed from the `columns` and `values` portion of the results.\nIf `true`, the response will include an extra section under the name `all_columns` which has the name of all the columns.',
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      format: EsqlTypesEsqlFormatSchema.openapi({
        param: {
          in: 'query',
          name: 'format',
          description:
            "A short version of the Accept header, e.g. json, yaml.\n\n`csv`, `tsv`, and `txt` formats will return results in a tabular format, excluding other metadata fields from the response.\n\nFor async requests, nothing will be returned if the async query doesn't finish within the timeout.\nThe query ID and running status are available in the `X-Elasticsearch-Async-Id` and `X-Elasticsearch-Async-Is-Running` HTTP headers of the response, respectively.",
          deprecated: false,
          schema: { $ref: '#/components/schemas/esql._types.EsqlFormat' },
          style: 'form',
          required: false,
        },
      }).exactOptional(),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              columnar: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'By default, ES|QL returns results as rows. For example, FROM returns each individual document as one row. For the JSON, YAML, CBOR and smile formats, ES|QL can return the results in a columnar fashion where one row represents all the values of a certain column in the results.',
                }),
              filter: TypesQueryDslQueryContainerSchema.exactOptional().openapi({
                description:
                  'Specify a Query DSL query in the filter parameter to filter the set of documents that an ES|QL query runs on.',
              }),
              time_zone: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Sets the default timezone of the query.',
                  'x-state': 'Generally available; Added in 9.4.0',
                }),
              locale: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Returns results (especially dates) formatted per the conventions of the locale.',
                }),
              params: EsqlTypesESQLParamsSchema.exactOptional().openapi({
                description:
                  'To avoid any attempts of hacking or code injection, extract the values in a separate list of parameters. Use question mark placeholders (?) in the query string for each of the parameters.',
              }),
              profile: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'If provided and `true` the response will include an extra `profile` object\nwith information on how the query was executed. This information is for human debugging\nand its format can change at any time but it can give some insight into the performance\nof each part of the query.',
                }),
              query: z
                .string()
                .openapi({
                  description:
                    'The ES|QL query API accepts an ES|QL query string in the query parameter, runs it, and returns the results.',
                }),
              tables: z
                .record(z.string(), z.record(z.string(), EsqlTypesTableValuesContainerSchema))
                .exactOptional()
                .openapi({
                  description:
                    'Tables to use with the LOOKUP operation. The top level key is the table\nname and the next level key is the column name.',
                }),
              include_ccs_metadata: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'When set to `true` and performing a cross-cluster/cross-project query, the response will include an extra `_clusters`\nobject with information about the clusters that participated in the search along with info such as shards\ncount.',
                }),
              include_execution_metadata: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'When set to `true`, the response will include an extra `_clusters`\nobject with information about the clusters that participated in the search along with info such as shards\ncount.\nThis is similar to `include_ccs_metadata`, but it also returns metadata when the query is not CCS/CPS',
                }),
              wait_for_completion_timeout: TypesDurationSchema.default('1s')
                .exactOptional()
                .openapi({
                  description:
                    'The period to wait for the request to finish.\nBy default, the request waits for 1 second for the query results.\nIf the query completes during this period, results are returned\nOtherwise, a query ID is returned that can later be used to retrieve the results.',
                }),
              keep_alive: TypesDurationSchema.default('5d')
                .exactOptional()
                .openapi({
                  description:
                    'The period for which the query and its results are stored in the cluster.\nThe default period is five days.\nWhen this period expires, the query and its results are deleted, even if the query is still ongoing.\nIf the `keep_on_completion` parameter is false, Elasticsearch only stores async queries that do not complete within the period set by the `wait_for_completion_timeout` parameter, regardless of this value.',
                }),
              keep_on_completion: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Indicates whether the query and its results are stored in the cluster.\nIf false, the query and its results are stored in the cluster only if the request does not complete during the period set by the `wait_for_completion_timeout` parameter.',
                }),
              settings: EsqlTypesEsqlQuerySettingsSchema.exactOptional().openapi({
                description:
                  'Per-query settings, the request-body equivalent of the in-query `SET` command.\nFor example, `time_zone` can be supplied here instead of as a top-level field.',
                'x-state': 'Generally available; Added in 9.5.0',
              }),
            })
            .openapi({ required: ['query'] }),
          examples: {
            AsyncQueryRequestExample1: {
              value:
                '{\n  "query": """\n    FROM library,remote-*:library\n    | EVAL year = DATE_TRUNC(1 YEARS, release_date)\n    | STATS MAX(page_count) BY year\n    | SORT year\n    | LIMIT 5\n  """,\n  "wait_for_completion_timeout": "2s",\n  "include_ccs_metadata": true\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: EsqlTypesAsyncEsqlResultSchema } },
    },
  },
})

