export const putQueryViewNameRoute = createRoute({
  method: 'put',
  path: '/_query/view/{name}',
  tags: ['esql'],
  summary: 'Create or update an ES|QL view',
  description:
    'Stores an ES|QL query that runs whenever the view is referenced.\nA query that cannot be parsed is rejected. Replacing a reserved view fails.\n\n## Required authorization\n\n* Index privileges: `create_view`\n',
  externalDocs: {
    description: 'Define reusable queries with ES|QL views',
    url: 'https://www.elastic.co/docs/reference/query-languages/esql/esql-views',
  },
  operationId: 'esql-put-view',
  request: {
    params: z.object({
      name: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'name',
          description: 'The view name to create or update.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      validate: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'validate',
            description:
              'Whether to analyze the view query and return a warning when validation fails.\n\nValidation reports an unknown index or column, including an index the caller cannot read.\nThe view is saved even when validation reports a problem.\nFailures unrelated to the query, such as an overloaded cluster, produce no warning.',
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            'x-state': 'Generally available; Added in 9.7.0',
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              query: z
                .string()
                .openapi({
                  description:
                    'The ES|QL query string that defines the view. A query that cannot be parsed is rejected.',
                }),
              description: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'A free-text description of the view.',
                  'x-state': 'Generally available; Added in 9.6.0',
                }),
            })
            .openapi({ required: ['query'] }),
          examples: {
            PutViewRequestExample1: {
              summary: 'Create a view of country counts',
              description:
                'Create a view that normalizes country names and counts addresses by country.\n',
              value:
                '{\n  "query": """\n    FROM addresses\n    | RENAME city.country.name AS country\n    | EVAL country = CASE(country == "United States of America", "United States", country)\n    | STATS count=COUNT() BY country\n  """,\n  "description": "Address counts by country"\n}',
            },
            PutViewRequestExample2: {
              summary: 'Create a view and validate the query',
              description:
                'Analyze the view query before saving it. When the query uses an unknown index or column, the response includes a warning and the view is still saved.\n',
              value:
                '{\n  "query": """\n    FROM addresses\n    | RENAME city.country.name AS country\n    | EVAL country = CASE(country == "United States of America", "United States", country)\n    | STATS count=COUNT() BY country\n  """,\n  "description": "Address counts by country"\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: TypesAcknowledgedResponseBaseSchema,
          examples: {
            PutViewResponseExample1: {
              summary: 'View created',
              description: 'The view definition was stored successfully.',
              value: '{\n  "acknowledged": true\n}',
            },
          },
        },
      },
    },
  },
})

