export const postQueryRoute = createRoute({
  method: 'post',
  path: '/_query',
  tags: ['esql'],
  summary: 'Run an ES|QL query',
  description:
    'Get search results for an ES|QL (Elasticsearch query language) query.\n\n## Required authorization\n\n* Index privileges: `read`\n',
  externalDocs: {
    description: 'More about ES|QL reference',
    url: 'https://www.elastic.co/docs/explore-analyze/query-filter/languages/esql',
  },
  operationId: 'esql-query',
  request: {
    query: z.object({
      format: EsqlTypesEsqlFormatSchema.openapi({
        param: {
          in: 'query',
          name: 'format',
          description:
            'A short version of the Accept header, e.g. json, yaml.\n\n`csv`, `tsv`, and `txt` formats will return results in a tabular format, excluding other metadata fields from the response.',
          deprecated: false,
          schema: { $ref: '#/components/schemas/esql._types.EsqlFormat' },
          style: 'form',
          required: false,
        },
      }).exactOptional(),
      delimiter: z
        .string()
        .default(',')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'delimiter',
            description:
              'The character to use between values within a CSV row. Only valid for the CSV format.',
            deprecated: false,
            schema: { default: ',', type: 'string' },
            style: 'form',
            required: false,
          },
        }),
      drop_null_columns: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'drop_null_columns',
            description:
              'Should columns that are entirely `null` be removed from the `columns` and `values` portion of the results?\nDefaults to `false`. If `true` then the response will include an extra section under the name `all_columns` which has the name of all columns.',
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      allow_partial_results: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'allow_partial_results',
            description:
              'If `true`, partial results will be returned if there are shard failures, but the query can continue to execute on other clusters and shards.\nIf `false`, the query will fail if there are any failures.\n\nTo override the default behavior, you can set the `esql.query.allow_partial_results` cluster setting to `false`.',
            deprecated: false,
            schema: { default: true, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              columnar: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'By default, ES|QL returns results as rows. For example, FROM returns each individual document as one row. For the JSON, YAML, CBOR and smile formats, ES|QL can return the results in a columnar fashion where one row represents all the values of a certain column in the results.',
                }),
              filter: TypesQueryDslQueryContainerSchema.exactOptional().openapi({
                description:
                  'Specify a Query DSL query in the filter parameter to filter the set of documents that an ES|QL query runs on.',
              }),
              time_zone: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Sets the default timezone of the query.',
                  'x-state': 'Generally available; Added in 9.4.0',
                }),
              locale: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Returns results (especially dates) formatted per the conventions of the locale.',
                }),
              params: EsqlTypesESQLParamsSchema.exactOptional().openapi({
                description:
                  'To avoid any attempts of hacking or code injection, extract the values in a separate list of parameters. Use question mark placeholders (?) in the query string for each of the parameters.',
              }),
              profile: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'If provided and `true` the response will include an extra `profile` object\nwith information on how the query was executed. This information is for human debugging\nand its format can change at any time but it can give some insight into the performance\nof each part of the query.',
                }),
              query: z
                .string()
                .openapi({
                  description:
                    'The ES|QL query API accepts an ES|QL query string in the query parameter, runs it, and returns the results.',
                }),
              tables: z
                .record(z.string(), z.record(z.string(), EsqlTypesTableValuesContainerSchema))
                .exactOptional()
                .openapi({
                  description:
                    'Tables to use with the LOOKUP operation. The top level key is the table\nname and the next level key is the column name.',
                }),
              include_ccs_metadata: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'When set to `true` and performing a cross-cluster/cross-project query, the response will include an extra `_clusters`\nobject with information about the clusters that participated in the search along with info such as shards\ncount.',
                }),
              include_execution_metadata: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'When set to `true`, the response will include an extra `_clusters`\nobject with information about the clusters that participated in the search along with info such as shards\ncount.\nThis is similar to `include_ccs_metadata`, but it also returns metadata when the query is not CCS/CPS',
                }),
              settings: EsqlTypesEsqlQuerySettingsSchema.exactOptional().openapi({
                description:
                  'Per-query settings, the request-body equivalent of the in-query `SET` command.\nFor example, `time_zone` can be supplied here instead of as a top-level field.',
                'x-state': 'Generally available; Added in 9.5.0',
              }),
            })
            .openapi({ required: ['query'] }),
          examples: {
            QueryRequestExample1: {
              description: 'Run `POST /_query` to get results for an ES|QL query.',
              value:
                '{\n  "query": """\n    FROM library,remote-*:library\n    | EVAL year = DATE_TRUNC(1 YEARS, release_date)\n    | STATS MAX(page_count) BY year\n    | SORT year\n    | LIMIT 5\n  """,\n  "include_ccs_metadata": true\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: EsqlTypesEsqlResultSchema } },
    },
  },
})

export const getIndexSourceIdRoute = createRoute({
  method: 'get',
  path: '/{index}/_source/{id}',
  tags: ['document'],
  summary: "Get a document's source",
  description:
    'Get the source of a document.\nFor example:\n\n```\nGET my-index-000001/_source/1\n```\n\nYou can use the source filtering parameters to control which parts of the `_source` are returned:\n\n```\nGET my-index-000001/_source/1/?_source_includes=*.id&_source_excludes=entities\n```\n\n## Required authorization\n\n* Index privileges: `read`\n',
  externalDocs: {
    description: 'Learn more about _source field',
    url: 'https://www.elastic.co/docs/reference/elasticsearch/mapping-reference/mapping-source-field',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/docs-get.html',
  },
  operationId: 'get-source',
  request: {
    params: z.object({
      index: TypesIndexNameSchema.openapi({
        param: {
          in: 'path',
          name: 'index',
          description: 'The name of the index that contains the document.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.IndexName' },
          style: 'simple',
        },
      }),
      id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'id',
          description: 'A unique document identifier.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      preference: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'preference',
            description:
              'The node or shard the operation should be performed on.\nBy default, the operation is randomized between the shard replicas.',
            deprecated: false,
            schema: { type: 'string' },
            style: 'form',
            required: false,
          },
        }),
      realtime: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'realtime',
            description: 'If `true`, the request is real-time as opposed to near-real-time.',
            deprecated: false,
            schema: { default: true, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      refresh: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'refresh',
            description:
              'If `true`, the request refreshes the relevant shards before retrieving the document.\nSetting it to `true` should be done after careful thought and verification that this does not cause a heavy load on the system (and slow down indexing).',
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      routing: TypesRoutingSchema.openapi({
        param: {
          in: 'query',
          name: 'routing',
          description: 'A custom value used to route operations to a specific shard.',
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Routing' },
          style: 'form',
          required: false,
        },
      }).exactOptional(),
      _source: z
        .xor([z.stringbool(), TypesFieldsSchema])
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: '_source',
            description:
              'Indicates whether to return the `_source` field (`true` or `false`) or lists the fields to return.',
            deprecated: false,
            schema: {
              description:
                'Defines how to fetch a source. Fetching can be disabled entirely, or the source can be filtered.\nUsed as a query parameter along with the `_source_includes` and `_source_excludes` parameters.',
              oneOf: [{ type: 'boolean' }, { $ref: '#/components/schemas/_types.Fields' }],
            },
            style: 'form',
            required: false,
          },
          description:
            'Defines how to fetch a source. Fetching can be disabled entirely, or the source can be filtered.\nUsed as a query parameter along with the `_source_includes` and `_source_excludes` parameters.',
        }),
      _source_excludes: TypesFieldsSchema.openapi({
        param: {
          in: 'query',
          name: '_source_excludes',
          description: 'A comma-separated list of source fields to exclude in the response.',
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Fields' },
          style: 'form',
          required: false,
        },
      }).exactOptional(),
      _source_includes: TypesFieldsSchema.openapi({
        param: {
          in: 'query',
          name: '_source_includes',
          description: 'A comma-separated list of source fields to include in the response.',
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Fields' },
          style: 'form',
          required: false,
        },
      }).exactOptional(),
      version: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          TypesVersionNumberSchema.openapi({
            param: {
              in: 'query',
              name: 'version',
              description:
                'The version number for concurrency control.\nIt must match the current version of the document for the request to succeed.',
              deprecated: false,
              schema: { $ref: '#/components/schemas/_types.VersionNumber' },
              style: 'form',
              required: false,
            },
          }),
        )
        .exactOptional(),
      version_type: TypesVersionTypeSchema.openapi({
        param: {
          in: 'query',
          name: 'version_type',
          description: 'The version type.',
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.VersionType' },
          style: 'form',
          required: false,
        },
      }).exactOptional(),
    }),
  },
  responses: {
    200: { description: '', content: { 'application/json': { schema: z.object({}) } } },
  },
})

