export const getIndexFleetGlobalCheckpointsRoute = createRoute({
  method: 'get',
  path: '/{index}/_fleet/global_checkpoints',
  tags: ['fleet'],
  summary: 'Get global checkpoints',
  description:
    'Get the current global checkpoints for an index.\nThis API is designed for internal use by the Fleet server project.',
  operationId: 'fleet-global-checkpoints',
  request: {
    params: z.object({
      index: z
        .xor([TypesIndexNameSchema, TypesIndexAliasSchema])
        .openapi({
          param: {
            in: 'path',
            name: 'index',
            description: 'A single index or index alias that resolves to a single index.',
            required: true,
            deprecated: false,
            schema: {
              oneOf: [
                { $ref: '#/components/schemas/_types.IndexName' },
                { $ref: '#/components/schemas/_types.IndexAlias' },
              ],
            },
            style: 'simple',
          },
        }),
    }),
    query: z.object({
      wait_for_advance: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'wait_for_advance',
            description:
              'A boolean value which controls whether to wait (until the timeout) for the global checkpoints\nto advance past the provided `checkpoints`.',
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      wait_for_index: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'wait_for_index',
            description:
              'A boolean value which controls whether to wait (until the timeout) for the target index to exist\nand all primary shards be active. Can only be true when `wait_for_advance` is true.',
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      checkpoints: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              FleetTypesCheckpointSchema,
            ),
          ),
        )
        .default([])
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'checkpoints',
            description:
              'A comma separated list of previous global checkpoints. When used in combination with `wait_for_advance`,\nthe API will only return once the global checkpoints advances past the checkpoints. Providing an empty list\nwill cause Elasticsearch to immediately return the current global checkpoints.',
            deprecated: false,
            schema: {
              default: [],
              type: 'array',
              items: { $ref: '#/components/schemas/fleet._types.Checkpoint' },
            },
            style: 'form',
            required: false,
          },
        }),
      timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'timeout',
            description: 'Period to wait for a global checkpoints to advance past `checkpoints`.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              global_checkpoints: z.array(FleetTypesCheckpointSchema),
              timed_out: z.boolean(),
            })
            .openapi({ required: ['global_checkpoints', 'timed_out'] }),
        },
      },
    },
  },
})

