export const postIlmMigrateToDataTiersRoute = createRoute({
  method: 'post',
  path: '/_ilm/migrate_to_data_tiers',
  tags: ['ilm'],
  summary: 'Migrate to data tiers routing',
  description:
    'Switch the indices, ILM policies, and legacy, composable, and component templates from using custom node attributes and attribute-based allocation filters to using data tiers.\nOptionally, delete one legacy index template.\nUsing node roles enables ILM to automatically move the indices between data tiers.\n\nMigrating away from custom node attributes routing can be manually performed.\nThis API provides an automated way of performing three out of the four manual steps listed in the migration guide:\n\n1. Stop setting the custom hot attribute on new indices.\n1. Remove custom allocation settings from existing ILM policies.\n1. Replace custom allocation settings from existing indices with the corresponding tier preference.\n\nILM must be stopped before performing the migration.\nUse the stop ILM and get ILM status APIs to wait until the reported operation mode is `STOPPED`.',
  externalDocs: {
    description: 'About migrating index allocation',
    url: 'https://www.elastic.co/docs/manage-data/lifecycle/index-lifecycle-management/migrate-index-allocation-filters-to-node-roles',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/ilm-migrate-to-data-tiers.html',
  },
  operationId: 'ilm-migrate-to-data-tiers',
  request: {
    query: z.object({
      dry_run: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'dry_run',
            description:
              'If true, simulates the migration from node attributes based allocation filters to data tiers, but does not perform the migration.\nThis provides a way to retrieve the indices and ILM policies that need to be migrated.',
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      master_timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'master_timeout',
            description:
              'The period to wait for a connection to the master node.\nIf no response is received before the timeout expires, the request fails and returns an error.\nIt can also be set to `-1` to indicate that the request should never timeout.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              legacy_template_to_delete: z.string().exactOptional(),
              node_attribute: z.string().exactOptional(),
            })
            .openapi({ required: [] }),
          examples: {
            MigrateToDataTiersRequestExample1: {
              description:
                'Run `POST /_ilm/migrate_to_data_tiers` to migrate the indices, ILM policies, legacy templates, composable, and component templates away from defining custom allocation filtering using the `custom_attribute_name` node attribute. It also deletes the legacy template with name `global-template` if it exists in the system.\n',
              value:
                '{\n  "legacy_template_to_delete": "global-template",\n  "node_attribute": "custom_attribute_name"\n}',
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              dry_run: z.boolean(),
              removed_legacy_template: z
                .string()
                .openapi({
                  description:
                    'The name of the legacy index template that was deleted.\nThis information is missing if no legacy index templates were deleted.',
                }),
              migrated_ilm_policies: z
                .array(z.string())
                .openapi({ description: 'The ILM policies that were updated.' }),
              migrated_indices: TypesIndicesSchema.openapi({
                description: 'The indices that were migrated to tier preference routing.',
              }),
              migrated_legacy_templates: z
                .array(z.string())
                .openapi({
                  description:
                    'The legacy index templates that were updated to not contain custom routing settings for the provided data attribute.',
                }),
              migrated_composable_templates: z
                .array(z.string())
                .openapi({
                  description:
                    'The composable index templates that were updated to not contain custom routing settings for the provided data attribute.',
                }),
              migrated_component_templates: z
                .array(z.string())
                .openapi({
                  description:
                    'The component templates that were updated to not contain custom routing settings for the provided data attribute.',
                }),
            })
            .openapi({
              required: [
                'dry_run',
                'removed_legacy_template',
                'migrated_ilm_policies',
                'migrated_indices',
                'migrated_legacy_templates',
                'migrated_composable_templates',
                'migrated_component_templates',
              ],
            }),
          examples: {
            MigrateToDataTiersResponseExample1: {
              description:
                'A successful response when migrating indices, ILMs, and templates from custom node attributes to data tiers.\n',
              value:
                '{\n  "dry_run": false,\n  "removed_legacy_template":"global-template",\n  "migrated_ilm_policies":["policy_with_allocate_action"],\n  "migrated_indices":["warm-index-to-migrate-000001"],\n  "migrated_legacy_templates":["a-legacy-template"],\n  "migrated_composable_templates":["a-composable-template"],\n  "migrated_component_templates":["a-component-template"]\n}',
            },
          },
        },
      },
    },
  },
})

export const postIlmMoveIndexRoute = createRoute({
  method: 'post',
  path: '/_ilm/move/{index}',
  tags: ['ilm'],
  summary: 'Move to a lifecycle step',
  description:
    'Manually move an index into a specific step in the lifecycle policy and run that step.\n\nWARNING: This operation can result in the loss of data. Manually moving an index into a specific step runs that step even if it has already been performed. This is a potentially destructive action and this should be considered an expert level API.\n\nYou must specify both the current step and the step to be executed in the body of the request.\nThe request will fail if the current step does not match the step currently running for the index\nThis is to prevent the index from being moved from an unexpected step into the next step.\n\nWhen specifying the target (`next_step`) to which the index will be moved, either the name or both the action and name fields are optional.\nIf only the phase is specified, the index will move to the first step of the first action in the target phase.\nIf the phase and action are specified, the index will move to the first step of the specified action in the specified phase.\nOnly actions specified in the ILM policy are considered valid.\nAn index cannot move to a step that is not part of its policy.\n\n## Required authorization\n\n* Index privileges: `manage_ilm`\n',
  operationId: 'ilm-move-to-step',
  request: {
    params: z.object({
      index: TypesIndexNameSchema.openapi({
        param: {
          in: 'path',
          name: 'index',
          description: 'The name of the index whose lifecycle step is to change',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.IndexName' },
          style: 'simple',
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              current_step: IlmMoveToStepStepKeySchema.openapi({
                description: 'The step that the index is expected to be in.',
              }),
              next_step: IlmMoveToStepStepKeySchema.openapi({
                description: 'The step that you want to run.',
              }),
            })
            .openapi({ required: ['current_step', 'next_step'] }),
          examples: {
            MoveToStepRequestExample1: {
              summary: 'Move to forcemerge step',
              description:
                'Run `POST _ilm/move/my-index-000001` to move `my-index-000001` from the initial step to the `forcemerge` step.\n',
              value:
                '{\n  "current_step": {\n    "phase": "new",\n    "action": "complete",\n    "name": "complete"\n  },\n  "next_step": {\n    "phase": "warm",\n    "action": "forcemerge",\n    "name": "forcemerge"\n  }\n}',
            },
            MoveToStepRequestExample2: {
              summary: 'Move to warm step',
              description:
                'Run `POST _ilm/move/my-index-000001` to move `my-index-000001` from the end of hot phase into the start of warm.\n',
              value:
                '{\n  "current_step": {\n    "phase": "hot",\n    "action": "complete",\n    "name": "complete"\n  },\n  "next_step": {\n    "phase": "warm"\n  }\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: TypesAcknowledgedResponseBaseSchema,
          examples: {
            MoveToStepResponseExample1: {
              description:
                'A successful response when running a specific step in a lifecycle policy.\n',
              value: '{\n  "acknowledged": true\n}',
            },
          },
        },
      },
    },
  },
})

