export const postIndexDownsampleTargetIndexRoute = createRoute({
  method: 'post',
  path: '/{index}/_downsample/{target_index}',
  tags: ['data stream'],
  summary: 'Downsample an index',
  description:
    'Downsamples a time series (TSDS) index and reduces its size by keeping the last value or by pre-aggregating metrics:\n\n- When running in `aggregate` mode, it pre-calculates and stores statistical summaries (`min`, `max`, `sum`, `value_count` and `avg`)\nfor each metric field grouped by a configured time interval and their dimensions.\n- When running in `last_value` mode, it keeps the last value for each metric in the configured interval and their dimensions.\n\nFor example, a TSDS index that contains metrics sampled every 10 seconds can be downsampled to an hourly index.\nAll documents within an hour interval are summarized and stored as a single document in the downsample index.\n\nNOTE: Only indices in a time series data stream are supported.\nNeither field nor document level security can be defined on the source index.\nThe source index must be read-only (`index.blocks.write: true`).',
  operationId: 'indices-downsample',
  request: {
    params: z.object({
      index: TypesIndexNameSchema.openapi({
        param: {
          in: 'path',
          name: 'index',
          description: 'Name of the time series index to downsample.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.IndexName' },
          style: 'simple',
        },
      }),
      target_index: TypesIndexNameSchema.openapi({
        param: {
          in: 'path',
          name: 'target_index',
          description: 'Name of the index to create.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.IndexName' },
          style: 'simple',
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: IndicesTypesDownsampleConfigSchema,
          examples: { DownsampleRequestExample1: { value: '{\n  "fixed_interval": "1d"\n}' } },
        },
      },
      required: true,
    },
  },
  responses: {
    200: { description: '', content: { 'application/json': { schema: z.object({}) } } },
  },
})

