              value:
                '{\n  "indices": {\n    ".ds-my-data-stream-test-2026.10.17-000001": {\n      "index": ".ds-my-data-stream-test-2026.10.17-000001",\n      "managed_by_lifecycle": true,\n      "index_creation_date_millis": 1792195511314,\n      "time_since_index_creation": "3.07d",\n      "rollover_date_millis": 1792440980120,\n      "time_since_rollover": "5.51h",\n      "generation_time": "5.51h",\n      "lifecycle": {\n        "enabled": true,\n        "data_retention": "30d",\n        "effective_retention": "30d",\n        "retention_determined_by": "data_stream_configuration"\n      },\n      "error": {\n        "first_occurrence_millis": 1792441580075,\n        "message": """{"type":"exception","reason":"Force merge request only had 1 successful shards out of a total of 2"}""",\n        "last_recorded_millis": 1792460779960,\n        "retry_count": 52\n      }\n    },\n    ".ds-my-data-stream-test-2026.10.19-000002": {\n      "index": ".ds-my-data-stream-test-2026.10.19-000002",\n      "managed_by_lifecycle": true,\n      "index_creation_date_millis": 1792440980129,\n      "time_since_index_creation": "5.51h",\n      "lifecycle": {\n        "enabled": true,\n        "data_retention": "30d",\n        "effective_retention": "30d",\n        "retention_determined_by": "data_stream_configuration"\n      }\n    }\n  }\n}',
