export const getIndexFieldUsageStatsRoute = createRoute({
  method: 'get',
  path: '/{index}/_field_usage_stats',
  tags: ['indices'],
  summary: 'Get field usage stats',
  description:
    'Get field usage information for each shard and field of an index.\nField usage statistics are automatically captured when queries are running on a cluster.\nA shard-level search request that accesses a given field, even if multiple times during that request, is counted as a single use.\n\nThe response body reports the per-shard usage count of the data structures that back the fields in the index.\nA given request will increment each count by a maximum value of 1, even if the request accesses the same field multiple times.\n\n## Required authorization\n\n* Index privileges: `manage`\n',
  operationId: 'indices-field-usage-stats',
  request: {
    params: z.object({
      index: TypesIndicesSchema.openapi({
        param: {
          in: 'path',
          name: 'index',
          description:
            'Comma-separated list or wildcard expression of index names used to limit the request.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Indices' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      allow_no_indices: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'allow_no_indices',
            description:
              'A setting that does two separate checks on the index expression.\nIf `false`, the request returns an error (1) if any wildcard expression\n(including `_all` and `*`) resolves to zero matching indices or (2) if the\ncomplete set of resolved indices, aliases or data streams is empty after all\nexpressions are evaluated. If `true`, index expressions that resolve to no\nindices are allowed and the request returns an empty result.',
            deprecated: false,
            schema: { type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      expand_wildcards: TypesExpandWildcardsSchema.default('open')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'expand_wildcards',
            description:
              'Type of index that wildcard patterns can match.\nIf the request can target data streams, this argument determines whether wildcard expressions match hidden data streams.\nSupports comma-separated values, such as `open,hidden`.',
            deprecated: false,
            schema: {
              default: 'open',
              allOf: [{ $ref: '#/components/schemas/_types.ExpandWildcards' }],
            },
            style: 'form',
            required: false,
          },
        }),
      ignore_unavailable: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'ignore_unavailable',
            description:
              'If `false`, the request returns an error if it targets a concrete (non-wildcarded)\nindex, alias, or data stream that is missing, closed, or otherwise unavailable.\nIf `true`, unavailable concrete targets are silently ignored.',
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      fields: TypesFieldsSchema.openapi({
        param: {
          in: 'query',
          name: 'fields',
          description:
            'Comma-separated list or wildcard expressions of fields to include in the statistics.',
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Fields' },
          style: 'form',
          required: false,
        },
      }).exactOptional(),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: IndicesFieldUsageStatsFieldsUsageBodySchema,
          examples: {
            indicesFieldUsageStatsResponseExample1: {
              description:
                'An abbreviated response from `GET /my-index-000001/_field_usage_stats`. The `all_fields` object reports the sums of the usage counts for all fields in the index (on the listed shard).\n',
              value:
                '{\n  "_shards": {\n    "total": 1,\n    "successful": 1,\n    "failed": 0\n  },\n  "my-index-000001": {\n    "shards": [\n      {\n        "tracking_id": "MpOl0QlTQ4SYYhEe6KgJoQ",\n        "tracking_started_at_millis": 1625558985010,\n        "routing": {\n          "state": "STARTED",\n          "primary": true,\n          "node": "gA6KeeVzQkGURFCUyV-e8Q",\n          "relocating_node": null\n        },\n        "stats": {\n          "all_fields": {\n            "any": "6",\n            "inverted_index": {\n              "terms": 1,\n              "postings": 1,\n              "proximity": 1,\n              "positions": 0,\n              "term_frequencies": 1,\n              "offsets": 0,\n              "payloads": 0\n            },\n            "stored_fields": 2,\n            "doc_values": 1,\n            "points": 0,\n            "norms": 1,\n            "term_vectors": 0,\n            "knn_vectors": 0\n          },\n          "fields": {\n            "_id": {\n              "any": 1,\n              "inverted_index": {\n                "terms": 1,\n                "postings": 1,\n                "proximity": 1,\n                "positions": 0,\n                "term_frequencies": 1,\n                "offsets": 0,\n                "payloads": 0\n              },\n              "stored_fields": 1,\n              "doc_values": 0,\n              "points": 0,\n              "norms": 0,\n              "term_vectors": 0,\n              "knn_vectors": 0\n            },\n            "_source": {},\n            "context": {},\n            "message.keyword": {}\n          }\n        }\n      }\n    ]\n  }\n}',
            },
          },
        },
      },
    },
  },
})

export const getFlushRoute = createRoute({
  method: 'get',
  path: '/_flush',
  tags: ['indices'],
  summary: 'Flush data streams or indices',
  description:
    'Flushing a data stream or index is the process of making sure that any data that is currently only stored in the transaction log is also permanently stored in the Lucene index.\nWhen restarting, Elasticsearch replays any unflushed operations from the transaction log into the Lucene index to bring it back into the state that it was in before the restart.\nElasticsearch automatically triggers flushes as needed, using heuristics that trade off the size of the unflushed transaction log against the cost of performing each flush.\n\nAfter each operation has been flushed it is permanently stored in the Lucene index.\nThis may mean that there is no need to maintain an additional copy of it in the transaction log.\nThe transaction log is made up of multiple files, called generations, and Elasticsearch will delete any generation files when they are no longer needed, freeing up disk space.\n\nIt is also possible to trigger a flush on one or more indices using the flush API, although it is rare for users to need to call this API directly.\nIf you call the flush API after indexing some documents then a successful response indicates that Elasticsearch has flushed all the documents that were indexed before the flush API was called.\n\n## Required authorization\n\n* Index privileges: `maintenance`\n',
  operationId: 'indices-flush-1',
  request: {
    query: z.object({
      allow_no_indices: IndicesFlushAllowNoIndicesParamsSchema,
      expand_wildcards: IndicesFlushExpandWildcardsParamsSchema,
      force: IndicesFlushForceParamsSchema,
      ignore_unavailable: IndicesFlushIgnoreUnavailableParamsSchema,
      wait_if_ongoing: IndicesFlushWaitIfOngoingParamsSchema,
    }),
  },
  responses: { 200: IndicesFlush_200Response },
})

