      expand_wildcards: IndicesForcemergeExpandWildcardsParamsSchema,
      flush: IndicesForcemergeFlushParamsSchema,
      ignore_unavailable: IndicesForcemergeIgnoreUnavailableParamsSchema,
      max_num_segments: IndicesForcemergeMaxNumSegmentsParamsSchema,
