export const getRefreshRoute = createRoute({
  method: 'get',
  path: '/_refresh',
  tags: ['indices'],
  summary: 'Refresh an index',
  description:
    "A refresh makes recent operations performed on one or more indices available for search.\nFor data streams, the API runs the refresh operation on the stream’s backing indices.\n\nBy default, Elasticsearch periodically refreshes indices every second, but only on indices that have received one search request or more in the last 30 seconds.\nYou can change this default interval with the `index.refresh_interval` setting.\n\nIn Elastic Cloud Serverless, the default refresh interval is 5 seconds across all indices.\n\nRefresh requests are synchronous and do not return a response until the refresh operation completes.\n\nRefreshes are resource-intensive.\nTo ensure good cluster performance, it's recommended to wait for Elasticsearch's periodic refresh rather than performing an explicit refresh when possible.\n\nIf your application workflow indexes documents and then runs a search to retrieve the indexed document, it's recommended to use the index API's `refresh=wait_for` query parameter option.\nThis option ensures the indexing operation waits for a periodic refresh before running the search.\n\n## Required authorization\n\n* Index privileges: `maintenance`\n",
  externalDocs: {
    description: 'More about the refresh parameter',
    url: 'https://www.elastic.co/docs/reference/elasticsearch/rest-apis/refresh-parameter',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/indices-refresh.html',
  },
  operationId: 'indices-refresh-1',
  request: {
    query: z.object({
      allow_no_indices: IndicesRefreshAllowNoIndicesParamsSchema,
      expand_wildcards: IndicesRefreshExpandWildcardsParamsSchema,
      ignore_unavailable: IndicesRefreshIgnoreUnavailableParamsSchema,
    }),
  },
  responses: { 200: IndicesRefresh_200Response },
})

