export const getIndexReloadSearchAnalyzersRoute = createRoute({
  method: 'get',
  path: '/{index}/_reload_search_analyzers',
  tags: ['indices'],
  summary: 'Reload search analyzers',
  description:
    "Reload an index's search analyzers and their resources.\nFor data streams, the API reloads search analyzers and resources for the stream's backing indices.\n\nIMPORTANT: After reloading the search analyzers you should clear the request cache to make sure it doesn't contain responses derived from the previous versions of the analyzer.\n\nYou can use the reload search analyzers API to pick up changes to synonym files used in the `synonym_graph` or `synonym` token filter of a search analyzer.\nTo be eligible, the token filter must have an `updateable` flag of `true` and only be used in search analyzers.\n\nNOTE: This API does not perform a reload for each shard of an index.\nInstead, it performs a reload for each node containing index shards.\nAs a result, the total shard count returned by the API can differ from the number of index shards.\nBecause reloading affects every node with an index shard, it is important to update the synonym file on every data node in the cluster--including nodes that don't contain a shard replica--before using this API.\nThis ensures the synonym file is updated everywhere in the cluster in case shards are relocated in the future.\n\n## Required authorization\n\n* Index privileges: `manage`\n",
  externalDocs: {
    description: 'More about the search_analyzer',
    url: 'https://www.elastic.co/docs/reference/elasticsearch/mapping-reference/search-analyzer',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/indices-reload-analyzers.html',
  },
  operationId: 'indices-reload-search-analyzers',
  request: {
    params: z.object({ index: IndicesReloadSearchAnalyzersIndexParamsSchema }),
    query: z.object({
      allow_no_indices: IndicesReloadSearchAnalyzersAllowNoIndicesParamsSchema,
      expand_wildcards: IndicesReloadSearchAnalyzersExpandWildcardsParamsSchema,
      ignore_unavailable: IndicesReloadSearchAnalyzersIgnoreUnavailableParamsSchema,
      resource: IndicesReloadSearchAnalyzersResourceParamsSchema,
    }),
  },
  responses: { 200: IndicesReloadSearchAnalyzers_200Response },
})

