export const postAliasesRoute = createRoute({
  method: 'post',
  path: '/_aliases',
  tags: ['indices'],
  summary: 'Update aliases and delete indices atomically',
  description:
    'Applies one or more actions in a single request:\n\n- Add a data stream or index to an alias.\n- Remove a data stream or index from an alias.\n- Delete an index in that same request, so the deletion and the alias changes are applied together.\n\nFor example, you can replace an index with an alias of the same name.\n\nNOTE: Every `remove_index` action in the request runs first, before any `add` or `remove` actions, no matter where it sits in the `actions` array.\n\n## Required authorization\n\n* Index privileges: `manage`\n',
  operationId: 'indices-update-aliases',
  request: {
    query: z.object({
      master_timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'master_timeout',
            description:
              'Period to wait for a connection to the master node.\nIf no response is received before the timeout expires, the request fails and returns an error.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
      timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'timeout',
            description:
              'Period to wait for a response.\nIf no response is received before the timeout expires, the request fails and returns an error.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              actions: z
                .array(IndicesUpdateAliasesActionSchema)
                .exactOptional()
                .openapi({ description: 'Actions to perform.' }),
            })
            .openapi({ required: [] }),
          examples: {
            IndicesUpdateAliasesExample1: {
              summary: 'Add a data stream or index to an alias',
              description: 'If the alias does not exist, it is created.',
              value:
                '{\n  "actions": [\n    {\n      "add": {\n        "index": "logs-nginx.access-*",\n        "alias": "logs"\n      }\n    }\n  ]\n}',
            },
            IndicesUpdateAliasesExample2: {
              summary: 'Remove a data stream or index from an alias',
              value:
                '{\n  "actions": [\n    {\n      "remove": {\n        "index": "logs-nginx.access-prod",\n        "alias": "logs"\n      }\n    }\n  ]\n}',
            },
            IndicesUpdateAliasesExample3: {
              summary: 'Remove an index and update an alias',
              description:
                'First, remove the index `my-index-1` (which has the alias `my-alias`) and then add the index `my-index-2` to the alias in a single request.\n',
              value:
                '{\n  "actions": [\n    {\n      "remove_index": {\n        "index": "my-index-1"\n      }\n    },\n    {\n      "add": {\n        "index": "my-index-2",\n        "alias": "my-alias"\n      }\n    }\n  ]\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: IndicesUpdateAliasesIndicesUpdateAliasesResponseBodySchema,
          examples: {
            IndicesUpdateAliasesExample1: {
              summary: 'A partially successful response',
              description:
                'When using multiple actions, if some succeed and some fail, the API returns a list of per-action results. For example, if the alias `logs-non-existing` does not exist, the API returns a 404 error for the `remove` action.',
              value:
                '{\n  "acknowledged": true,\n  "errors": true,\n  "action_results": [\n    {\n      "action": {\n        "type": "remove",\n        "indices": [\n          "logs-nginx.access-prod"\n        ],\n        "aliases": [\n          "logs-non-existing"\n        ]\n      },\n      "status": 404,\n      "error": {\n        "type": "aliases_not_found_exception",\n        "reason": "aliases [logs-non-existing] missing",\n        "resource.type": "aliases",\n        "resource.id": "logs-non-existing"\n      }\n    },\n    {\n      "action": {\n        "type": "add",\n        "indices": [\n          "logs-nginx.access-default"\n        ],\n        "aliases": [\n          "logs-non-existing"\n        ]\n      },\n      "status": 200\n    }\n  ]\n}',
            },
          },
        },
      },
    },
  },
})

