export const putInferenceTaskTypeCustomInferenceIdRoute = createRoute({
  method: 'put',
  path: '/_inference/{task_type}/{custom_inference_id}',
  tags: ['inference'],
  summary: 'Create a custom inference endpoint',
  description:
    'The custom service gives more control over how to interact with external inference services that aren\'t explicitly supported through dedicated integrations.\nThe custom service gives you the ability to define the headers, url, query parameters, request body, and secrets.\nThe custom service supports the template replacement functionality, which enables you to define a template that can be replaced with the value associated with that key.\nTemplates are portions of a string that start with `${` and end with `}`.\nThe parameters `secret_parameters` and `task_settings` are checked for keys for template replacement. Template replacement is supported in the `request`, `headers`, `url`, and `query_parameters`.\nIf the definition (key) is not found for a template, an error message is returned.\nIn case of an endpoint definition like the following:\n```\nPUT _inference/text_embedding/test-text-embedding\n{\n  "service": "custom",\n  "service_settings": {\n     "secret_parameters": {\n          "api_key": "<some api key>"\n     },\n     "url": "...endpoints.huggingface.cloud/v1/embeddings",\n     "headers": {\n         "Authorization": "Bearer ${api_key}",\n         "Content-Type": "application/json"\n     },\n     "request": "{\\"input\\": ${input}}",\n     "response": {\n         "json_parser": {\n             "text_embeddings":"$.data[*].embedding[*]"\n         }\n     }\n  }\n}\n```\nTo replace `${api_key}` the `secret_parameters` and `task_settings` are checked for a key named `api_key`.\n\n> info\n> Templates should not be surrounded by quotes.\n\nPre-defined templates:\n* `${input}` refers to the array of input strings that comes from the `input` field of the subsequent inference requests.\n* `${input_type}` refers to the input type translation values.\n* `${query}` refers to the query field used specifically for reranking tasks.\n* `${top_n}` refers to the `top_n` field available when performing rerank requests.\n* `${return_documents}` refers to the `return_documents` field available when performing rerank requests.\n\n## Required authorization\n\n* Cluster privileges: `manage_inference`\n',
  operationId: 'inference-put-custom',
  request: {
    params: z.object({
      task_type: InferenceTypesCustomTaskTypeSchema.openapi({
        param: {
          in: 'path',
          name: 'task_type',
          description: 'The type of the inference task that the model will perform.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/inference._types.CustomTaskType' },
          style: 'simple',
        },
      }),
      custom_inference_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'custom_inference_id',
          description: 'The unique identifier of the inference endpoint.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              chunking_settings:
                InferenceTypesInferenceChunkingSettingsSchema.exactOptional().openapi({
                  externalDocs: {
                    url: 'https://www.elastic.co/docs/explore-analyze/elastic-inference/inference-api#infer-chunking-config',
                  },
                  description:
                    'The chunking configuration object.\nApplies only to the `sparse_embedding` or `text_embedding` task types.\nNot applicable to the `rerank` or `completion` task types.',
                }),
              service: InferenceTypesCustomServiceTypeSchema.openapi({
                description:
                  'The type of service supported for the specified task type. In this case, `custom`.',
              }),
              service_settings: InferenceTypesCustomServiceSettingsSchema.openapi({
                description:
                  'Settings used to install the inference model.\nThese settings are specific to the `custom` service.',
              }),
              task_settings: InferenceTypesCustomTaskSettingsSchema.exactOptional().openapi({
                description:
                  'Settings to configure the inference task.\nThese settings are specific to the task type you specified.',
              }),
            })
            .openapi({ required: ['service', 'service_settings'] }),
          examples: {
            PutCustomRequestExample1: {
              summary: 'Custom text embedding task (OpenAI)',
              description:
                'Run `PUT _inference/text_embedding/custom-embeddings` to create an inference endpoint that performs a text embedding task.',
              value:
                '{\n    "service": "custom",\n    "service_settings": {\n        "secret_parameters": {\n            "api_key": "<api key>"\n        },\n        "url": "https://api.openai.com/v1/embeddings",\n        "headers": {\n            "Authorization": "Bearer ${api_key}",\n            "Content-Type": "application/json;charset=utf-8"\n        },\n        "request": "{\\"input\\": ${input}, \\"model\\": \\"text-embedding-3-small\\"}",\n        "response": {\n            "json_parser": {\n                "text_embeddings": "$.data[*].embedding[*]"\n            }\n        }\n    }\n}',
            },
            PutCustomRequestExample2: {
              summary: 'Custom rerank task (Cohere APIv2)',
              description:
                'Run `PUT _inference/rerank/custom-rerank` to create an inference endpoint that performs a rerank task.',
              value:
                '{\n  "service": "custom",\n  "service_settings": {\n      "secret_parameters": {\n          "api_key": "<api key>"\n      },\n      "url": "https://api.cohere.com/v2/rerank",\n      "headers": {\n          "Authorization": "bearer ${api_key}",\n          "Content-Type": "application/json"\n      },\n      "request": "{\\"documents\\": ${input}, \\"query\\": ${query}, \\"model\\": \\"rerank-v3.5\\"}",\n      "response": {\n          "json_parser": {\n              "reranked_index":"$.results[*].index",\n              "relevance_score":"$.results[*].relevance_score"\n          }\n      }\n  }\n}',
            },
            PutCustomRequestExample3: {
              summary: 'Custom text embedding task (Cohere APIv2)',
              description:
                'Run `PUT _inference/text_embedding/custom-text-embedding` to create an inference endpoint that performs a text embedding task.',
              value:
                '{\n  "service": "custom",\n  "service_settings": {\n      "secret_parameters": {\n          "api_key": "<api key>"\n      },\n      "url": "https://api.cohere.com/v2/embed",\n      "headers": {\n          "Authorization": "bearer ${api_key}",\n          "Content-Type": "application/json"\n      },\n      "request": "{\\"texts\\": ${input}, \\"model\\": \\"embed-v4.0\\", \\"input_type\\": ${input_type}}",\n      "response": {\n          "json_parser": {\n              "text_embeddings":"$.embeddings.float[*]"\n          }\n      },\n      "input_type": {\n          "translation": {\n              "ingest": "search_document",\n              "search": "search_query"\n          },\n          "default": "search_document"\n      }\n  }\n}',
            },
            PutCustomRequestExample4: {
              summary: 'Custom rerank task (Jina AI)',
              description:
                'Run `PUT _inference/rerank/custom-rerank-jina` to create an inference endpoint that performs a rerank task.',
              value:
                '{\n  "service": "custom",\n  "service_settings": {\n    "secret_parameters": {\n      "api_key": "<api key>"\n    },    \n    "url": "https://api.jina.ai/v1/rerank",\n    "headers": {\n      "Content-Type": "application/json",\n      "Authorization": "Bearer ${api_key}"\n    },\n    "request": "{\\"model\\": \\"jina-reranker-v2-base-multilingual\\",\\"query\\": ${query},\\"documents\\":${input}}",\n    "response": {\n      "json_parser": {\n        "relevance_score": "$.results[*].relevance_score",\n        "reranked_index": "$.results[*].index"\n      }\n    }\n  }\n}',
            },
            PutCustomRequestExample5: {
              summary: 'Custom text embedding task (Hugging Face)',
              description:
                'Run `PUT _inference/text_embedding/custom-text-embedding-hf` to create an inference endpoint that performs a text embedding task by using the Qwen/Qwen3-Embedding-8B model.',
              value:
                '{\n  "service": "custom",\n  "service_settings": {\n      "secret_parameters": {\n          "api_key": "<api key>"\n      },\n      "url": "<dedicated inference endpoint on HF>/v1/embeddings",\n      "headers": {\n          "Authorization": "Bearer ${api_key}",\n          "Content-Type": "application/json"\n      },\n      "request": "{\\"input\\": ${input}}",\n      "response": {\n          "json_parser": {\n              "text_embeddings":"$.data[*].embedding[*]"\n          }\n      }\n  }\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: InferenceTypesInferenceEndpointInfoCustomSchema } },
    },
  },
})

