export const putInferenceTaskTypeElasticsearchInferenceIdRoute = createRoute({
  method: 'put',
  path: '/_inference/{task_type}/{elasticsearch_inference_id}',
  tags: ['inference'],
  summary: 'Create an Elasticsearch inference endpoint',
  description:
    'Create an inference endpoint to perform an inference task with the `elasticsearch` service.\n\n> info\n> Your Elasticsearch deployment contains preconfigured ELSER and E5 inference endpoints, you only need to create the enpoints using the API if you want to customize the settings.\n\nIf you use the ELSER or the E5 model through the `elasticsearch` service, the API request will automatically download and deploy the model if it isn\'t downloaded yet.\n\n> info\n> You might see a 502 bad gateway error in the response when using the Kibana Console. This error usually just reflects a timeout, while the model downloads in the background. You can check the download progress in the Machine Learning UI. If using the Python client, you can set the timeout parameter to a higher value.\n\nAfter creating the endpoint, wait for the model deployment to complete before using it.\nTo verify the deployment status, use the get trained model statistics API.\nLook for `"state": "fully_allocated"` in the response and ensure that the `"allocation_count"` matches the `"target_allocation_count"`.\nAvoid creating multiple endpoints for the same model unless required, as each endpoint consumes significant resources.\n\n## Required authorization\n\n* Cluster privileges: `manage_inference`\n',
  operationId: 'inference-put-elasticsearch',
  request: {
    params: z.object({
      task_type: InferenceTypesElasticsearchTaskTypeSchema.openapi({
        param: {
          in: 'path',
          name: 'task_type',
          description: 'The type of the inference task that the model will perform.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/inference._types.ElasticsearchTaskType' },
          style: 'simple',
        },
      }),
      elasticsearch_inference_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'elasticsearch_inference_id',
          description:
            'The unique identifier of the inference endpoint.\nThe must not match the `model_id`.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'timeout',
            description:
              'Specifies the amount of time to wait for the inference endpoint to be created.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              chunking_settings:
                InferenceTypesInferenceChunkingSettingsSchema.exactOptional().openapi({
                  externalDocs: {
                    url: 'https://www.elastic.co/docs/explore-analyze/elastic-inference/inference-api#infer-chunking-config',
                  },
                  description:
                    'The chunking configuration object.\nApplies only to the `sparse_embedding` and `text_embedding` task types.\nNot applicable to the `rerank` task type.',
                }),
              service: InferenceTypesElasticsearchServiceTypeSchema.openapi({
                description:
                  'The type of service supported for the specified task type. In this case, `elasticsearch`.',
              }),
              service_settings: InferenceTypesElasticsearchServiceSettingsSchema.openapi({
                description:
                  'Settings used to install the inference model. These settings are specific to the `elasticsearch` service.',
              }),
              task_settings: InferenceTypesElasticsearchTaskSettingsSchema.exactOptional().openapi({
                description:
                  'Settings to configure the inference task.\nThese settings are specific to the task type you specified.',
              }),
            })
            .openapi({ required: ['service', 'service_settings'] }),
          examples: {
            PutElasticsearchRequestExample1: {
              summary: 'ELSER sparse embedding task',
              description:
                "Run `PUT _inference/sparse_embedding/my-elser-model` to create an inference endpoint that performs a `sparse_embedding` task. The `model_id` must be the ID of one of the built-in ELSER models. The API will automatically download the ELSER model if it isn't already downloaded and then deploy the model.",
              value:
                '{\n    "service": "elasticsearch",\n    "service_settings": {\n        "adaptive_allocations": { \n        "enabled": true,\n        "min_number_of_allocations": 1,\n        "max_number_of_allocations": 4\n        },\n        "num_threads": 1,\n        "model_id": ".elser_model_2" \n    }\n}',
            },
            PutElasticsearchRequestExample2: {
              summary: 'Elastic rerank task',
              description:
                "Run `PUT _inference/rerank/my-elastic-rerank` to create an inference endpoint that performs a rerank task using the built-in Elastic Rerank cross-encoder model.  The `model_id` must be `.rerank-v1`, which is the ID of the built-in Elastic Rerank model. The API will automatically download the Elastic Rerank model if it isn't already downloaded and then deploy the model. Once deployed, the model can be used for semantic re-ranking with a `text_similarity_reranker` retriever.",
              value:
                '{\n    "service": "elasticsearch",\n    "service_settings": {\n        "model_id": ".rerank-v1", \n        "num_threads": 1,\n        "adaptive_allocations": { \n        "enabled": true,\n        "min_number_of_allocations": 1,\n        "max_number_of_allocations": 4\n        }\n    }\n}',
            },
            PutElasticsearchRequestExample3: {
              summary: 'E5 text embedding task',
              description:
                "Run `PUT _inference/text_embedding/my-e5-model` to create an inference endpoint that performs a `text_embedding` task. The `model_id` must be the ID of one of the built-in E5 models. The API will automatically download the E5 model if it isn't already downloaded and then deploy the model.",
              value:
                '{\n    "service": "elasticsearch",\n    "service_settings": {\n        "num_allocations": 1,\n        "num_threads": 1,\n        "model_id": ".multilingual-e5-small" \n    }\n}',
            },
            PutElasticsearchRequestExample4: {
              summary: 'Eland text embedding task',
              description:
                'Run `PUT _inference/text_embedding/my-msmarco-minilm-model` to create an inference endpoint that performs a `text_embedding` task with a model that was uploaded by Eland.',
              value:
                '{\n    "service": "elasticsearch",\n    "service_settings": {\n        "num_allocations": 1,\n        "num_threads": 1,\n        "model_id": "msmarco-MiniLM-L12-cos-v5" \n    }\n}',
            },
            PutElasticsearchRequestExample5: {
              summary: 'Adaptive allocation',
              description:
                "Run `PUT _inference/text_embedding/my-e5-model` to create an inference endpoint that performs a `text_embedding` task and to configure adaptive allocations. The API request will automatically download the E5 model if it isn't already downloaded and then deploy the model.",
              value:
                '{\n    "service": "elasticsearch",\n    "service_settings": {\n        "adaptive_allocations": {\n        "enabled": true,\n        "min_number_of_allocations": 3,\n        "max_number_of_allocations": 10\n        },\n        "num_threads": 1,\n        "model_id": ".multilingual-e5-small"\n    }\n}',
            },
            PutElasticsearchRequestExample6: {
              summary: 'Existing model deployment',
              description:
                'Run `PUT _inference/sparse_embedding/use_existing_deployment` to use an already existing model deployment when creating an inference endpoint.',
              value:
                '{\n    "service": "elasticsearch",\n    "service_settings": {\n        "deployment_id": ".elser_model_2"\n    }\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: InferenceTypesInferenceEndpointInfoElasticsearchSchema,
          examples: {
            PutElasticsearchResponseExample1: {
              description:
                'A successful response from `PUT _inference/sparse_embedding/use_existing_deployment`. It contains the model ID and the threads and allocations settings from the model deployment.\n',
              value:
                '{\n  "inference_id": "use_existing_deployment",\n  "task_type": "sparse_embedding",\n  "service": "elasticsearch",\n  "service_settings": {\n    "num_allocations": 2,\n    "num_threads": 1,\n    "model_id": ".elser_model_2",\n    "deployment_id": ".elser_model_2"\n  },\n  "chunking_settings": {\n    "strategy": "sentence",\n    "max_chunk_size": 250,\n    "sentence_overlap": 1\n  }\n}',
            },
          },
        },
      },
    },
  },
})

