export const putInferenceTaskTypeOpenaiInferenceIdRoute = createRoute({
  method: 'put',
  path: '/_inference/{task_type}/{openai_inference_id}',
  tags: ['inference'],
  summary: 'Create an OpenAI inference endpoint',
  description:
    'Create an inference endpoint to perform an inference task with the `openai` service or `openai` compatible APIs.\n\n## Required authorization\n\n* Cluster privileges: `manage_inference`\n',
  operationId: 'inference-put-openai',
  request: {
    params: z.object({
      task_type: InferenceTypesOpenAITaskTypeSchema.openapi({
        param: {
          in: 'path',
          name: 'task_type',
          description:
            'The type of the inference task that the model will perform.\nNOTE: The `chat_completion` task type only supports streaming and only through the _stream API.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/inference._types.OpenAITaskType' },
          style: 'simple',
        },
      }),
      openai_inference_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'openai_inference_id',
          description: 'The unique identifier of the inference endpoint.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'timeout',
            description:
              'Specifies the amount of time to wait for the inference endpoint to be created.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              chunking_settings:
                InferenceTypesInferenceChunkingSettingsSchema.exactOptional().openapi({
                  externalDocs: {
                    url: 'https://www.elastic.co/docs/explore-analyze/elastic-inference/inference-api#infer-chunking-config',
                  },
                  description:
                    'The chunking configuration object.\nApplies only to the `text_embedding` task type.\nNot applicable to the `completion` or `chat_completion` task types.',
                }),
              service: InferenceTypesOpenAIServiceTypeSchema.openapi({
                description:
                  'The type of service supported for the specified task type. In this case, `openai`.',
              }),
              service_settings: InferenceTypesOpenAIServiceSettingsSchema.openapi({
                description:
                  'Settings used to install the inference model. These settings are specific to the `openai` service.',
              }),
              task_settings: InferenceTypesOpenAITaskSettingsSchema.exactOptional().openapi({
                description:
                  'Settings to configure the inference task.\nThese settings are specific to the task type you specified.',
              }),
            })
            .openapi({ required: ['service', 'service_settings'] }),
          examples: {
            PutOpenAiRequestExample1: {
              summary: 'A text embedding task',
              description:
                'Run `PUT _inference/text_embedding/openai-embeddings` to create an inference endpoint that performs a `text_embedding` task. The embeddings created by requests to this endpoint will have 128 dimensions.',
              value:
                '{\n    "service": "openai",\n    "service_settings": {\n        "api_key": "OpenAI-API-Key",\n        "model_id": "text-embedding-3-small",\n        "dimensions": 128\n    }\n}',
            },
            PutOpenAiRequestExample2: {
              summary: 'A completion task',
              description:
                'Run `PUT _inference/completion/openai-completion` to create an inference endpoint to perform a `completion` task type.',
              value:
                '{\n    "service": "openai",\n    "service_settings": {\n        "api_key": "OpenAI-API-Key",\n        "model_id": "gpt-3.5-turbo"\n    }\n}',
            },
            PutOpenAiRequestExample3: {
              summary: 'A text embedding task with OAuth 2.0 authorization',
              description:
                'Run `PUT _inference/text_embedding/openai-embeddings` to create an inference endpoint that performs a `text_embedding` task. The requests to this endpoint will use OAuth 2.0 authorization.',
              value:
                '{\n  "service": "openai",\n  "service_settings": {\n    "model_id": "text-embedding-3-small",\n    "client_id": "test_client_id",\n    "scopes": ["scope1", "scope2"],\n    "client_secret": "secret",\n    "token_url": "http://localhost:8080/token",\n    "url": "https://api.openai.com/v1/embeddings"\n  }\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: InferenceTypesInferenceEndpointInfoOpenAISchema } },
    },
  },
})

