export const putIngestPipelineIdRoute = createRoute({
  method: 'put',
  path: '/_ingest/pipeline/{id}',
  tags: ['ingest'],
  summary: 'Create or update a pipeline',
  description: 'Changes made using this API take effect immediately.',
  externalDocs: {
    description: 'About ingest pipelines',
    url: 'https://www.elastic.co/docs/manage-data/ingest/transform-enrich/ingest-pipelines',
  },
  operationId: 'ingest-put-pipeline',
  request: {
    params: z.object({
      id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'id',
          description: 'ID of the ingest pipeline to create or update.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      master_timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'master_timeout',
            description:
              'Period to wait for a connection to the master node. If no response is received before the timeout expires, the request fails and returns an error.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
      timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'timeout',
            description:
              'Period to wait for a response. If no response is received before the timeout expires, the request fails and returns an error.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
      if_version: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'if_version',
            description: 'Required version for optimistic concurrency control for pipeline updates',
            deprecated: false,
            schema: { type: 'number' },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              _meta: TypesMetadataSchema.exactOptional().openapi({
                description:
                  'Optional metadata about the ingest pipeline. May have any contents. This map is not automatically generated by Elasticsearch.',
              }),
              description: z
                .string()
                .exactOptional()
                .openapi({ description: 'Description of the ingest pipeline.' }),
              on_failure: z
                .array(IngestTypesProcessorContainerSchema)
                .exactOptional()
                .openapi({
                  description:
                    "Processors to run immediately after a processor failure. Each processor supports a processor-level `on_failure` value. If a processor without an `on_failure` value fails, Elasticsearch uses this pipeline-level parameter as a fallback. The processors in this parameter run sequentially in the order specified. Elasticsearch will not attempt to run the pipeline's remaining processors.",
                }),
              processors: z
                .array(IngestTypesProcessorContainerSchema)
                .exactOptional()
                .openapi({
                  description:
                    'Processors used to perform transformations on documents before indexing. Processors run sequentially in the order specified.',
                }),
              version: TypesVersionNumberSchema.exactOptional().openapi({
                description:
                  'Version number used by external systems to track ingest pipelines. This parameter is intended for external systems only. Elasticsearch does not use or validate pipeline version numbers.',
              }),
              deprecated: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Marks this ingest pipeline as deprecated.\nWhen a deprecated ingest pipeline is referenced as the default or final pipeline when creating or updating a non-deprecated index template, Elasticsearch will emit a deprecation warning.',
                }),
              field_access_pattern: IngestTypesFieldAccessPatternSchema.default('classic')
                .exactOptional()
                .openapi({
                  description:
                    "Controls how processors in this pipeline should read and write data on a document's source.",
                  'x-state': 'Generally available; Added in 9.2.0',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            PutPipelineRequestExample1: {
              summary: 'Create an ingest pipeline.',
              value:
                '{\n  "description" : "My optional pipeline description",\n  "processors" : [\n    {\n      "set" : {\n        "description" : "My optional processor description",\n        "field": "my-keyword-field",\n        "value": "foo"\n      }\n    }\n  ]\n}',
            },
            PutPipelineRequestExample2: {
              summary: 'Create an ingest pipeline with metadata.',
              description:
                'You can use the `_meta` parameter to add arbitrary metadata to a pipeline.',
              value:
                '{\n  "description" : "My optional pipeline description",\n  "processors" : [\n    {\n      "set" : {\n        "description" : "My optional processor description",\n        "field": "my-keyword-field",\n        "value": "foo"\n      }\n    }\n  ],\n  "_meta": {\n    "reason": "set my-keyword-field to foo",\n    "serialization": {\n      "class": "MyPipeline",\n      "id": 10\n    }\n  }\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: TypesAcknowledgedResponseBaseSchema } },
    },
  },
})

