export const getMgetRoute = createRoute({
  method: 'get',
  path: '/_mget',
  tags: ['document'],
  summary: 'Get multiple documents',
  description:
    'Get multiple JSON documents by ID from one or more indices.\nIf you specify an index in the request URI, you only need to specify the document IDs in the request body.\nTo ensure fast responses, this multi get (mget) API responds with partial results if one or more shards fail.\n\n**Filter source fields**\n\nBy default, the `_source` field is returned for every document (if stored).\nUse the `_source` and `_source_include` or `source_exclude` attributes to filter what fields are returned for a particular document.\nYou can include the `_source`, `_source_includes`, and `_source_excludes` query parameters in the request URI to specify the defaults to use when there are no per-document instructions.\n\n**Get stored fields**\n\nUse the `stored_fields` attribute to specify the set of stored fields you want to retrieve.\nAny requested fields that are not stored are ignored.\nYou can include the `stored_fields` query parameter in the request URI to specify the defaults to use when there are no per-document instructions.\n\n## Required authorization\n\n* Index privileges: `read`\n',
  operationId: 'mget',
  request: {
    query: z.object({
      preference: MgetPreferenceParamsSchema,
      realtime: MgetRealtimeParamsSchema,
      refresh: MgetRefreshParamsSchema,
      routing: MgetRoutingParamsSchema,
      _source: MgetSourceParamsSchema,
      _source_excludes: MgetSourceExcludesParamsSchema,
      _source_includes: MgetSourceIncludesParamsSchema,
      stored_fields: MgetStoredFieldsParamsSchema,
    }),
    body: MgetRequestBody,
  },
  responses: { 200: Mget_200Response },
})

export const postMgetRoute = createRoute({
  method: 'post',
  path: '/_mget',
  tags: ['document'],
  summary: 'Get multiple documents',
  description:
    'Get multiple JSON documents by ID from one or more indices.\nIf you specify an index in the request URI, you only need to specify the document IDs in the request body.\nTo ensure fast responses, this multi get (mget) API responds with partial results if one or more shards fail.\n\n**Filter source fields**\n\nBy default, the `_source` field is returned for every document (if stored).\nUse the `_source` and `_source_include` or `source_exclude` attributes to filter what fields are returned for a particular document.\nYou can include the `_source`, `_source_includes`, and `_source_excludes` query parameters in the request URI to specify the defaults to use when there are no per-document instructions.\n\n**Get stored fields**\n\nUse the `stored_fields` attribute to specify the set of stored fields you want to retrieve.\nAny requested fields that are not stored are ignored.\nYou can include the `stored_fields` query parameter in the request URI to specify the defaults to use when there are no per-document instructions.\n\n## Required authorization\n\n* Index privileges: `read`\n',
  operationId: 'mget-1',
  request: {
    query: z.object({
      preference: MgetPreferenceParamsSchema,
      realtime: MgetRealtimeParamsSchema,
      refresh: MgetRefreshParamsSchema,
      routing: MgetRoutingParamsSchema,
      _source: MgetSourceParamsSchema,
      _source_excludes: MgetSourceExcludesParamsSchema,
      _source_includes: MgetSourceIncludesParamsSchema,
      stored_fields: MgetStoredFieldsParamsSchema,
    }),
    body: MgetRequestBody,
  },
  responses: { 200: Mget_200Response },
})

