export const putMlDataFrameAnalyticsIdRoute = createRoute({
  method: 'put',
  path: '/_ml/data_frame/analytics/{id}',
  tags: ['ml data frame'],
  summary: 'Create a data frame analytics job',
  description:
    'This API creates a data frame analytics job that performs an analysis on the\nsource indices and stores the outcome in a destination index.\nBy default, the query used in the source configuration is `{"match_all": {}}`.\n\nIf the destination index does not exist, it is created automatically when you start the job.\n\nIf you supply only a subset of the regression or classification parameters, hyperparameter optimization occurs. It determines a value for each of the undefined parameters.\n\n## Required authorization\n\n* Index privileges: `create_index`,`index`,`manage`,`read`,`view_index_metadata`\n* Cluster privileges: `manage_ml`\n',
  operationId: 'ml-put-data-frame-analytics',
  request: {
    params: z.object({
      id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'id',
          description:
            'Identifier for the data frame analytics job. This identifier can contain\nlowercase alphanumeric characters (a-z and 0-9), hyphens, and\nunderscores. It must start and end with alphanumeric characters.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              allow_lazy_start: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Specifies whether this job can start when there is insufficient machine\nlearning node capacity for it to be immediately assigned to a node. If\nset to `false` and a machine learning node with capacity to run the job\ncannot be immediately found, the API returns an error. If set to `true`,\nthe API does not return an error; the job waits in the `starting` state\nuntil sufficient machine learning node capacity is available. This\nbehavior is also affected by the cluster-wide\n`xpack.ml.max_lazy_ml_nodes` setting.',
                }),
              analysis: MlTypesDataframeAnalysisContainerSchema.openapi({
                description:
                  'The analysis configuration, which contains the information necessary to\nperform one of the following types of analysis: classification, outlier\ndetection, or regression.',
              }),
              analyzed_fields: MlTypesDataframeAnalysisAnalyzedFieldsSchema.exactOptional().openapi(
                {
                  description:
                    'Specifies `includes` and/or `excludes` patterns to select which fields\nwill be included in the analysis. The patterns specified in `excludes`\nare applied last, therefore `excludes` takes precedence. In other words,\nif the same field is specified in both `includes` and `excludes`, then\nthe field will not be included in the analysis. If `analyzed_fields` is\nnot set, only the relevant fields will be included. For example, all the\nnumeric fields for outlier detection.\nThe supported fields vary for each type of analysis. Outlier detection\nrequires numeric or `boolean` data to analyze. The algorithms don’t\nsupport missing values therefore fields that have data types other than\nnumeric or boolean are ignored. Documents where included fields contain\nmissing values, null values, or an array are also ignored. Therefore the\n`dest` index may contain documents that don’t have an outlier score.\nRegression supports fields that are numeric, `boolean`, `text`,\n`keyword`, and `ip` data types. It is also tolerant of missing values.\nFields that are supported are included in the analysis, other fields are\nignored. Documents where included fields contain an array with two or\nmore values are also ignored. Documents in the `dest` index that don’t\ncontain a results field are not included in the regression analysis.\nClassification supports fields that are numeric, `boolean`, `text`,\n`keyword`, and `ip` data types. It is also tolerant of missing values.\nFields that are supported are included in the analysis, other fields are\nignored. Documents where included fields contain an array with two or\nmore values are also ignored. Documents in the `dest` index that don’t\ncontain a results field are not included in the classification analysis.\nClassification analysis can be improved by mapping ordinal variable\nvalues to a single number. For example, in case of age ranges, you can\nmodel the values as `0-14 = 0`, `15-24 = 1`, `25-34 = 2`, and so on.',
                },
              ),
              description: z
                .string()
                .exactOptional()
                .openapi({ description: 'A description of the job.' }),
              dest: MlTypesDataframeAnalyticsDestinationSchema.openapi({
                description: 'The destination configuration.',
              }),
              max_num_threads: z
                .number()
                .default(1)
                .exactOptional()
                .openapi({
                  description:
                    'The maximum number of threads to be used by the analysis. Using more\nthreads may decrease the time necessary to complete the analysis at the\ncost of using more CPU. Note that the process may use additional threads\nfor operational functionality other than the analysis itself.',
                }),
              _meta: TypesMetadataSchema.exactOptional(),
              model_memory_limit: z
                .string()
                .default('1gb')
                .exactOptional()
                .openapi({
                  description:
                    'The approximate maximum amount of memory resources that are permitted for\nanalytical processing. If your `elasticsearch.yml` file contains an\n`xpack.ml.max_model_memory_limit` setting, an error occurs when you try\nto create data frame analytics jobs that have `model_memory_limit` values\ngreater than that setting.',
                }),
              source: MlTypesDataframeAnalyticsSourceSchema.openapi({
                description: 'The configuration of how to source the analysis data.',
              }),
              headers: TypesHttpHeadersSchema.exactOptional().openapi({
                'x-state': 'Generally available; Added in 8.0.0',
              }),
              version: TypesVersionStringSchema.exactOptional().openapi({
                'x-state': 'Generally available; Added in 7.16.0',
              }),
            })
            .openapi({ required: ['analysis', 'dest', 'source'] }),
          examples: {
            MlPutDataFrameAnalyticsExample1: {
              description:
                'An example body for a `PUT _ml/data_frame/analytics/model-flight-delays-pre` request.',
              value:
                '{\n  "source": {\n    "index": [\n      "kibana_sample_data_flights"\n    ],\n    "query": {\n      "range": {\n        "DistanceKilometers": {\n          "gt": 0\n        }\n      }\n    },\n    "_source": {\n      "includes": [],\n      "excludes": [\n        "FlightDelay",\n        "FlightDelayType"\n      ]\n    }\n  },\n  "dest": {\n    "index": "df-flight-delays",\n    "results_field": "ml-results"\n  },\n  "analysis": {\n  "regression": {\n    "dependent_variable": "FlightDelayMin",\n    "training_percent": 90\n    }\n  },\n  "analyzed_fields": {\n    "includes": [],\n    "excludes": [\n      "FlightNum"\n    ]\n  },\n  "model_memory_limit": "100mb"\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              authorization: MlTypesDataframeAnalyticsAuthorizationSchema.exactOptional(),
              allow_lazy_start: z.boolean(),
              analysis: MlTypesDataframeAnalysisContainerSchema,
              analyzed_fields: MlTypesDataframeAnalysisAnalyzedFieldsSchema.exactOptional(),
              create_time: TypesEpochTimeUnitMillisSchema,
              description: z.string().exactOptional(),
              dest: MlTypesDataframeAnalyticsDestinationSchema,
              id: TypesIdSchema,
              max_num_threads: z.number(),
              _meta: TypesMetadataSchema.exactOptional(),
              model_memory_limit: z.string(),
              source: MlTypesDataframeAnalyticsSourceSchema,
              version: TypesVersionStringSchema,
            })
            .openapi({
              required: [
                'allow_lazy_start',
                'analysis',
                'create_time',
                'dest',
                'id',
                'max_num_threads',
                'model_memory_limit',
                'source',
                'version',
              ],
            }),
        },
      },
    },
  },
})

