export const putMlDatafeedsDatafeedIdRoute = createRoute({
  method: 'put',
  path: '/_ml/datafeeds/{datafeed_id}',
  tags: ['ml anomaly'],
  summary: 'Create a datafeed',
  description:
    'Datafeeds retrieve data from Elasticsearch for analysis by an anomaly detection job.\nYou can associate only one datafeed with each anomaly detection job.\nThe datafeed contains a query that runs at a defined interval (`frequency`).\nIf you are concerned about delayed data, you can add a delay (`query_delay\') at each interval.\nBy default, the datafeed uses the following query: `{"match_all": {"boost": 1}}`.\n\nWhen Elasticsearch security features are enabled, your datafeed remembers which roles the user who created it had\nat the time of creation and runs the query using those same roles. If you provide secondary authorization headers,\nthose credentials are used instead.\nYou must use Kibana, this API, or the create anomaly detection jobs API to create a datafeed. Do not add a datafeed\ndirectly to the `.ml-config` index. Do not give users `write` privileges on the `.ml-config` index.\n\n## Required authorization\n\n* Index privileges: `read`\n* Cluster privileges: `manage_ml`\n',
  operationId: 'ml-put-datafeed',
  request: {
    params: z.object({
      datafeed_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'datafeed_id',
          description:
            'A numerical character string that uniquely identifies the datafeed.\nThis identifier can contain lowercase alphanumeric characters (a-z and 0-9), hyphens, and underscores.\nIt must start and end with alphanumeric characters.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      allow_no_indices: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'allow_no_indices',
            description:
              'A setting that does two separate checks on the index expression.\nIf `false`, the request returns an error (1) if any wildcard expression\n(including `_all` and `*`) resolves to zero matching indices or (2) if the\ncomplete set of resolved indices, aliases or data streams is empty after all\nexpressions are evaluated. If `true`, index expressions that resolve to no\nindices are allowed and the request returns an empty result.',
            deprecated: false,
            schema: { default: true, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      expand_wildcards: TypesExpandWildcardsSchema.default('open')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'expand_wildcards',
            description:
              'Type of index that wildcard patterns can match. If the request can target data streams, this argument determines\nwhether wildcard expressions match hidden data streams. Supports comma-separated values.',
            deprecated: false,
            schema: {
              default: 'open',
              allOf: [{ $ref: '#/components/schemas/_types.ExpandWildcards' }],
            },
            style: 'form',
            required: false,
          },
        }),
      ignore_throttled: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'ignore_throttled',
            description: 'If true, concrete, expanded, or aliased indices are ignored when frozen.',
            deprecated: true,
            schema: { default: true, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      ignore_unavailable: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'ignore_unavailable',
            description:
              'If `false`, the request returns an error if it targets a concrete (non-wildcarded)\nindex, alias, or data stream that is missing, closed, or otherwise unavailable.\nIf `true`, unavailable concrete targets are silently ignored.',
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              aggregations: z
                .record(z.string(), TypesAggregationsAggregationContainerSchema)
                .exactOptional()
                .openapi({
                  description:
                    'If set, the datafeed performs aggregation searches.\nSupport for aggregations is limited and should be used only with low cardinality data.',
                }),
              chunking_config: MlTypesChunkingConfigSchema.exactOptional().openapi({
                description:
                  'Datafeeds might be required to search over long time periods, for several months or years.\nThis search is split into time chunks in order to ensure the load on Elasticsearch is managed.\nChunking configuration controls how the size of these time chunks are calculated;\nit is an advanced configuration option.',
              }),
              delayed_data_check_config:
                MlTypesDelayedDataCheckConfigSchema.exactOptional().openapi({
                  description:
                    'Specifies whether the datafeed checks for missing data and the size of the window.\nThe datafeed can optionally search over indices that have already been read in an effort to determine whether\nany data has subsequently been added to the index. If missing data is found, it is a good indication that the\n`query_delay` is set too low and the data is being indexed after the datafeed has passed that moment in time.\nThis check runs only on real-time datafeeds.',
                }),
              frequency: TypesDurationSchema.exactOptional().openapi({
                description:
                  'The interval at which scheduled queries are made while the datafeed runs in real time.\nThe default value is either the bucket span for short bucket spans, or, for longer bucket spans, a sensible\nfraction of the bucket span. When `frequency` is shorter than the bucket span, interim results for the last\n(partial) bucket are written then eventually overwritten by the full bucket results. If the datafeed uses\naggregations, this value must be divisible by the interval of the date histogram aggregation.',
              }),
              indices: TypesIndicesSchema.exactOptional().openapi({
                description:
                  'An array of index names. Wildcards are supported. If any of the indices are in remote clusters, the master\nnodes and the machine learning nodes must have the `remote_cluster_client` role.',
              }),
              indices_options: TypesIndicesOptionsSchema.exactOptional().openapi({
                description: 'Specifies index expansion options that are used during search',
              }),
              job_id: TypesIdSchema.exactOptional().openapi({
                description: 'Identifier for the anomaly detection job.',
              }),
              max_empty_searches: z
                .number()
                .exactOptional()
                .openapi({
                  description:
                    'If a real-time datafeed has never seen any data (including during any initial training period), it automatically\nstops and closes the associated job after this many real-time searches return no documents. In other words,\nit stops after `frequency` times `max_empty_searches` of real-time operation. If not set, a datafeed with no\nend time that sees no data remains started until it is explicitly stopped. By default, it is not set.',
                }),
              max_consecutive_extraction_failures: z
                .number()
                .exactOptional()
                .openapi({
                  description:
                    "The maximum number of consecutive real-time data extraction failures the datafeed tolerates before it\nautomatically stops itself, leaving the associated job open. The consecutive-failure counter resets on any\ncycle that extracts successfully, including empty-data cycles. If not set, the threshold defaults to roughly\none day's worth of searches based on the datafeed `frequency` (floored at 1). Set to `-1` to disable auto-stop\nand retry indefinitely. Values of `0` or less than `-1` are rejected.",
                }),
              query: TypesQueryDslQueryContainerSchema.default('{"match_all": {"boost": 1}}')
                .exactOptional()
                .openapi({
                  description:
                    'The Elasticsearch query domain-specific language (DSL). This value corresponds to the query object in an\nElasticsearch search POST body. All the options that are supported by Elasticsearch can be used, as this\nobject is passed verbatim to Elasticsearch.',
                }),
              query_delay: TypesDurationSchema.exactOptional().openapi({
                description:
                  'The number of seconds behind real time that data is queried. For example, if data from 10:04 a.m. might\nnot be searchable in Elasticsearch until 10:06 a.m., set this property to 120 seconds. The default\nvalue is randomly selected between `60s` and `120s`. This randomness improves the query performance\nwhen there are multiple jobs running on the same node.',
              }),
              runtime_mappings: TypesMappingRuntimeFieldsSchema.exactOptional().openapi({
                description: 'Specifies runtime fields for the datafeed search.',
              }),
              script_fields: z
                .record(z.string(), TypesScriptFieldSchema)
                .exactOptional()
                .openapi({
                  description:
                    'Specifies scripts that evaluate custom expressions and returns script fields to the datafeed.\nThe detector configuration objects in a job can contain functions that use these script fields.',
                }),
              scroll_size: z
                .number()
                .default(1000)
                .exactOptional()
                .openapi({
                  description:
                    'The size parameter that is used in Elasticsearch searches when the datafeed does not use aggregations.\nThe maximum value is the value of `index.max_result_window`, which is 10,000 by default.',
                }),
              headers: TypesHttpHeadersSchema.exactOptional().openapi({
                'x-state': 'Generally available; Added in 8.0.0',
              }),
            })
            .openapi({ required: [] }),
          examples: {
            MlPutDatafeedExample1: {
              description:
                'An example body for a `PUT _ml/datafeeds/datafeed-test-job?pretty` request.',
              value:
                '{\n  "indices": [\n    "kibana_sample_data_logs"\n  ],\n  "query": {\n    "bool": {\n      "must": [\n        {\n          "match_all": {}\n        }\n      ]\n    }\n  },\n  "job_id": "test-job"\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              aggregations: z
                .record(z.string(), TypesAggregationsAggregationContainerSchema)
                .exactOptional(),
              authorization: MlTypesDatafeedAuthorizationSchema.exactOptional(),
              chunking_config: MlTypesChunkingConfigSchema,
              delayed_data_check_config: MlTypesDelayedDataCheckConfigSchema.exactOptional(),
              datafeed_id: TypesIdSchema,
              frequency: TypesDurationSchema.exactOptional(),
              indices: z.array(z.string()),
              job_id: TypesIdSchema,
              indices_options: TypesIndicesOptionsSchema.exactOptional(),
              max_empty_searches: z.number().exactOptional(),
              max_consecutive_extraction_failures: z.number().exactOptional(),
              query: TypesQueryDslQueryContainerSchema,
              query_delay: TypesDurationSchema,
              runtime_mappings: TypesMappingRuntimeFieldsSchema.exactOptional(),
              script_fields: z.record(z.string(), TypesScriptFieldSchema).exactOptional(),
              scroll_size: z.number(),
            })
            .openapi({
              required: [
                'chunking_config',
                'datafeed_id',
                'indices',
                'job_id',
                'query',
                'query_delay',
                'scroll_size',
              ],
            }),
        },
      },
    },
  },
})

