export const postMlAnomalyDetectorsJobIdForecastRoute = createRoute({
  method: 'post',
  path: '/_ml/anomaly_detectors/{job_id}/_forecast',
  tags: ['ml anomaly'],
  summary: 'Predict future behavior of a time series',
  description:
    'Forecasts are not supported for jobs that perform population analysis; an\nerror occurs if you try to create a forecast for a job that has an\n`over_field_name` in its configuration. Forcasts predict future behavior\nbased on historical data.\n\n## Required authorization\n\n* Cluster privileges: `manage_ml`\n',
  operationId: 'ml-forecast',
  request: {
    params: z.object({
      job_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'job_id',
          description:
            'Identifier for the anomaly detection job. The job must be open when you\ncreate a forecast; otherwise, an error occurs.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      duration: TypesDurationSchema.default('1d')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'duration',
            description:
              'A period of time that indicates how far into the future to forecast. For\nexample, `30d` corresponds to 30 days. The forecast starts at the last\nrecord that was processed.',
            deprecated: false,
            schema: { default: '1d', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
      expires_in: TypesDurationSchema.default('14d')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'expires_in',
            description:
              'The period of time that forecast results are retained. After a forecast\nexpires, the results are deleted. If set to a value of 0, the forecast is\nnever automatically deleted.',
            deprecated: false,
            schema: { default: '14d', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
      max_model_memory: z
        .string()
        .default('20mb')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'max_model_memory',
            description:
              'The maximum memory the forecast can use. If the forecast needs to use\nmore than the provided amount, it will spool to disk. Default is 20mb,\nmaximum is 500mb and minimum is 1mb. If set to 40% or more of the job’s\nconfigured memory limit, it is automatically reduced to below that\namount.',
            deprecated: false,
            schema: { default: '20mb', type: 'string' },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              duration: TypesDurationSchema.default('1d')
                .exactOptional()
                .openapi({
                  description: 'Refer to the description for the `duration` query parameter.',
                }),
              expires_in: TypesDurationSchema.default('14d')
                .exactOptional()
                .openapi({
                  description: 'Refer to the description for the `expires_in` query parameter.',
                }),
              max_model_memory: z
                .string()
                .default('20mb')
                .exactOptional()
                .openapi({
                  description:
                    'Refer to the description for the `max_model_memory` query parameter.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            MlForecastExample1: {
              description:
                'An example body for a `POST _ml/anomaly_detectors/low_request_rate/_forecast` request.',
              value: '{\n  "duration": "10d"\n}',
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({ acknowledged: z.boolean(), forecast_id: TypesIdSchema })
            .openapi({ required: ['acknowledged', 'forecast_id'] }),
        },
      },
    },
  },
})

