export const postMlAnomalyDetectorsEstimateModelMemoryRoute = createRoute({
  method: 'post',
  path: '/_ml/anomaly_detectors/_estimate_model_memory',
  tags: ['ml anomaly'],
  summary: 'Estimate job model memory usage',
  description:
    'Make an estimation of the memory usage for an anomaly detection job model.\nThe estimate is based on analysis configuration details for the job and cardinality\nestimates for the fields it references.\n\n## Required authorization\n\n* Cluster privileges: `manage_ml`\n',
  operationId: 'ml-estimate-model-memory',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              analysis_config: MlTypesAnalysisConfigSchema.exactOptional().openapi({
                description:
                  'For a list of the properties that you can specify in the\n`analysis_config` component of the body of this API.',
              }),
              max_bucket_cardinality: z
                .record(z.string(), z.number())
                .exactOptional()
                .openapi({
                  description:
                    'Estimates of the highest cardinality in a single bucket that is observed\nfor influencer fields over the time period that the job analyzes data.\nTo produce a good answer, values must be provided for all influencer\nfields. Providing values for fields that are not listed as `influencers`\nhas no effect on the estimation.',
                }),
              overall_cardinality: z
                .record(z.string(), z.number())
                .exactOptional()
                .openapi({
                  description:
                    'Estimates of the cardinality that is observed for fields over the whole\ntime period that the job analyzes data. To produce a good answer, values\nmust be provided for fields referenced in the `by_field_name`,\n`over_field_name` and `partition_field_name` of any detectors. Providing\nvalues for other fields has no effect on the estimation. It can be\nomitted from the request if no detectors have a `by_field_name`,\n`over_field_name` or `partition_field_name`.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            MlEstimateModelMemoryRequestExample1: {
              description:
                'Run `POST _ml/anomaly_detectors/_estimate_model_memory` to estimate the model memory limit based on the analysis configuration details provided in the request body.',
              value:
                '{\n  "analysis_config": {\n    "bucket_span": "5m",\n    "detectors": [\n      {\n        "function": "sum",\n        "field_name": "bytes",\n        "by_field_name": "status",\n        "partition_field_name": "app"\n      }\n    ],\n    "influencers": [\n      "source_ip",\n      "dest_ip"\n    ]\n  },\n  "overall_cardinality": {\n    "status": 10,\n    "app": 50\n  },\n  "max_bucket_cardinality": {\n    "source_ip": 300,\n    "dest_ip": 30\n  }\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({ model_memory_estimate: z.string() })
            .openapi({ required: ['model_memory_estimate'] }),
          examples: {
            MlEstimateModelMemoryResponseExample1: {
              description:
                'A successful response from `POST _ml/anomaly_detectors/_estimate_model_memory`.',
              value: '{\n  "model_memory_estimate": "21mb"\n}',
            },
          },
        },
      },
    },
  },
})

