              value:
                '{\n  "index": "animal_classification",\n  "evaluation": {\n    "classification": {\n      "actual_field": "animal_class",\n      "metrics": {\n        "auc_roc": {\n          "class_name": "dog"\n        }\n      }\n    }\n  }\n}',
