              value:
                '{\n  "index": "house_price_predictions",\n  "query": {\n    "bool": {\n      "filter": [\n        {\n          "term": {\n            "ml.is_training": false\n          }\n        }\n      ]\n    }\n  },\n  "evaluation": {\n    "regression": {\n      "actual_field": "price",\n      "predicted_field": "ml.price_prediction",\n      "metrics": {\n        "r_squared": {},\n        "mse": {},\n        "msle": {\n          "offset": 10\n        },\n        "huber": {\n          "delta": 1.5\n        }\n      }\n    }\n  }\n}',
