export const postMlAnomalyDetectorsJobIdFlushRoute = createRoute({
  method: 'post',
  path: '/_ml/anomaly_detectors/{job_id}/_flush',
  tags: ['ml anomaly'],
  summary: 'Force buffered data to be processed',
  description:
    'The flush jobs API is only applicable when sending data for analysis using\nthe post data API. Depending on the content of the buffer, then it might\nadditionally calculate new results. Both flush and close operations are\nsimilar, however the flush is more efficient if you are expecting to send\nmore data for analysis. When flushing, the job remains open and is available\nto continue analyzing data. A close operation additionally prunes and\npersists the model state to disk and the job must be opened again before\nanalyzing further data.\n\n## Required authorization\n\n* Cluster privileges: `manage_ml`\n',
  operationId: 'ml-flush-job',
  request: {
    params: z.object({
      job_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'job_id',
          description: 'Identifier for the anomaly detection job.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      advance_time: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(TypesDateTimeSchema)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'advance_time',
            description:
              'Specifies to advance to a particular time value. Results are generated\nand the model is updated for data from the specified time interval.',
            deprecated: false,
            schema: { $ref: '#/components/schemas/_types.DateTime' },
            style: 'form',
            required: false,
          },
        }),
      calc_interim: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'calc_interim',
            description:
              'If true, calculates the interim results for the most recent bucket or all\nbuckets within the latency period.',
            deprecated: false,
            schema: { type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      end: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(TypesDateTimeSchema)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'end',
            description:
              'When used in conjunction with `calc_interim` and `start`, specifies the\nrange of buckets on which to calculate interim results.',
            deprecated: false,
            schema: { $ref: '#/components/schemas/_types.DateTime' },
            style: 'form',
            required: false,
          },
        }),
      skip_time: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(TypesDateTimeSchema)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'skip_time',
            description:
              'Specifies to skip to a particular time value. Results are not generated\nand the model is not updated for data from the specified time interval.',
            deprecated: false,
            schema: { $ref: '#/components/schemas/_types.DateTime' },
            style: 'form',
            required: false,
          },
        }),
      start: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(TypesDateTimeSchema)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'start',
            description:
              'When used in conjunction with `calc_interim`, specifies the range of\nbuckets on which to calculate interim results.',
            deprecated: false,
            schema: { $ref: '#/components/schemas/_types.DateTime' },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              advance_time: TypesDateTimeSchema.exactOptional().openapi({
                description: 'Refer to the description for the `advance_time` query parameter.',
              }),
              calc_interim: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Refer to the description for the `calc_interim` query parameter.',
                }),
              end: TypesDateTimeSchema.exactOptional().openapi({
                description: 'Refer to the description for the `end` query parameter.',
              }),
              skip_time: TypesDateTimeSchema.exactOptional().openapi({
                description: 'Refer to the description for the `skip_time` query parameter.',
              }),
              start: TypesDateTimeSchema.exactOptional().openapi({
                description: 'Refer to the description for the `start` query parameter.',
              }),
            })
            .openapi({ required: [] }),
          examples: {
            MlFlushJobExample1: {
              description:
                'An example body for a `POST _ml/anomaly_detectors/low_request_rate/_flush` request.',
              value: '{\n  "calc_interim": true\n}',
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              flushed: z.boolean(),
              last_finalized_bucket_end: z
                .number()
                .exactOptional()
                .openapi({
                  description:
                    'Provides the timestamp (in milliseconds since the epoch) of the end of\nthe last bucket that was processed.',
                }),
            })
            .openapi({ required: ['flushed'] }),
        },
      },
    },
  },
  deprecated: true,
})

