export const getMlAnomalyDetectorsJobIdResultsOverallBucketsRoute = createRoute({
  method: 'get',
  path: '/_ml/anomaly_detectors/{job_id}/results/overall_buckets',
  tags: ['ml anomaly'],
  summary: 'Get overall bucket results',
  description:
    "Retrievs overall bucket results that summarize the bucket results of\nmultiple anomaly detection jobs.\n\nThe `overall_score` is calculated by combining the scores of all the\nbuckets within the overall bucket span. First, the maximum\n`anomaly_score` per anomaly detection job in the overall bucket is\ncalculated. Then the `top_n` of those scores are averaged to result in\nthe `overall_score`. This means that you can fine-tune the\n`overall_score` so that it is more or less sensitive to the number of\njobs that detect an anomaly at the same time. For example, if you set\n`top_n` to `1`, the `overall_score` is the maximum bucket score in the\noverall bucket. Alternatively, if you set `top_n` to the number of jobs,\nthe `overall_score` is high only when all jobs detect anomalies in that\noverall bucket. If you set the `bucket_span` parameter (to a value\ngreater than its default), the `overall_score` is the maximum\n`overall_score` of the overall buckets that have a span equal to the\njobs' largest bucket span.\n\n## Required authorization\n\n* Cluster privileges: `monitor_ml`\n",
  operationId: 'ml-get-overall-buckets',
  request: {
    params: z.object({ job_id: MlGetOverallBucketsJobIdParamsSchema }),
    query: z.object({
      allow_no_match: MlGetOverallBucketsAllowNoMatchParamsSchema,
      bucket_span: MlGetOverallBucketsBucketSpanParamsSchema,
      end: MlGetOverallBucketsEndParamsSchema,
      exclude_interim: MlGetOverallBucketsExcludeInterimParamsSchema,
      overall_score: MlGetOverallBucketsOverallScoreParamsSchema,
      start: MlGetOverallBucketsStartParamsSchema,
      top_n: MlGetOverallBucketsTopNParamsSchema,
    }),
    body: MlGetOverallBucketsRequestBody,
  },
  responses: { 200: MlGetOverallBuckets_200Response },
})

export const postMlAnomalyDetectorsJobIdResultsOverallBucketsRoute = createRoute({
  method: 'post',
  path: '/_ml/anomaly_detectors/{job_id}/results/overall_buckets',
  tags: ['ml anomaly'],
  summary: 'Get overall bucket results',
  description:
    "Retrievs overall bucket results that summarize the bucket results of\nmultiple anomaly detection jobs.\n\nThe `overall_score` is calculated by combining the scores of all the\nbuckets within the overall bucket span. First, the maximum\n`anomaly_score` per anomaly detection job in the overall bucket is\ncalculated. Then the `top_n` of those scores are averaged to result in\nthe `overall_score`. This means that you can fine-tune the\n`overall_score` so that it is more or less sensitive to the number of\njobs that detect an anomaly at the same time. For example, if you set\n`top_n` to `1`, the `overall_score` is the maximum bucket score in the\noverall bucket. Alternatively, if you set `top_n` to the number of jobs,\nthe `overall_score` is high only when all jobs detect anomalies in that\noverall bucket. If you set the `bucket_span` parameter (to a value\ngreater than its default), the `overall_score` is the maximum\n`overall_score` of the overall buckets that have a span equal to the\njobs' largest bucket span.\n\n## Required authorization\n\n* Cluster privileges: `monitor_ml`\n",
  operationId: 'ml-get-overall-buckets-1',
  request: {
    params: z.object({ job_id: MlGetOverallBucketsJobIdParamsSchema }),
    query: z.object({
      allow_no_match: MlGetOverallBucketsAllowNoMatchParamsSchema,
      bucket_span: MlGetOverallBucketsBucketSpanParamsSchema,
      end: MlGetOverallBucketsEndParamsSchema,
      exclude_interim: MlGetOverallBucketsExcludeInterimParamsSchema,
      overall_score: MlGetOverallBucketsOverallScoreParamsSchema,
      start: MlGetOverallBucketsStartParamsSchema,
      top_n: MlGetOverallBucketsTopNParamsSchema,
    }),
    body: MlGetOverallBucketsRequestBody,
  },
  responses: { 200: MlGetOverallBuckets_200Response },
})

export const getMlAnomalyDetectorsJobIdResultsRecordsRoute = createRoute({
  method: 'get',
  path: '/_ml/anomaly_detectors/{job_id}/results/records',
  tags: ['ml anomaly'],
  summary: 'Get anomaly records for an anomaly detection job',
  description:
    'Records contain the detailed analytical results. They describe the anomalous\nactivity that has been identified in the input data based on the detector\nconfiguration.\nThere can be many anomaly records depending on the characteristics and size\nof the input data. In practice, there are often too many to be able to\nmanually process them. The machine learning features therefore perform a\nsophisticated aggregation of the anomaly records into buckets.\nThe number of record results depends on the number of anomalies found in each\nbucket, which relates to the number of time series being modeled and the\nnumber of detectors.\n\n## Required authorization\n\n* Cluster privileges: `monitor_ml`\n',
  operationId: 'ml-get-records',
  request: {
    params: z.object({ job_id: MlGetRecordsJobIdParamsSchema }),
    query: z.object({
      desc: MlGetRecordsDescParamsSchema,
      end: MlGetRecordsEndParamsSchema,
      exclude_interim: MlGetRecordsExcludeInterimParamsSchema,
      from: MlGetRecordsFromParamsSchema,
      record_score: MlGetRecordsRecordScoreParamsSchema,
      size: MlGetRecordsSizeParamsSchema,
      sort: MlGetRecordsSortParamsSchema,
      start: MlGetRecordsStartParamsSchema,
    }),
    body: MlGetRecordsRequestBody,
  },
  responses: { 200: MlGetRecords_200Response },
})

