export const postMlAnomalyDetectorsJobIdOpenRoute = createRoute({
  method: 'post',
  path: '/_ml/anomaly_detectors/{job_id}/_open',
  tags: ['ml anomaly'],
  summary: 'Open anomaly detection jobs',
  description:
    'An anomaly detection job must be opened to be ready to receive and analyze\ndata. It can be opened and closed multiple times throughout its lifecycle.\nWhen you open a new job, it starts with an empty model.\nWhen you open an existing job, the most recent model state is automatically\nloaded. The job is ready to resume its analysis from where it left off, once\nnew data is received.\n\n## Required authorization\n\n* Cluster privileges: `manage_ml`\n',
  operationId: 'ml-open-job',
  request: {
    params: z.object({
      job_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'job_id',
          description: 'Identifier for the anomaly detection job.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      timeout: TypesDurationSchema.default('30m')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'timeout',
            description: 'Controls the time to wait until a job has opened.',
            deprecated: false,
            schema: { default: '30m', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              timeout: TypesDurationSchema.default('30m')
                .exactOptional()
                .openapi({
                  description: 'Refer to the description for the `timeout` query parameter.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            MlOpenJobRequestExample1: {
              description:
                'A request to open anomaly detection jobs. The timeout specifies to wait 35 minutes for the job to open.\n',
              value: '{\n  "timeout": "35m"\n}',
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              opened: z.boolean(),
              node: TypesNodeIdSchema.openapi({
                description:
                  'The ID of the node that the job was started on. In serverless this will be the "serverless".\nIf the job is allowed to open lazily and has not yet been assigned to a node, this value is an empty string.',
              }),
            })
            .openapi({ required: ['opened', 'node'] }),
          examples: {
            MlOpenJobResponseExample1: {
              description: 'A successful response when opening an anomaly detection job.',
              value: '{\n  "opened": true,\n  "node": "node-1"\n}',
            },
          },
        },
      },
    },
  },
})

export const postMlAnomalyDetectorsJobIdDataRoute = createRoute({
  method: 'post',
  path: '/_ml/anomaly_detectors/{job_id}/_data',
  tags: ['ml anomaly'],
  summary: 'Send data to an anomaly detection job for analysis',
  description:
    'IMPORTANT: For each job, data can be accepted from only a single connection at a time.\nIt is not currently possible to post data to multiple jobs using wildcards or a comma-separated list.\n\n## Required authorization\n\n* Cluster privileges: `manage_ml`\n',
  operationId: 'ml-post-data',
  request: {
    params: z.object({
      job_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'job_id',
          description:
            'Identifier for the anomaly detection job. The job must have a state of open to receive and process the data.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      reset_end: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(TypesDateTimeSchema)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'reset_end',
            description: 'Specifies the end of the bucket resetting range.',
            deprecated: false,
            schema: { $ref: '#/components/schemas/_types.DateTime' },
            style: 'form',
            required: false,
          },
        }),
      reset_start: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(TypesDateTimeSchema)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'reset_start',
            description: 'Specifies the start of the bucket resetting range.',
            deprecated: false,
            schema: { $ref: '#/components/schemas/_types.DateTime' },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: { content: { 'application/json': { schema: z.array(z.object({})) } }, required: true },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              job_id: TypesIdSchema,
              processed_record_count: z.number(),
              processed_field_count: z.number(),
              input_bytes: z.number(),
              input_field_count: z.number(),
              invalid_date_count: z.number(),
              missing_field_count: z.number(),
              out_of_order_timestamp_count: z.number(),
              empty_bucket_count: z.number(),
              sparse_bucket_count: z.number(),
              bucket_count: z.number(),
              earliest_record_timestamp: TypesEpochTimeUnitMillisSchema.exactOptional(),
              latest_record_timestamp: TypesEpochTimeUnitMillisSchema.exactOptional(),
              last_data_time: TypesEpochTimeUnitMillisSchema.exactOptional(),
              latest_empty_bucket_timestamp: TypesEpochTimeUnitMillisSchema.exactOptional(),
              latest_sparse_bucket_timestamp: TypesEpochTimeUnitMillisSchema.exactOptional(),
              input_record_count: z.number(),
              log_time: TypesEpochTimeUnitMillisSchema.exactOptional(),
            })
            .openapi({
              required: [
                'job_id',
                'processed_record_count',
                'processed_field_count',
                'input_bytes',
                'input_field_count',
                'invalid_date_count',
                'missing_field_count',
                'out_of_order_timestamp_count',
                'empty_bucket_count',
                'sparse_bucket_count',
                'bucket_count',
                'input_record_count',
              ],
            }),
        },
      },
    },
  },
  deprecated: true,
})

