export const postMlDatafeedsDatafeedIdUpdateRoute = createRoute({
  method: 'post',
  path: '/_ml/datafeeds/{datafeed_id}/_update',
  tags: ['ml anomaly'],
  summary: 'Update a datafeed',
  description:
    'You must stop and start the datafeed for the changes to be applied.\nWhen Elasticsearch security features are enabled, your datafeed remembers which roles the user who updated it had at\nthe time of the update and runs the query using those same roles. If you provide secondary authorization headers,\nthose credentials are used instead.\n\n## Required authorization\n\n* Cluster privileges: `manage_ml`\n',
  operationId: 'ml-update-datafeed',
  request: {
    params: z.object({
      datafeed_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'datafeed_id',
          description:
            'A numerical character string that uniquely identifies the datafeed.\nThis identifier can contain lowercase alphanumeric characters (a-z and 0-9), hyphens, and underscores.\nIt must start and end with alphanumeric characters.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      allow_no_indices: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'allow_no_indices',
            description:
              'A setting that does two separate checks on the index expression.\nIf `false`, the request returns an error (1) if any wildcard expression\n(including `_all` and `*`) resolves to zero matching indices or (2) if the\ncomplete set of resolved indices, aliases or data streams is empty after all\nexpressions are evaluated. If `true`, index expressions that resolve to no\nindices are allowed and the request returns an empty result.',
            deprecated: false,
            schema: { default: true, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      expand_wildcards: TypesExpandWildcardsSchema.default('open')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'expand_wildcards',
            description:
              'Type of index that wildcard patterns can match. If the request can target data streams, this argument determines\nwhether wildcard expressions match hidden data streams. Supports comma-separated values.',
            deprecated: false,
            schema: {
              default: 'open',
              allOf: [{ $ref: '#/components/schemas/_types.ExpandWildcards' }],
            },
            style: 'form',
            required: false,
          },
        }),
      ignore_throttled: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'ignore_throttled',
            description:
              'If `true`, concrete, expanded or aliased indices are ignored when frozen.',
            deprecated: true,
            schema: { default: true, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      ignore_unavailable: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'ignore_unavailable',
            description:
              'If `false`, the request returns an error if it targets a concrete (non-wildcarded)\nindex, alias, or data stream that is missing, closed, or otherwise unavailable.\nIf `true`, unavailable concrete targets are silently ignored.',
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              aggregations: z
                .record(z.string(), TypesAggregationsAggregationContainerSchema)
                .exactOptional()
                .openapi({
                  description:
                    'If set, the datafeed performs aggregation searches. Support for aggregations is limited and should be used only\nwith low cardinality data.',
                }),
              chunking_config: MlTypesChunkingConfigSchema.exactOptional().openapi({
                description:
                  'Datafeeds might search over long time periods, for several months or years. This search is split into time\nchunks in order to ensure the load on Elasticsearch is managed. Chunking configuration controls how the size of\nthese time chunks are calculated; it is an advanced configuration option.',
              }),
              delayed_data_check_config:
                MlTypesDelayedDataCheckConfigSchema.exactOptional().openapi({
                  description:
                    'Specifies whether the datafeed checks for missing data and the size of the window. The datafeed can optionally\nsearch over indices that have already been read in an effort to determine whether any data has subsequently been\nadded to the index. If missing data is found, it is a good indication that the `query_delay` is set too low and\nthe data is being indexed after the datafeed has passed that moment in time. This check runs only on real-time\ndatafeeds.',
                }),
              frequency: TypesDurationSchema.exactOptional().openapi({
                description:
                  'The interval at which scheduled queries are made while the datafeed runs in real time. The default value is\neither the bucket span for short bucket spans, or, for longer bucket spans, a sensible fraction of the bucket\nspan. When `frequency` is shorter than the bucket span, interim results for the last (partial) bucket are\nwritten then eventually overwritten by the full bucket results. If the datafeed uses aggregations, this value\nmust be divisible by the interval of the date histogram aggregation.',
              }),
              indices: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    'An array of index names. Wildcards are supported. If any of the indices are in remote clusters, the machine\nlearning nodes must have the `remote_cluster_client` role.',
                }),
              indices_options: TypesIndicesOptionsSchema.exactOptional().openapi({
                description: 'Specifies index expansion options that are used during search.',
              }),
              job_id: TypesIdSchema.exactOptional(),
              max_empty_searches: z
                .number()
                .exactOptional()
                .openapi({
                  description:
                    'If a real-time datafeed has never seen any data (including during any initial training period), it automatically\nstops and closes the associated job after this many real-time searches return no documents. In other words,\nit stops after `frequency` times `max_empty_searches` of real-time operation. If not set, a datafeed with no\nend time that sees no data remains started until it is explicitly stopped. By default, it is not set.',
                }),
              max_consecutive_extraction_failures: z
                .number()
                .exactOptional()
                .openapi({
                  description:
                    "The maximum number of consecutive real-time data extraction failures the datafeed tolerates before it\nautomatically stops itself, leaving the associated job open. The consecutive-failure counter resets on any\ncycle that extracts successfully, including empty-data cycles. If not set, the threshold defaults to roughly\none day's worth of searches based on the datafeed `frequency` (floored at 1). Set to `-1` to disable auto-stop\nand retry indefinitely. Values of `0` or less than `-1` are rejected.",
                }),
              query: TypesQueryDslQueryContainerSchema.default('{"match_all": {"boost": 1}}')
                .exactOptional()
                .openapi({
                  description:
                    'The Elasticsearch query domain-specific language (DSL). This value corresponds to the query object in an\nElasticsearch search POST body. All the options that are supported by Elasticsearch can be used, as this\nobject is passed verbatim to Elasticsearch. Note that if you change the query, the analyzed data is also\nchanged. Therefore, the time required to learn might be long and the understandability of the results is\nunpredictable. If you want to make significant changes to the source data, it is recommended that you\nclone the job and datafeed and make the amendments in the clone. Let both run in parallel and close one\nwhen you are satisfied with the results of the job.',
                }),
              query_delay: TypesDurationSchema.exactOptional().openapi({
                description:
                  'The number of seconds behind real time that data is queried. For example, if data from 10:04 a.m. might\nnot be searchable in Elasticsearch until 10:06 a.m., set this property to 120 seconds. The default\nvalue is randomly selected between `60s` and `120s`. This randomness improves the query performance\nwhen there are multiple jobs running on the same node.',
              }),
              runtime_mappings: TypesMappingRuntimeFieldsSchema.exactOptional().openapi({
                description: 'Specifies runtime fields for the datafeed search.',
              }),
              script_fields: z
                .record(z.string(), TypesScriptFieldSchema)
                .exactOptional()
                .openapi({
                  description:
                    'Specifies scripts that evaluate custom expressions and returns script fields to the datafeed.\nThe detector configuration objects in a job can contain functions that use these script fields.',
                }),
              scroll_size: z
                .number()
                .default(1000)
                .exactOptional()
                .openapi({
                  description:
                    'The size parameter that is used in Elasticsearch searches when the datafeed does not use aggregations.\nThe maximum value is the value of `index.max_result_window`.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            MlUpdateDatafeedExample1: {
              description:
                'An example body for a `POST _ml/datafeeds/datafeed-test-job/_update` request.',
              value: '{\n  "query": {\n    "term": {\n      "geo.src": "US"\n    }\n  }\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              authorization: MlTypesDatafeedAuthorizationSchema.exactOptional(),
              aggregations: z
                .record(z.string(), TypesAggregationsAggregationContainerSchema)
                .exactOptional(),
              chunking_config: MlTypesChunkingConfigSchema,
              delayed_data_check_config: MlTypesDelayedDataCheckConfigSchema.exactOptional(),
              datafeed_id: TypesIdSchema,
              frequency: TypesDurationSchema.exactOptional().openapi({
                description:
                  'The interval at which scheduled queries are made while the datafeed runs in real time. The default value is either the bucket span for short bucket spans, or, for longer bucket spans, a sensible fraction of the bucket span. For example: `150s`. When `frequency` is shorter than the bucket span, interim results for the last (partial) bucket are written then eventually overwritten by the full bucket results. If the datafeed uses aggregations, this value must be divisible by the interval of the date histogram aggregation.',
              }),
              indices: z.array(z.string()),
              indices_options: TypesIndicesOptionsSchema.exactOptional(),
              job_id: TypesIdSchema,
              max_empty_searches: z.number().exactOptional(),
              max_consecutive_extraction_failures: z.number().exactOptional(),
              query: TypesQueryDslQueryContainerSchema,
              query_delay: TypesDurationSchema,
              runtime_mappings: TypesMappingRuntimeFieldsSchema.exactOptional(),
              script_fields: z.record(z.string(), TypesScriptFieldSchema).exactOptional(),
              scroll_size: z.number(),
            })
            .openapi({
              required: [
                'chunking_config',
                'datafeed_id',
                'indices',
                'job_id',
                'query',
                'query_delay',
                'scroll_size',
              ],
            }),
        },
      },
    },
  },
})

