export const postMlAnomalyDetectorsJobIdUpdateRoute = createRoute({
  method: 'post',
  path: '/_ml/anomaly_detectors/{job_id}/_update',
  tags: ['ml anomaly'],
  summary: 'Update an anomaly detection job',
  description:
    'Updates certain properties of an anomaly detection job.\n\n## Required authorization\n\n* Cluster privileges: `manage_ml`\n',
  operationId: 'ml-update-job',
  request: {
    params: z.object({
      job_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'job_id',
          description: 'Identifier for the job.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              allow_lazy_open: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Advanced configuration option. Specifies whether this job can open when\nthere is insufficient machine learning node capacity for it to be\nimmediately assigned to a node. If `false` and a machine learning node\nwith capacity to run the job cannot immediately be found, the open\nanomaly detection jobs API returns an error. However, this is also\nsubject to the cluster-wide `xpack.ml.max_lazy_ml_nodes` setting. If this\noption is set to `true`, the open anomaly detection jobs API does not\nreturn an error and the job waits in the opening state until sufficient\nmachine learning node capacity is available.',
                }),
              analysis_limits: MlTypesAnalysisMemoryLimitSchema.exactOptional(),
              background_persist_interval: TypesDurationSchema.exactOptional().openapi({
                description:
                  'Advanced configuration option. The time between each periodic persistence\nof the model.\nThe default value is a randomized value between 3 to 4 hours, which\navoids all jobs persisting at exactly the same time. The smallest allowed\nvalue is 1 hour.\nFor very large models (several GB), persistence could take 10-20 minutes,\nso do not set the value too low.\nIf the job is open when you make the update, you must stop the datafeed,\nclose the job, then reopen the job and restart the datafeed for the\nchanges to take effect.',
              }),
              custom_settings: z
                .record(z.string(), z.object({}))
                .exactOptional()
                .openapi({
                  description:
                    'Advanced configuration option. Contains custom meta data about the job.\nFor example, it can contain custom URL information as shown in Adding\ncustom URLs to machine learning results.',
                }),
              categorization_filters: z.array(z.string()).exactOptional(),
              description: z
                .string()
                .exactOptional()
                .openapi({ description: 'A description of the job.' }),
              model_plot_config: MlTypesModelPlotConfigSchema.exactOptional(),
              model_prune_window: TypesDurationSchema.exactOptional(),
              daily_model_snapshot_retention_after_days: z
                .number()
                .default(1)
                .exactOptional()
                .openapi({
                  description:
                    'Advanced configuration option, which affects the automatic removal of old\nmodel snapshots for this job. It specifies a period of time (in days)\nafter which only the first snapshot per day is retained. This period is\nrelative to the timestamp of the most recent snapshot for this job. Valid\nvalues range from 0 to `model_snapshot_retention_days`. For jobs created\nbefore version 7.8.0, the default value matches\n`model_snapshot_retention_days`.',
                }),
              model_snapshot_retention_days: z
                .number()
                .default(10)
                .exactOptional()
                .openapi({
                  description:
                    'Advanced configuration option, which affects the automatic removal of old\nmodel snapshots for this job. It specifies the maximum period of time (in\ndays) that snapshots are retained. This period is relative to the\ntimestamp of the most recent snapshot for this job.',
                }),
              renormalization_window_days: z
                .number()
                .exactOptional()
                .openapi({
                  description:
                    'Advanced configuration option. The period over which adjustments to the\nscore are applied, as new data is seen.',
                }),
              results_retention_days: z
                .number()
                .exactOptional()
                .openapi({
                  description:
                    'Advanced configuration option. The period of time (in days) that results\nare retained. Age is calculated relative to the timestamp of the latest\nbucket result. If this property has a non-null value, once per day at\n00:30 (server time), results that are the specified number of days older\nthan the latest bucket result are deleted from Elasticsearch. The default\nvalue is null, which means all results are retained.',
                }),
              groups: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description: 'A list of job groups. A job can belong to no groups or many.',
                }),
              detectors: z
                .xor([MlTypesDetectorUpdateSchema, z.array(MlTypesDetectorUpdateSchema)])
                .exactOptional()
                .openapi({
                  description: 'A detector update object or an array of detector update objects.',
                }),
              per_partition_categorization:
                MlTypesPerPartitionCategorizationSchema.exactOptional().openapi({
                  description:
                    'Settings related to how categorization interacts with partition fields.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            MlUpdateJobExample1: {
              description:
                'An example body for a `POST _ml/anomaly_detectors/low_request_rate/_update` request.',
              value:
                '{\n  "description":"An updated job",\n  "detectors": {\n    "detector_index": 0,\n    "description": "An updated detector description"\n  },\n  "groups": ["kibana_sample_data","kibana_sample_web_logs"],\n  "model_plot_config": {\n    "enabled": true\n  },\n  "renormalization_window_days": 30,\n  "background_persist_interval": "2h",\n  "model_snapshot_retention_days": 7,\n  "results_retention_days": 60\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              allow_lazy_open: z.boolean(),
              analysis_config: MlTypesAnalysisConfigReadSchema,
              analysis_limits: MlTypesAnalysisLimitsSchema,
              background_persist_interval: TypesDurationSchema.exactOptional(),
              create_time: TypesEpochTimeUnitMillisSchema,
              finished_time: TypesEpochTimeUnitMillisSchema.exactOptional(),
              custom_settings: z.record(z.string(), z.string()).exactOptional(),
              daily_model_snapshot_retention_after_days: z.number(),
              data_description: MlTypesDataDescriptionSchema,
              datafeed_config: MlTypesDatafeedSchema.exactOptional(),
              description: z.string().exactOptional(),
              groups: z.array(z.string()).exactOptional(),
              job_id: TypesIdSchema,
              job_type: z.string(),
              job_version: TypesVersionStringSchema,
              model_plot_config: MlTypesModelPlotConfigSchema.exactOptional(),
              model_snapshot_id: TypesIdSchema.exactOptional(),
              model_snapshot_retention_days: z.number(),
              renormalization_window_days: z.number().exactOptional(),
              results_index_name: TypesIndexNameSchema,
              results_retention_days: z.number().exactOptional(),
            })
            .openapi({
              required: [
                'allow_lazy_open',
                'analysis_config',
                'analysis_limits',
                'create_time',
                'daily_model_snapshot_retention_after_days',
                'data_description',
                'job_id',
                'job_type',
                'job_version',
                'model_snapshot_retention_days',
                'results_index_name',
              ],
            }),
        },
      },
    },
  },
})

