export const postMlTrainedModelsModelIdDeploymentUpdateRoute = createRoute({
  method: 'post',
  path: '/_ml/trained_models/{model_id}/deployment/_update',
  tags: ['ml trained model'],
  summary: 'Update a trained model deployment',
  description: '\n\n## Required authorization\n\n* Cluster privileges: `manage_ml`\n',
  operationId: 'ml-update-trained-model-deployment',
  request: {
    params: z.object({
      model_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'model_id',
          description:
            'The unique identifier of the trained model. Currently, only PyTorch models are supported.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      number_of_allocations: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'number_of_allocations',
            description:
              'The number of model allocations on each node where the model is deployed.\nAll allocations on a node share the same copy of the model in memory but use\na separate set of threads to evaluate the model.\nIncreasing this value generally increases the throughput.\nIf this setting is greater than the number of hardware threads\nit will automatically be changed to a value less than the number of hardware threads.',
            deprecated: false,
            schema: { default: 1, type: 'number' },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              number_of_allocations: z
                .number()
                .default(1)
                .exactOptional()
                .openapi({
                  description:
                    'The number of model allocations on each node where the model is deployed.\nAll allocations on a node share the same copy of the model in memory but use\na separate set of threads to evaluate the model.\nIncreasing this value generally increases the throughput.\nIf this setting is greater than the number of hardware threads\nit will automatically be changed to a value less than the number of hardware threads.\nIf adaptive_allocations is enabled, do not set this value, because it’s automatically set.',
                }),
              adaptive_allocations:
                MlTypesAdaptiveAllocationsSettingsSchema.exactOptional().openapi({
                  description:
                    'Adaptive allocations configuration. When enabled, the number of allocations\nis set based on the current load.\nIf adaptive_allocations is enabled, do not set the number of allocations manually.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            MlUpdateTrainedModelDeploymentExample1: {
              description:
                'An example body for a `POST _ml/trained_models/elastic__distilbert-base-uncased-finetuned-conll03-english/deployment/_update` request.',
              value: '{\n  "number_of_allocations": 4\n}',
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({ assignment: MlTypesTrainedModelAssignmentSchema })
            .openapi({ required: ['assignment'] }),
        },
      },
    },
  },
})

export const postMlAnomalyDetectorsJobIdModelSnapshotsSnapshotIdUpgradeRoute = createRoute({
  method: 'post',
  path: '/_ml/anomaly_detectors/{job_id}/model_snapshots/{snapshot_id}/_upgrade',
  tags: ['ml anomaly'],
  summary: 'Upgrade a snapshot',
  description:
    'Upgrade an anomaly detection model snapshot to the latest major version.\nOver time, older snapshot formats are deprecated and removed. Anomaly\ndetection jobs support only snapshots that are from the current or previous\nmajor version.\nThis API provides a means to upgrade a snapshot to the current major version.\nThis aids in preparing the cluster for an upgrade to the next major version.\nOnly one snapshot per anomaly detection job can be upgraded at a time and the\nupgraded snapshot cannot be the current snapshot of the anomaly detection\njob.\n\n## Required authorization\n\n* Cluster privileges: `manage_ml`\n',
  operationId: 'ml-upgrade-job-snapshot',
  request: {
    params: z.object({
      job_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'job_id',
          description: 'Identifier for the anomaly detection job.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
      snapshot_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'snapshot_id',
          description: 'A numerical character string that uniquely identifies the model snapshot.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      wait_for_completion: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'wait_for_completion',
            description:
              'When true, the API won’t respond until the upgrade is complete.\nOtherwise, it responds as soon as the upgrade task is assigned to a node.',
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      timeout: TypesDurationSchema.default('30m')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'timeout',
            description: 'Controls the time to wait for the request to complete.',
            deprecated: false,
            schema: { default: '30m', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              node: TypesNodeIdSchema.openapi({
                description:
                  'The ID of the node that the upgrade task was started on if it is still running. In serverless this will be the "serverless".',
              }),
              completed: z
                .boolean()
                .openapi({
                  description:
                    'When true, this means the task is complete. When false, it is still running.',
                }),
            })
            .openapi({ required: ['node', 'completed'] }),
        },
      },
    },
  },
})

export const getMsearchRoute = createRoute({
  method: 'get',
  path: '/_msearch',
  tags: ['search'],
  summary: 'Run multiple searches',
  description:
    'The format of the request is similar to the bulk API format and makes use of the newline delimited JSON (NDJSON) format.\nThe structure is as follows:\n\n```\nheader\\n\nbody\\n\nheader\\n\nbody\\n\n```\n\nThis structure is specifically optimized to reduce parsing if a specific search ends up redirected to another node.\n\nIMPORTANT: The final line of data must end with a newline character `\\n`.\nEach newline character may be preceded by a carriage return `\\r`.\nWhen sending requests to this endpoint the `Content-Type` header should be set to `application/x-ndjson`.\n\n## Required authorization\n\n* Index privileges: `read`\n',
  operationId: 'msearch',
  request: {
    query: z.object({
      allow_no_indices: MsearchAllowNoIndicesParamsSchema,
      ccs_minimize_roundtrips: MsearchCcsMinimizeRoundtripsParamsSchema,
      expand_wildcards: MsearchExpandWildcardsParamsSchema,
      ignore_throttled: MsearchIgnoreThrottledParamsSchema,
      ignore_unavailable: MsearchIgnoreUnavailableParamsSchema,
      include_named_queries_score: MsearchIncludeNamedQueriesScoreParamsSchema,
      index: MsearchIndex_2ParamsSchema,
      max_concurrent_searches: MsearchMaxConcurrentSearchesParamsSchema,
      max_concurrent_shard_requests: MsearchMaxConcurrentShardRequestsParamsSchema,
      pre_filter_shard_size: MsearchPreFilterShardSizeParamsSchema,
      rest_total_hits_as_int: MsearchRestTotalHitsAsIntParamsSchema,
      routing: MsearchRoutingParamsSchema,
      search_type: MsearchSearchTypeParamsSchema,
      typed_keys: MsearchTypedKeysParamsSchema,
    }),
    body: MsearchRequestBody,
  },
  responses: { 200: Msearch_200Response },
})

