export const getMtermvectorsRoute = createRoute({
  method: 'get',
  path: '/_mtermvectors',
  tags: ['document'],
  summary: 'Get multiple term vectors',
  description:
    'Get multiple term vectors with a single request.\nYou can specify existing documents by index and ID or provide artificial documents in the body of the request.\nYou can specify the index in the request body or request URI.\nThe response contains a `docs` array with all the fetched termvectors.\nEach element has the structure provided by the termvectors API.\n\n**Artificial documents**\n\nYou can also use `mtermvectors` to generate term vectors for artificial documents provided in the body of the request.\nThe mapping used is determined by the specified `_index`.\n\n## Required authorization\n\n* Index privileges: `read`\n',
  operationId: 'mtermvectors',
  request: {
    query: z.object({
      ids: MtermvectorsIdsParamsSchema,
      fields: MtermvectorsFieldsParamsSchema,
      field_statistics: MtermvectorsFieldStatisticsParamsSchema,
      offsets: MtermvectorsOffsetsParamsSchema,
      payloads: MtermvectorsPayloadsParamsSchema,
      positions: MtermvectorsPositionsParamsSchema,
      preference: MtermvectorsPreferenceParamsSchema,
      realtime: MtermvectorsRealtimeParamsSchema,
      routing: MtermvectorsRoutingParamsSchema,
      term_statistics: MtermvectorsTermStatisticsParamsSchema,
      version: MtermvectorsVersionParamsSchema,
      version_type: MtermvectorsVersionTypeParamsSchema,
    }),
    body: MtermvectorsRequestBody,
  },
  responses: { 200: Mtermvectors_200Response },
})

