export const deleteNodesNodeIdRepositoriesMeteringMaxArchiveVersionRoute = createRoute({
  method: 'delete',
  path: '/_nodes/{node_id}/_repositories_metering/{max_archive_version}',
  tags: ['cluster'],
  summary: 'Clear the archived repositories metering',
  description:
    'Clear the archived repositories metering information in the cluster.\n\n## Required authorization\n\n* Cluster privileges: `monitor`,`manage`\n',
  operationId: 'nodes-clear-repositories-metering-archive',
  request: {
    params: z.object({
      node_id: TypesNodeIdsSchema.openapi({
        param: {
          in: 'path',
          name: 'node_id',
          description:
            'Comma-separated list of node IDs or names used to limit returned information.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.NodeIds' },
          style: 'simple',
        },
      }),
      max_archive_version: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .openapi({
          param: {
            in: 'path',
            name: 'max_archive_version',
            description: 'Specifies the maximum `archive_version` to be cleared from the archive.',
            required: true,
            deprecated: false,
            schema: { type: 'number' },
            style: 'simple',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': { schema: NodesClearRepositoriesMeteringArchiveResponseBaseSchema },
      },
    },
  },
})

