export const postNodesReloadSecureSettingsRoute = createRoute({
  method: 'post',
  path: '/_nodes/reload_secure_settings',
  tags: ['cluster'],
  summary: 'Reload the keystore on nodes in the cluster',
  description:
    'Secure settings are stored in an on-disk keystore. Certain of these settings are reloadable.\nThat is, you can change them on disk and reload them without restarting any nodes in the cluster.\nWhen you have updated reloadable secure settings in your keystore, you can use this API to reload those settings on each node.\n\nWhen the Elasticsearch keystore is password protected and not simply obfuscated, you must provide the password for the keystore when you reload the secure settings.\nReloading the settings for the whole cluster assumes that the keystores for all nodes are protected with the same password; this method is allowed only when inter-node communications are encrypted.\nAlternatively, you can reload the secure settings on each node by locally accessing the API and passing the node-specific Elasticsearch keystore password.',
  operationId: 'nodes-reload-secure-settings',
  request: {
    query: z.object({ timeout: NodesReloadSecureSettingsTimeoutParamsSchema }),
    body: NodesReloadSecureSettingsRequestBody,
  },
  responses: { 200: NodesReloadSecureSettings_200Response },
})

