export const putQueryRulesRulesetIdRuleRuleIdRoute = createRoute({
  method: 'put',
  path: '/_query_rules/{ruleset_id}/_rule/{rule_id}',
  tags: ['query_rules'],
  summary: 'Create or update a query rule',
  description:
    'Create or update a query rule within a query ruleset.\n\nIMPORTANT: Due to limitations within pinned queries, you can only pin documents using ids or docs, but cannot use both in single rule.\nIt is advised to use one or the other in query rulesets, to avoid errors.\nAdditionally, pinned queries have a maximum limit of 100 pinned hits.\nIf multiple matching rules pin more than 100 documents, only the first 100 documents are pinned in the order they are specified in the ruleset.\n\n## Required authorization\n\n* Cluster privileges: `manage_search_query_rules`\n',
  externalDocs: {
    description: 'About editing rules and rulesets',
    url: 'https://www.elastic.co/docs/solutions/search/query-rules-ui#edit-a-rule',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/put-query-rule.html',
  },
  operationId: 'query-rules-put-rule',
  request: {
    params: z.object({
      ruleset_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'ruleset_id',
          description:
            'The unique identifier of the query ruleset containing the rule to be created or updated.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
      rule_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'rule_id',
          description:
            'The unique identifier of the query rule within the specified ruleset to be created or updated.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              type: QueryRulesTypesQueryRuleTypeSchema.openapi({
                description: 'The type of rule.',
              }),
              criteria: z
                .xor([
                  QueryRulesTypesQueryRuleCriteriaSchema,
                  z.array(QueryRulesTypesQueryRuleCriteriaSchema),
                ])
                .openapi({
                  description:
                    'The criteria that must be met for the rule to be applied.\nIf multiple criteria are specified for a rule, all criteria must be met for the rule to be applied.',
                }),
              actions: QueryRulesTypesQueryRuleActionsSchema.openapi({
                description:
                  'The actions to take when the rule is matched.\nThe format of this action depends on the rule type.',
              }),
              priority: z.number().exactOptional(),
            })
            .openapi({ required: ['type', 'criteria', 'actions'] }),
          examples: {
            QueryRulePutRequestExample1: {
              description:
                'Run `POST _query_rules/my-ruleset/_test` to test a ruleset. Provide the match criteria that you want to test against.\n',
              value: '{\n  "match_criteria": {\n    "query_string": "puggles"\n  }\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z.object({ result: TypesResultSchema }).openapi({ required: ['result'] }),
        },
      },
    },
  },
})

