export const postReindexTaskIdRethrottleRoute = createRoute({
  method: 'post',
  path: '/_reindex/{task_id}/_rethrottle',
  tags: ['document'],
  summary: 'Throttle a reindex operation',
  description:
    'Change the maximum number of documents to index per second for a particular reindex operation.\nFor example, to unthrottle to unlimited documents per second:\n\n```\nPOST _reindex/r1A2WoRbTwKZ516z6NEs5A:36619/_rethrottle?requests_per_second=-1\n```\n\nRethrottling that speeds up the query takes effect immediately.\nRethrottling that slows down the query will take effect after completing the current batch of documents.\nThis behavior prevents scroll timeouts.\n\nThis API follows reindex tasks across node-shutdown relocations, so callers can keep using\nthe original task ID throughout the lifetime of the operation.\nThe relocated task ID is also accepted and is followed transparently.\nIn either case, returned task IDs and timings reflect the original task, not its relocated successor.\n\nThe rethrottle may not have been applied to any tasks if either `node_failures` or `task_failures` are non-empty, or if the response contains\nno successfully rethrottled tasks — that is, no entries under `nodes` (returned with the default\n`group_by=nodes` in stack) or under `tasks` (returned in serverless, or in stack with\n`group_by=none` or `group_by=parents`).',
  operationId: 'reindex-rethrottle',
  request: {
    params: z.object({
      task_id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'task_id',
          description:
            'The task identifier, returned when creating a reindex task, or by listing tasks via\n`GET /_reindex` or `GET /_tasks`.\nIn stack, can be either the original task ID or the task ID of the relocated task.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      requests_per_second: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .openapi({
          param: {
            in: 'query',
            name: 'requests_per_second',
            description:
              'The maximum number of documents to index per second, across the entire reindex operation (including slices).\nIt can be either `-1` to turn off throttling or any decimal number like `1.7` or `12` to throttle to that level.',
            required: true,
            deprecated: false,
            schema: { type: 'number' },
            style: 'form',
          },
        }),
      group_by: TasksTypesGroupBySchema.default('nodes')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'group_by',
            description:
              'The way to group the tasks in the response.\nWe recommend setting this to `none`, which provides the cleanest response format.',
            deprecated: false,
            schema: {
              default: 'nodes',
              allOf: [{ $ref: '#/components/schemas/tasks._types.GroupBy' }],
            },
            'x-state': 'Generally available',
            style: 'form',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              node_failures: z
                .array(TypesErrorCauseSchema)
                .exactOptional()
                .openapi({
                  description:
                    'Node-level failures encountered while applying the rethrottle request.\nWill return a `failed_node_exception` wrapping a `no_such_node_exception`,\nif a node handling the task either never existed, or has left the cluster, and one of the following is true:\n1. The task has completed.\n2. The task cannot be found.\n\nNote: Rethrottle handles relocations, so it should succeed if the task can be found and has not completed.',
                }),
              task_failures: z
                .array(TypesTaskFailureSchema)
                .exactOptional()
                .openapi({
                  description:
                    'Per-task failures encountered while applying the rethrottle.\nIf a rethrottle is attempted during a relocation handoff, the failure object reports `status: SERVICE_UNAVAILABLE` (the HTTP response itself is still `200 OK`).\nIn this case, the request can be retried until success.',
                }),
              nodes: z
                .record(z.string(), GlobalReindexRethrottleReindexNodeSchema)
                .exactOptional()
                .openapi({
                  description:
                    'Tasks grouped by node, returned only when `group_by=nodes` (the default).',
                }),
              tasks: GlobalReindexRethrottleReindexTasksSchema.exactOptional().openapi({
                description:
                  'The tasks that were successfully rethrottled.\nAlways returned in serverless.\nReturned with `group_by=none` or `group_by=parents` in stack.',
              }),
            })
            .openapi({ required: [] }),
          examples: {
            ReindexRethrottleResponseExample1: {
              summary: 'Successful rethrottle',
              description:
                'A successful response from `POST _reindex/{task_id}/_rethrottle?requests_per_second=10`. This is the response shape always returned in serverless, and in stack only when `group_by=none`. Task IDs and timings reflect the original task across node-shutdown relocations.\n',
              value:
                '{\n  "tasks": [\n    {\n      "node": "r1A2WoRbTwKZ516z6NEs5A",\n      "id": 36619,\n      "type": "transport",\n      "action": "indices:data/write/reindex",\n      "status": {\n        "total": 11500,\n        "updated": 0,\n        "created": 4000,\n        "deleted": 0,\n        "batches": 4,\n        "version_conflicts": 0,\n        "noops": 0,\n        "retries": {\n          "bulk": 0,\n          "search": 0\n        },\n        "throttled_millis": 0,\n        "requests_per_second": 10.0,\n        "throttled_until_millis": 0\n      },\n      "description": "reindex from [my-source-index] to [my-dest-index]",\n      "start_time_in_millis": 1762190000000,\n      "running_time_in_nanos": 4200000000,\n      "cancellable": true,\n      "headers": {}\n    }\n  ]\n}',
            },
            ReindexRethrottleResponseExample2: {
              summary: "Task ID's node is not in the cluster",
              description:
                "A successful response from `POST _reindex/{task_id}/_rethrottle` when the task ID's node is not in the cluster (for example, the node was shut down without relocation, or the task ID was never valid). The empty `tasks` array and `failed_node_exception` wrapping a `no_such_node_exception` indicate the task is gone.\n",
              value:
                '{\n  "node_failures": [\n    {\n      "type": "failed_node_exception",\n      "reason": "Failed node [non_existing_node]",\n      "node_id": "non_existing_node",\n      "caused_by": {\n        "type": "no_such_node_exception",\n        "reason": "No such node [non_existing_node]",\n        "node_id": "non_existing_node"\n      }\n    }\n  ],\n  "tasks": []\n}',
            },
            ReindexRethrottleResponseRelocationExample1: {
              summary: 'Rethrottle during relocation (HTTP 200)',
              description:
                'While the HTTP status remains `200 OK`, a rethrottle sent during a node-shutdown relocation handoff can return `task_failures` with `status: SERVICE_UNAVAILABLE` and a `status_exception` cause. Retry with the same task ID; the retry follows the relocated task until it succeeds.\n',
              value:
                '{\n  "task_failures": [\n    {\n      "task_id": 36619,\n      "node_id": "r1A2WoRbTwKZ516z6NEs5A",\n      "status": "SERVICE_UNAVAILABLE",\n      "reason": {\n        "type": "status_exception",\n        "reason": "cannot rethrottle, task is being relocated"\n      }\n    }\n  ],\n  "tasks": {}\n}',
            },
          },
        },
      },
    },
  },
})

