export const getIndexRollupSearchRoute = createRoute({
  method: 'get',
  path: '/{index}/_rollup_search',
  tags: ['rollup'],
  summary: 'Search rolled-up data',
  description:
    'The rollup search endpoint is needed because, internally, rolled-up documents utilize a different document structure than the original data.\nIt rewrites standard Query DSL into a format that matches the rollup documents then takes the response and rewrites it back to what a client would expect given the original query.\n\nThe request body supports a subset of features from the regular search API.\nThe following functionality is not available:\n\n`size`: Because rollups work on pre-aggregated data, no search hits can be returned and so size must be set to zero or omitted entirely.\n`highlighter`, `suggestors`, `post_filter`, `profile`, `explain`: These are similarly disallowed.\n\nFor more detailed examples of using the rollup search API, including querying rolled-up data only or combining rolled-up and live data, refer to the External documentation.',
  externalDocs: {
    description: 'Getting started with rollups',
    url: 'https://www.elastic.co/docs/manage-data/lifecycle/rollup/getting-started-api#historical-only-search-example',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/rollup-search.html',
  },
  operationId: 'rollup-rollup-search',
  request: {
    params: z.object({ index: RollupRollupSearchIndexParamsSchema }),
    query: z.object({
      rest_total_hits_as_int: RollupRollupSearchRestTotalHitsAsIntParamsSchema,
      typed_keys: RollupRollupSearchTypedKeysParamsSchema,
    }),
    body: RollupRollupSearchRequestBody,
  },
  responses: { 200: RollupRollupSearch_200Response },
  deprecated: true,
})

