export const getApplicationSearchApplicationRoute = createRoute({
  method: 'get',
  path: '/_application/search_application',
  tags: ['search_application'],
  summary: 'Get search applications',
  description:
    'Get information about search applications.\n\n## Required authorization\n\n* Cluster privileges: `manage_search_application`\n',
  operationId: 'search-application-list',
  request: {
    query: z.object({
      q: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'q',
            description: 'Query in the Lucene query string syntax.',
            deprecated: false,
            schema: { type: 'string' },
            style: 'form',
            required: false,
          },
        }),
      from: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .default(0)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'from',
            description: 'Starting offset.',
            deprecated: false,
            schema: { default: 0, type: 'number' },
            style: 'form',
            required: false,
          },
        }),
      size: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'size',
            description: 'Specifies a max number of results to get.',
            deprecated: false,
            schema: { type: 'number' },
            style: 'form',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              count: z.number(),
              results: z.array(SearchApplicationTypesSearchApplicationSchema),
            })
            .openapi({ required: ['count', 'results'] }),
          examples: {
            SearchApplicationsListResponseExample1: {
              description:
                'A succesful response from `GET _application/search_application?from=0&size=3&q=app*` returns the first three search applications whose names start with `app`.',
              value:
                '{\n  "count": 2,\n  "results": [\n    {\n      "name": "app-1",\n      "updated_at_millis": 1690981129366\n    },\n    {\n      "name": "app-2",\n      "updated_at_millis": 1691501823939\n    }\n  ]\n}',
            },
          },
        },
      },
    },
  },
})

