export const postApplicationSearchApplicationNameRenderQueryRoute = createRoute({
  method: 'post',
  path: '/_application/search_application/{name}/_render_query',
  tags: ['search_application'],
  summary: 'Render a search application query',
  description:
    "Generate an Elasticsearch query using the specified query parameters and the search template associated with the search application or a default template if none is specified.\nIf a parameter used in the search template is not specified in `params`, the parameter's default value will be used.\nThe API returns the specific Elasticsearch query that would be generated and run by calling the search application search API.\n\nYou must have `read` privileges on the backing alias of the search application.",
  operationId: 'search-application-render-query',
  request: {
    params: z.object({
      name: TypesNameSchema.openapi({
        param: {
          in: 'path',
          name: 'name',
          description: 'The name of the search application to render teh query for.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Name' },
          style: 'simple',
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({ params: z.record(z.string(), z.object({})).exactOptional() })
            .openapi({ required: [] }),
          examples: {
            SearchApplicationsRenderQueryRequestExample1: {
              description:
                'Run `POST _application/search_application/my-app/_render_query` to generate a query for a search application called `my-app` that uses the search template.',
              value:
                '{\n  "params": {\n    "query_string": "my first query",\n    "text_fields": [\n      {\n        "name": "title",\n        "boost": 5\n      },\n      {\n        "name": "description",\n        "boost": 1\n      }\n    ]\n  }\n}',
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z.object({}),
          examples: {
            SearchApplicationsRenderQueryResponseExample1: {
              description:
                'A successful response for generating a query for a search application. The `from`, `size`, and `explain` parameters were not specified in the request, so the default values specified in the search template are used.',
              value:
                '{\n  "from": 0,\n  "size": 10,\n  "query": {\n    "multi_match": {\n      "query": "my first query",\n      "fields": [\n        "description^1.0",\n        "title^5.0"\n      ]\n    }\n  },\n  "explain": false\n}',
            },
          },
        },
      },
    },
  },
})

