export const getSearchShardsRoute = createRoute({
  method: 'get',
  path: '/_search_shards',
  tags: ['search'],
  summary: 'Get the search shards',
  description:
    'Get the indices and shards that a search request would be run against.\nThis information can be useful for working out issues or planning optimizations with routing and shard preferences.\nWhen filtered aliases are used, the filter is returned as part of the `indices` section.\n\nIf the Elasticsearch security features are enabled, you must have the `view_index_metadata` or `manage` index privilege for the target data stream, index, or alias.\n\n## Required authorization\n\n* Index privileges: `view_index_metadata`\n',
  operationId: 'search-shards',
  request: {
    query: z.object({
      allow_no_indices: SearchShardsAllowNoIndicesParamsSchema,
      expand_wildcards: SearchShardsExpandWildcardsParamsSchema,
      ignore_unavailable: SearchShardsIgnoreUnavailableParamsSchema,
      local: SearchShardsLocalParamsSchema,
      master_timeout: SearchShardsMasterTimeoutParamsSchema,
      preference: SearchShardsPreferenceParamsSchema,
      routing: SearchShardsRoutingParamsSchema,
    }),
  },
  responses: { 200: SearchShards_200Response },
})

