export const postSnapshotRepositorySnapshotMountRoute = createRoute({
  method: 'post',
  path: '/_snapshot/{repository}/{snapshot}/_mount',
  tags: ['searchable_snapshots'],
  summary: 'Mount a snapshot',
  description:
    'Mount a snapshot as a searchable snapshot index.\nDo not use this API for snapshots managed by index lifecycle management (ILM).\nManually mounting ILM-managed snapshots can interfere with ILM processes.\n\n## Required authorization\n\n* Index privileges: `manage`\n* Cluster privileges: `manage`\n',
  operationId: 'searchable-snapshots-mount',
  request: {
    params: z.object({
      repository: TypesNameSchema.openapi({
        param: {
          in: 'path',
          name: 'repository',
          description: 'The name of the repository containing the snapshot of the index to mount.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Name' },
          style: 'simple',
        },
      }),
      snapshot: TypesNameSchema.openapi({
        param: {
          in: 'path',
          name: 'snapshot',
          description: 'The name of the snapshot of the index to mount.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Name' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      master_timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'master_timeout',
            description:
              'The period to wait for the master node.\nIf the master node is not available before the timeout expires, the request fails and returns an error.\nTo indicate that the request should never timeout, set it to `-1`.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
      wait_for_completion: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'wait_for_completion',
            description: 'If true, the request blocks until the operation is complete.',
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      storage: SearchableSnapshotsMountStorageOptionSchema.default('full_copy')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'storage',
            description:
              'The mount option for the searchable snapshot index.\nFor further information on mount options, refer to: [Mount options](https://www.elastic.co/docs/deploy-manage/tools/snapshot-and-restore/searchable-snapshots#searchable-snapshot-mount-storage-options)',
            deprecated: false,
            schema: {
              default: 'full_copy',
              allOf: [{ $ref: '#/components/schemas/searchable_snapshots.mount.StorageOption' }],
            },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              index: TypesIndexNameSchema.openapi({
                description:
                  'The name of the index contained in the snapshot whose data is to be mounted.\nIf no `renamed_index` is specified, this name will also be used to create the new index.',
              }),
              renamed_index: TypesIndexNameSchema.exactOptional().openapi({
                description: 'The name of the index that will be created.',
              }),
              index_settings: z
                .record(z.string(), z.object({}))
                .exactOptional()
                .openapi({
                  description: 'The settings that should be added to the index when it is mounted.',
                }),
              ignore_index_settings: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    'The names of settings that should be removed from the index when it is mounted.',
                }),
            })
            .openapi({ required: ['index'] }),
          examples: {
            SearchableSnapshotsMountSnapshotRequestExample1: {
              description:
                'Run `POST /_snapshot/my_repository/my_snapshot/_mount?wait_for_completion=true` to mount the index `my_docs` from an existing snapshot named `my_snapshot` stored in `my_repository` as a new index `docs`.\n',
              value:
                '{\n  "index": "my_docs",\n  "renamed_index": "docs",\n  "index_settings": {\n    "index.number_of_replicas": 0\n  },\n  "ignore_index_settings": [ "index.refresh_interval" ]\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({ snapshot: SearchableSnapshotsMountMountedSnapshotSchema })
            .openapi({ required: ['snapshot'] }),
        },
      },
    },
  },
})

