export const postSecurityApiKeyBulkUpdateRoute = createRoute({
  method: 'post',
  path: '/_security/api_key/_bulk_update',
  tags: ['security'],
  summary: 'Bulk update API keys',
  description:
    "Update the attributes for multiple API keys.\n\nIMPORTANT: It is not possible to use an API key as the authentication credential for this API. To update API keys, the owner user's credentials are required.\n\nThis API is similar to the update API key API but enables you to apply the same update to multiple API keys in one API call. This operation can greatly improve performance over making individual updates.\n\nIt is not possible to update expired or invalidated API keys.\n\nThis API supports updates to API key access scope, metadata and expiration.\nThe access scope of each API key is derived from the `role_descriptors` you specify in the request and a snapshot of the owner user's permissions at the time of the request.\nThe snapshot of the owner's permissions is updated automatically on every call.\n\nIMPORTANT: If you don't specify `role_descriptors` in the request, a call to this API might still change an API key's access scope. This change can occur if the owner user's permissions have changed since the API key was created or last modified.\n\nA successful request returns a JSON structure that contains the IDs of all updated API keys, the IDs of API keys that already had the requested changes and did not require an update, and error details for any failed update.\n\n## Required authorization\n\n* Cluster privileges: `manage_own_api_key`\n",
  operationId: 'security-bulk-update-api-keys',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              expiration: TypesDurationSchema.exactOptional().openapi({
                description:
                  'Expiration time for the API keys.\nBy default, API keys never expire.\nThis property can be omitted to leave the value unchanged.',
              }),
              ids: z
                .xor([z.string(), z.array(z.string())])
                .openapi({ description: 'The API key identifiers.' }),
              metadata: TypesMetadataSchema.exactOptional().openapi({
                description:
                  'Arbitrary nested metadata to associate with the API keys.\nWithin the `metadata` object, top-level keys beginning with an underscore (`_`) are reserved for system usage.\nAny information specified with this parameter fully replaces metadata previously associated with the API key.',
              }),
              role_descriptors: z
                .record(z.string(), SecurityTypesRoleDescriptorSchema)
                .exactOptional()
                .openapi({
                  description:
                    "The role descriptors to assign to the API keys.\nAn API key's effective permissions are an intersection of its assigned privileges and the point-in-time snapshot of permissions of the owner user.\nYou can assign new privileges by specifying them in this parameter.\nTo remove assigned privileges, supply the `role_descriptors` parameter as an empty object `{}`.\nIf an API key has no assigned privileges, it inherits the owner user's full permissions.\nThe snapshot of the owner's permissions is always updated, whether you supply the `role_descriptors` parameter.\nThe structure of a role descriptor is the same as the request for the create API keys API.",
                }),
            })
            .openapi({ required: ['ids'] }),
          examples: {
            SecurityBulkUpdateApiKeysRequestExample1: {
              description:
                'Assign new role descriptors and metadata and update the expiration time for two API keys.',
              value:
                '{\n  "ids": [\n    "VuaCfGcBCdbkQm-e5aOx",\n    "H3_AhoIBA9hmeQJdg7ij"\n  ],\n  "role_descriptors": {\n    "role-a": {\n      "indices": [\n        {\n          "names": [\n            "*"\n          ],\n          "privileges": [\n            "write"\n          ]\n        }\n      ]\n    }\n  },\n  "metadata": {\n    "environment": {\n      "level": 2,\n      "trusted": true,\n      "tags": [\n        "production"\n      ]\n    }\n  },\n  "expiration": "30d"\n}',
            },
            SecurityBulkUpdateApiKeysRequestExample2: {
              description:
                "Remove the previously assigned permissions for two API keys, making them inherit the owner user's full permissions.",
              value:
                '{\n  "ids": [\n    "VuaCfGcBCdbkQm-e5aOx",\n    "H3_AhoIBA9hmeQJdg7ij"\n  ],\n  "role_descriptors": {}\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: SecurityTypesBulkErrorSchema.exactOptional(),
              noops: z.array(z.string()),
              updated: z.array(z.string()),
            })
            .openapi({ required: ['noops', 'updated'] }),
          examples: {
            SecurityBulkUpdateApiKeysResponseExample1: {
              description: 'A successful response from updating two API keys.',
              value:
                '{\n  "updated": [\n    "VuaCfGcBCdbkQm-e5aOx",\n    "H3_AhoIBA9hmeQJdg7ij"\n  ],\n  "noops": []\n}',
            },
          },
        },
      },
    },
  },
})

