export const deleteSecurityApiKeyRoute = createRoute({
  method: 'delete',
  path: '/_security/api_key',
  tags: ['security'],
  summary: 'Invalidate API keys',
  description:
    "This API invalidates API keys created by the create API key or grant API key APIs.\nInvalidated API keys fail authentication, but they can still be viewed using the get API key information and query API key information APIs, for at least the configured retention period, until they are automatically deleted.\n\nTo use this API, you must have at least the `manage_security`, `manage_api_key`, or `manage_own_api_key` cluster privileges.\nThe `manage_security` privilege allows deleting any API key, including both REST and cross cluster API keys.\nThe `manage_api_key` privilege allows deleting any REST API key, but not cross cluster API keys.\nThe `manage_own_api_key` only allows deleting REST API keys that are owned by the user.\nIn addition, with the `manage_own_api_key` privilege, an invalidation request must be issued in one of the three formats:\n\n- Set the parameter `owner=true`.\n- Or, set both `username` and `realm_name` to match the user's identity.\n- Or, if the request is issued by an API key, that is to say an API key invalidates itself, specify its ID in the `ids` field.\n\n## Required authorization\n\n* Cluster privileges: `manage_api_key`,`manage_own_api_key`\n",
  operationId: 'security-invalidate-api-key',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              id: TypesIdSchema.exactOptional(),
              ids: z
                .array(TypesIdSchema)
                .exactOptional()
                .openapi({
                  description:
                    'A list of API key ids.\nThis parameter cannot be used with any of `name`, `realm_name`, or `username`.',
                }),
              name: TypesNameSchema.exactOptional().openapi({
                description:
                  'An API key name.\nThis parameter cannot be used with any of `ids`, `realm_name` or `username`.',
              }),
              owner: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Query API keys owned by the currently authenticated user.\nThe `realm_name` or `username` parameters cannot be specified when this parameter is set to `true` as they are assumed to be the currently authenticated ones.\n\nNOTE: At least one of `ids`, `name`, `username`, and `realm_name` must be specified if `owner` is `false`.',
                }),
              realm_name: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The name of an authentication realm.\nThis parameter cannot be used with either `ids` or `name`, or when `owner` flag is set to `true`.',
                }),
              username: TypesUsernameSchema.exactOptional().openapi({
                description:
                  'The username of a user.\nThis parameter cannot be used with either `ids` or `name` or when `owner` flag is set to `true`.',
              }),
            })
            .openapi({ required: [] }),
          examples: {
            SecurityInvalidateApiKeyRequestExample1: {
              summary: 'API keys by ID',
              description:
                'Run `DELETE /_security/api_key` to invalidate the API keys identified by ID.',
              value: '{\n  "ids" : [ "VuaCfGcBCdbkQm-e5aOx" ]\n}',
            },
            SecurityInvalidateApiKeyRequestExample2: {
              summary: 'API keys by name',
              description:
                'Run `DELETE /_security/api_key` to invalidate the API keys identified by name.',
              value: '{\n  "name" : "my-api-key"\n}',
            },
            SecurityInvalidateApiKeyRequestExample3: {
              summary: 'API keys by realm',
              description:
                'Run `DELETE /_security/api_key` to invalidate all API keys for the `native1` realm.',
              value: '{\n  "realm_name" : "native1"\n}',
            },
            SecurityInvalidateApiKeyRequestExample4: {
              summary: 'API keys by user',
              description:
                'Run `DELETE /_security/api_key` to invalidate all API keys for the user `myuser` in all realms.',
              value: '{\n  "username" : "myuser"\n}',
            },
            SecurityInvalidateApiKeyRequestExample5: {
              summary: 'API keys by ID and owner',
              description:
                'Run `DELETE /_security/api_key` to invalidate the API keys identified by ID if they are owned by the currently authenticated user.',
              value: '{\n  "ids" : ["VuaCfGcBCdbkQm-e5aOx"],\n  "owner" : "true"\n}',
            },
            SecurityInvalidateApiKeyRequestExample6: {
              summary: 'API keys by user and realm',
              description:
                'Run `DELETE /_security/api_key` to invalidate all API keys for the user `myuser` in the `native1` realm .',
              value: '{\n  "username" : "myuser",\n  "realm_name" : "native1"\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              error_count: z
                .number()
                .openapi({
                  description:
                    'The number of errors that were encountered when invalidating the API keys.',
                }),
              error_details: z
                .array(TypesErrorCauseSchema)
                .exactOptional()
                .openapi({
                  description:
                    'Details about the errors.\nThis field is not present in the response when `error_count` is `0`.',
                }),
              invalidated_api_keys: z
                .array(z.string())
                .openapi({
                  description:
                    'The IDs of the API keys that were invalidated as part of this request.',
                }),
              previously_invalidated_api_keys: z
                .array(z.string())
                .openapi({ description: 'The IDs of the API keys that were already invalidated.' }),
            })
            .openapi({
              required: ['error_count', 'invalidated_api_keys', 'previously_invalidated_api_keys'],
            }),
          examples: {
            SecurityInvalidateApiKeyResponseExample1: {
              description: 'A successful response from `DELETE /_security/api_key`.\n',
              value:
                '{\n  "invalidated_api_keys": [ \n    "api-key-id-1"\n  ],\n  "previously_invalidated_api_keys": [ \n    "api-key-id-2",\n    "api-key-id-3"\n  ],\n  "error_count": 2, \n  "error_details": [ \n    {\n      "type": "exception",\n      "reason": "error occurred while invalidating api keys",\n      "caused_by": {\n        "type": "illegal_argument_exception",\n        "reason": "invalid api key id"\n      }\n    },\n    {\n      "type": "exception",\n      "reason": "error occurred while invalidating api keys",\n      "caused_by": {\n        "type": "illegal_argument_exception",\n        "reason": "invalid api key id"\n      }\n    }\n  ]\n}',
            },
          },
        },
      },
    },
  },
})

export const postSecurityCrossClusterApiKeyRoute = createRoute({
  method: 'post',
  path: '/_security/cross_cluster/api_key',
  tags: ['security'],
  summary: 'Create a cross-cluster API key',
  description:
    'Create an API key of the `cross_cluster` type for the API key based remote cluster access.\nA `cross_cluster` API key cannot be used to authenticate through the REST interface.\n\nIMPORTANT: To authenticate this request you must use a credential that is not an API key. Even if you use an API key that has the required privilege, the API returns an error.\n\nCross-cluster API keys are created by the Elasticsearch API key service, which is automatically enabled.\n\nNOTE: Unlike REST API keys, a cross-cluster API key does not capture permissions of the authenticated user. The API key’s effective permission is exactly as specified with the `access` property.\n\nA successful request returns a JSON structure that contains the API key, its unique ID, and its name. If applicable, it also returns expiration information for the API key in milliseconds.\n\nBy default, API keys never expire. You can specify expiration information when you create the API keys.\n\nCross-cluster API keys can only be updated with the update cross-cluster API key API.\nAttempting to update them with the update REST API key API or the bulk update REST API keys API will result in an error.\n\n## Required authorization\n\n* Cluster privileges: `manage_security`\n',
  externalDocs: {
    description: 'About adding remote clusters',
    url: 'https://www.elastic.co/docs/deploy-manage/remote-clusters/remote-clusters-api-key',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/security-api-create-cross-cluster-api-key.html',
  },
  operationId: 'security-create-cross-cluster-api-key',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              access: SecurityTypesAccessSchema.openapi({
                description:
                  'The access to be granted to this API key.\nThe access is composed of permissions for cross-cluster search and cross-cluster replication.\nAt least one of them must be specified.\n\nNOTE: No explicit privileges should be specified for either search or replication access.\nThe creation process automatically converts the access specification to a role descriptor which has relevant privileges assigned accordingly.',
              }),
              expiration: TypesDurationSchema.exactOptional().openapi({
                description: 'Expiration time for the API key.\nBy default, API keys never expire.',
              }),
              metadata: TypesMetadataSchema.exactOptional().openapi({
                description:
                  'Arbitrary metadata that you want to associate with the API key.\nIt supports nested data structure.\nWithin the metadata object, keys beginning with `_` are reserved for system usage.',
              }),
              name: TypesNameSchema.openapi({
                description: 'Specifies the name for this API key.',
              }),
              certificate_identity: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "The certificate identity to associate with this API key.\nThis field is used to restrict the API key to connections authenticated by a specific TLS certificate.\nThe value should match the certificate's distinguished name (DN) pattern.",
                }),
            })
            .openapi({ required: ['access', 'name'] }),
          examples: {
            CreateCrossClusterApiKeyRequestExample1: {
              description:
                'Run `POST /_security/cross_cluster/api_key` to create a cross-cluster API key.\n',
              value:
                '{\n  "name": "my-cross-cluster-api-key",\n  "expiration": "1d",   \n  "access": {\n    "search": [  \n      {\n        "names": ["logs*"]\n      }\n    ],\n    "replication": [  \n      {\n        "names": ["archive*"]\n      }\n    ]\n  },\n  "metadata": {\n    "description": "phase one",\n    "environment": {\n      "level": 1,\n      "trusted": true,\n      "tags": ["dev", "staging"]\n    }\n  }\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              api_key: z.string().openapi({ description: 'Generated API key.' }),
              expiration: TypesDurationValueUnitMillisSchema.exactOptional().openapi({
                description: 'Expiration in milliseconds for the API key.',
              }),
              id: TypesIdSchema.openapi({ description: 'Unique ID for this API key.' }),
              name: TypesNameSchema.openapi({
                description: 'Specifies the name for this API key.',
              }),
              encoded: z
                .string()
                .openapi({
                  description:
                    'API key credentials which is the base64-encoding of\nthe UTF-8 representation of `id` and `api_key` joined\nby a colon (`:`).',
                }),
            })
            .openapi({ required: ['api_key', 'id', 'name', 'encoded'] }),
          examples: {
            CreateCrossClusterApiKeyResponseExample1: {
              description:
                'A successful response from `POST /_security/service/elastic/fleet-server/credential/token`.\n',
              value:
                '{\n  "created": true,\n  "token": {\n    "name": "Jk5J1HgBuyBK5TpDrdo4",\n    "value": "AAEAAWVsYXN0aWM...vZmxlZXQtc2VydmVyL3Rva2VuMTo3TFdaSDZ"\n  }\n}',
            },
          },
        },
      },
    },
  },
})

export const putSecurityServiceNamespaceServiceCredentialTokenNameRoute = createRoute({
  method: 'put',
  path: '/_security/service/{namespace}/{service}/credential/token/{name}',
  tags: ['security'],
  summary: 'Create a service account token',
  description:
    'Create a service accounts token for access without requiring basic authentication.\nThis route serves both kinds of service account, but the privileges differ: `manage_service_account` authorizes tokens of built-in accounts in the `elastic` namespace only, and tokens of a user-managed account require `manage_security`.\n\nNOTE: Service account tokens never expire.\nYou must actively delete them if they are no longer needed.\n\nIMPORTANT: On Serverless, non-operator users can create tokens for only `elastic/fleet-server` and `elastic/fleet-server-remote`.\nCreating tokens for any other service account requires operator privileges.\n\n## Required authorization\n\n* Cluster privileges: `manage_service_account`\n',
  externalDocs: {
    description: 'More about service accounts',
    url: 'https://www.elastic.co/docs/deploy-manage/users-roles/cluster-or-deployment-auth/service-accounts',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/security-api-create-service-token.html',
  },
  operationId: 'security-create-service-token',
  request: {
    params: z.object({
      namespace: SecurityCreateServiceTokenNamespaceParamsSchema,
      service: SecurityCreateServiceTokenServiceParamsSchema,
      name: SecurityCreateServiceTokenNameParamsSchema,
    }),
    query: z.object({ refresh: SecurityCreateServiceTokenRefreshParamsSchema }),
  },
  responses: { 200: SecurityCreateServiceToken_200Response },
})

