export const postSecurityDelegatePkiRoute = createRoute({
  method: 'post',
  path: '/_security/delegate_pki',
  tags: ['security'],
  summary: 'Delegate PKI authentication',
  description:
    "This API implements the exchange of an X509Certificate chain for an Elasticsearch access token.\nThe certificate chain is validated, according to RFC 5280, by sequentially considering the trust configuration of every installed PKI realm that has `delegation.enabled` set to `true`.\nA successfully trusted client certificate is also subject to the validation of the subject distinguished name according to thw `username_pattern` of the respective realm.\n\nThis API is called by smart and trusted proxies, such as Kibana, which terminate the user's TLS session but still want to authenticate the user by using a PKI realm—-​as if the user connected directly to Elasticsearch.\n\nIMPORTANT: The association between the subject public key in the target certificate and the corresponding private key is not validated.\nThis is part of the TLS authentication process and it is delegated to the proxy that calls this API.\nThe proxy is trusted to have performed the TLS authentication and this API translates that authentication into an Elasticsearch access token.\n\n## Required authorization\n\n* Cluster privileges: `all`\n",
  externalDocs: {
    description: 'Learn more about pki',
    url: 'https://www.elastic.co/docs/deploy-manage/users-roles/cluster-or-deployment-auth/pki',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/security-api-delegate-pki-authentication.html',
  },
  operationId: 'security-delegate-pki',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              x509_certificate_chain: z
                .array(z.string())
                .openapi({
                  description:
                    "The X509Certificate chain, which is represented as an ordered string array.\nEach string in the array is a base64-encoded (Section 4 of RFC4648 - not base64url-encoded) of the certificate's DER encoding.\n\nThe first element is the target certificate that contains the subject distinguished name that is requesting access.\nThis may be followed by additional certificates; each subsequent certificate is used to certify the previous one.",
                }),
            })
            .openapi({ required: ['x509_certificate_chain'] }),
          examples: {
            SecurityDelegatePkiRequestExample1: {
              description: 'Delegate a one element certificate chain.',
              value:
                '{\n"x509_certificate_chain": [""]\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              access_token: z
                .string()
                .openapi({
                  description:
                    "An access token associated with the subject distinguished name of the client's certificate.",
                }),
              expires_in: z
                .number()
                .openapi({
                  description: 'The amount of time (in seconds) before the token expires.',
                }),
              type: z.string().openapi({ description: 'The type of token.' }),
              authentication: SecurityDelegatePkiAuthenticationSchema.exactOptional(),
            })
            .openapi({ required: ['access_token', 'expires_in', 'type'] }),
          examples: {
            SecurityDelegatePkiResponseExample1: {
              description: 'A successful response from delegating a one element certificate chain.',
              value:
                '{\n  "access_token": "dGhpcyBpcyBub3QgYSByZWFsIHRva2VuIGJ1dCBpdCBpcyBvbmx5IHRlc3QgZGF0YS4gZG8gbm90IHRyeSB0byByZWFkIHRva2VuIQ==",\n  "type": "Bearer",\n  "expires_in": 1200,\n  "authentication": {\n    "username": "Elasticsearch Test Client",\n    "roles": [],\n    "full_name": null,\n    "email": null,\n    "metadata": {\n      "pki_dn": "O=org, OU=Elasticsearch, CN=Elasticsearch Test Client",\n      "pki_delegated_by_user": "test_admin",\n      "pki_delegated_by_realm": "file"\n    },\n    "enabled": true,\n    "authentication_realm": {\n      "name": "pki1",\n      "type": "pki"\n    },\n    "lookup_realm": {\n      "name": "pki1",\n      "type": "pki"\n    },\n    "authentication_type": "realm"\n  }\n}',
            },
          },
        },
      },
    },
  },
})

