export const putSecurityPrivilegeRoute = createRoute({
  method: 'put',
  path: '/_security/privilege',
  tags: ['security'],
  summary: 'Create or update application privileges',
  description:
    'To use this API, you must have one of the following privileges:\n\n* The `manage_security` cluster privilege (or a greater privilege such as `all`).\n* The "Manage Application Privileges" global privilege for the application being referenced in the request.\n\nApplication names are formed from a prefix, with an optional suffix that conform to the following rules:\n\n* The prefix must begin with a lowercase ASCII letter.\n* The prefix must contain only ASCII letters or digits.\n* The prefix must be at least 3 characters long.\n* If the suffix exists, it must begin with either a dash `-` or `_`.\n* The suffix cannot contain any of the following characters: `\\`, `/`, `*`, `?`, `"`, `<`, `>`, `|`, `,`, `*`.\n* No part of the name can contain whitespace.\n\nPrivilege names must begin with a lowercase ASCII letter and must contain only ASCII letters and digits along with the characters `_`, `-`, and `.`.\n\nAction names can contain any number of printable ASCII characters and must contain at least one of the following characters: `/`, `*`, `:`.\n\n## Required authorization\n\n* Cluster privileges: `manage_security`\n',
  externalDocs: {
    description: 'About Elasticsearch privileges',
    url: 'https://www.elastic.co/docs/reference/elasticsearch/security-privileges',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/security-api-put-privileges.html',
  },
  operationId: 'security-put-privileges',
  request: {
    query: z.object({ refresh: SecurityPutPrivilegesRefreshParamsSchema }),
    body: SecurityPutPrivilegesRequestBody,
  },
  responses: { 200: SecurityPutPrivileges_200Response },
})

