export const getSecurityServiceNamespaceServiceCredentialRoute = createRoute({
  method: 'get',
  path: '/_security/service/{namespace}/{service}/credential',
  tags: ['security'],
  summary: 'Get service account credentials',
  description:
    'To use this API, you must have at least the `read_security` cluster privilege (or a greater privilege such as `manage_service_account` or `manage_security`).\n\nThe response includes service account tokens that were created with the create service account tokens API as well as file-backed tokens from all nodes of the cluster.\n\nNOTE: For tokens backed by the `service_tokens` file, the API collects them from all nodes of the cluster.\nTokens with the same name from different nodes are assumed to be the same token and are only counted once towards the total number of service tokens.\n\n## Required authorization\n\n* Cluster privileges: `read_security`\n',
  externalDocs: {
    description: 'More about service accounts',
    url: 'https://www.elastic.co/docs/deploy-manage/users-roles/cluster-or-deployment-auth/service-accounts',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/security-api-get-service-credentials.html',
  },
  operationId: 'security-get-service-credentials',
  request: {
    params: z.object({
      namespace: TypesNamespaceSchema.openapi({
        param: {
          in: 'path',
          name: 'namespace',
          description: 'The name of the namespace.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Namespace' },
          style: 'simple',
        },
      }),
      service: TypesNameSchema.openapi({
        param: {
          in: 'path',
          name: 'service',
          description: 'The service name.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Name' },
          style: 'simple',
        },
      }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              service_account: z.string(),
              count: z.number(),
              tokens: z.record(z.string(), TypesMetadataSchema),
              nodes_credentials: SecurityGetServiceCredentialsNodesCredentialsSchema.openapi({
                description: 'Service account credentials collected from all nodes of the cluster.',
              }),
            })
            .openapi({ required: ['service_account', 'count', 'tokens', 'nodes_credentials'] }),
          examples: {
            GetServiceCredentialsResponseExample1: {
              description:
                'A successful response from `GET /_security/service/elastic/fleet-server/credential`. The response contains all credentials for the `elastic/fleet-server` service account.\n',
              value:
                '{\n  "service_account": "elastic/fleet-server",\n  "count": 3,\n  "tokens": {\n    "token1": {},        \n    "token42": {}        \n  },\n  "nodes_credentials": { \n    "_nodes": {          \n      "total": 3,\n      "successful": 3,\n      "failed": 0\n    },\n    "file_tokens": {      \n      "my-token": {\n        "nodes": [ "node0", "node1" ] \n      }\n    }\n  }\n}',
            },
          },
        },
      },
    },
  },
})

