export const postSecurityOidcAuthenticateRoute = createRoute({
  method: 'post',
  path: '/_security/oidc/authenticate',
  tags: ['security'],
  summary: 'Authenticate OpenID Connect',
  description:
    'Exchange an OpenID Connect authentication response message for an Elasticsearch internal access token and refresh token that can be subsequently used for authentication.\n\nElasticsearch exposes all the necessary OpenID Connect related functionality with the OpenID Connect APIs.\nThese APIs are used internally by Kibana in order to provide OpenID Connect based authentication, but can also be used by other, custom web applications or other clients.',
  operationId: 'security-oidc-authenticate',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              nonce: z
                .string()
                .openapi({
                  description:
                    'Associate a client session with an ID token and mitigate replay attacks.\nThis value needs to be the same as the one that was provided to the `/_security/oidc/prepare` API or the one that was generated by Elasticsearch and included in the response to that call.',
                }),
              realm: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The name of the OpenID Connect realm.\nThis property is useful in cases where multiple realms are defined.',
                }),
              redirect_uri: z
                .string()
                .openapi({
                  description:
                    'The URL to which the OpenID Connect Provider redirected the User Agent in response to an authentication request after a successful authentication.\nThis URL must be provided as-is (URL encoded), taken from the body of the response or as the value of a location header in the response from the OpenID Connect Provider.',
                }),
              state: z
                .string()
                .openapi({
                  description:
                    'Maintain state between the authentication request and the response.\nThis value needs to be the same as the one that was provided to the `/_security/oidc/prepare` API or the one that was generated by Elasticsearch and included in the response to that call.',
                }),
            })
            .openapi({ required: ['nonce', 'redirect_uri', 'state'] }),
          examples: {
            OidcAuthenticateRequestExample1: {
              description:
                'Run `POST /_security/oidc/authenticate` to exchange the response that was returned from the OpenID Connect Provider after a successful authentication for an Elasticsearch access token and refresh token. This example is from an authentication that uses the authorization code grant flow.\n',
              value:
                '{\n  "redirect_uri" : "https://oidc-kibana.elastic.co:5603/api/security/oidc/callback?code=jtI3Ntt8v3_XvcLzCFGq&state=4dbrihtIAt3wBTwo6DxK-vdk-sSyDBV8Yf0AjdkdT5I",\n  "state" : "4dbrihtIAt3wBTwo6DxK-vdk-sSyDBV8Yf0AjdkdT5I",\n  "nonce" : "WaBPH0KqPVdG5HHdSxPRjfoZbXMCicm5v1OiAj0DUFM",\n  "realm" : "oidc1"\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              access_token: z.string().openapi({ description: 'The Elasticsearch access token.' }),
              expires_in: z
                .number()
                .openapi({ description: 'The duration (in seconds) of the tokens.' }),
              refresh_token: z
                .string()
                .openapi({ description: 'The Elasticsearch refresh token.' }),
              type: z.string().openapi({ description: 'The type of token.' }),
            })
            .openapi({ required: ['access_token', 'expires_in', 'refresh_token', 'type'] }),
          examples: {
            OidcAuthenticateResponseExample1: {
              description:
                'A successful response from `POST /_security/oidc/authenticate`. It contains the access and refresh tokens that were generated, the token duration (in seconds), and the type.\n',
              value:
                '{\n  "access_token" : "dGhpcyBpcyBub3QgYSByZWFsIHRva2VuIGJ1dCBpdCBpcyBvbmx5IHRlc3QgZGF0YS4gZG8gbm90IHRyeSB0byByZWFkIHRva2VuIQ==",\n  "type" : "Bearer",\n  "expires_in" : 1200,\n  "refresh_token": "vLBPvmAB6KvwvJZr27cS"\n}',
            },
          },
        },
      },
    },
  },
})

