export const postSecurityOidcPrepareRoute = createRoute({
  method: 'post',
  path: '/_security/oidc/prepare',
  tags: ['security'],
  summary: 'Prepare OpenID connect authentication',
  description:
    'Create an oAuth 2.0 authentication request as a URL string based on the configuration of the OpenID Connect authentication realm in Elasticsearch.\n\nThe response of this API is a URL pointing to the Authorization Endpoint of the configured OpenID Connect Provider, which can be used to redirect the browser of the user in order to continue the authentication process.\n\nElasticsearch exposes all the necessary OpenID Connect related functionality with the OpenID Connect APIs.\nThese APIs are used internally by Kibana in order to provide OpenID Connect based authentication, but can also be used by other, custom web applications or other clients.',
  operationId: 'security-oidc-prepare-authentication',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              iss: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'In the case of a third party initiated single sign on, this is the issuer identifier for the OP that the RP is to send the authentication request to.\nIt cannot be specified when *realm* is specified.\nOne of *realm* or *iss* is required.',
                }),
              login_hint: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'In the case of a third party initiated single sign on, it is a string value that is included in the authentication request as the *login_hint* parameter.\nThis parameter is not valid when *realm* is specified.',
                }),
              nonce: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The value used to associate a client session with an ID token and to mitigate replay attacks.\nIf the caller of the API does not provide a value, Elasticsearch will generate one with sufficient entropy and return it in the response.',
                }),
              realm: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The name of the OpenID Connect realm in Elasticsearch the configuration of which should be used in order to generate the authentication request.\nIt cannot be specified when *iss* is specified.\nOne of *realm* or *iss* is required.',
                }),
              state: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The value used to maintain state between the authentication request and the response, typically used as a Cross-Site Request Forgery mitigation.\nIf the caller of the API does not provide a value, Elasticsearch will generate one with sufficient entropy and return it in the response.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            OidcPrepareAuthenticationRequestExample1: {
              summary: 'Prepare with realm',
              description:
                'Run `POST /_security/oidc/prepare` to generate an authentication request for the OpenID Connect Realm `oidc1`.\n',
              value: '{\n  "realm" : "oidc1"\n}',
            },
            OidcPrepareAuthenticationRequestExample2: {
              summary: 'Prepare with realm, state, and nonce',
              description:
                'Run `POST /_security/oidc/prepare` to generate an authentication request for the OpenID Connect Realm `oidc1`, where the values for the `state` and the `nonce` have been generated by the client.\n',
              value:
                '{\n  "realm" : "oidc1",\n  "state" : "lGYK0EcSLjqH6pkT5EVZjC6eIW5YCGgywj2sxROO",\n  "nonce" : "zOBXLJGUooRrbLbQk5YCcyC8AXw3iloynvluYhZ5"\n}',
            },
            OidcPrepareAuthenticationRequestExample3: {
              summary: 'Prepare by realm',
              description:
                'Run `POST /_security/oidc/prepare` to generate an authentication request for a third party initiated single sign on. Specify the issuer that should be used for matching the appropriate OpenID Connect Authentication realm.\n',
              value:
                '{\n  "iss" : "http://127.0.0.1:8080",\n  "login_hint": "this_is_an_opaque_string"\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              nonce: z.string(),
              realm: z.string(),
              redirect: z
                .string()
                .openapi({
                  description:
                    'A URI that points to the authorization endpoint of the OpenID Connect Provider with all the parameters of the authentication request as HTTP GET parameters.',
                }),
              state: z.string(),
            })
            .openapi({ required: ['nonce', 'realm', 'redirect', 'state'] }),
          examples: {
            OidcPrepareAuthenticationResponseExample1: {
              description:
                'A successful response from `POST /_security/oidc/prepare`. It contains the URI pointing to the Authorization Endpoint of the OpenID Connect Provider with all the parameters of the Authentication Request as HTTP GET parameters.\n',
              value:
                '{\n  "redirect" : "http://127.0.0.1:8080/c2id-login?scope=openid&response_type=id_token&redirect_uri=https%3A%2F%2Fmy.fantastic.rp%2Fcb&state=4dbrihtIAt3wBTwo6DxK-vdk-sSyDBV8Yf0AjdkdT5I&nonce=WaBPH0KqPVdG5HHdSxPRjfoZbXMCicm5v1OiAj0DUFM&client_id=elasticsearch-rp",\n  "state" : "4dbrihtIAt3wBTwo6DxK-vdk-sSyDBV8Yf0AjdkdT5I",\n  "nonce" : "WaBPH0KqPVdG5HHdSxPRjfoZbXMCicm5v1OiAj0DUFM",\n  "realm" : "oidc1"\n}',
            },
          },
        },
      },
    },
  },
})

export const getSecurityQueryApiKeyRoute = createRoute({
  method: 'get',
  path: '/_security/_query/api_key',
  tags: ['security'],
  summary: 'Find API keys with a query',
  description:
    'Get a paginated list of API keys and their information.\nYou can optionally filter the results with a query.\n\nTo use this API, you must have at least the `manage_own_api_key` or the `read_security` cluster privileges.\nIf you have only the `manage_own_api_key` privilege, this API returns only the API keys that you own.\nIf you have the `read_security`, `manage_api_key`, or greater privileges (including `manage_security`), this API returns all API keys regardless of ownership.\nRefer to the linked documentation for examples of how to find API keys:\n\n## Required authorization\n\n* Cluster privileges: `manage_own_api_key`,`read_security`\n',
  externalDocs: {
    description: 'About query API key information',
    url: 'https://www.elastic.co/docs/reference/elasticsearch/rest-apis/query-api-keys',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/security-api-query-api-key.html',
  },
  operationId: 'security-query-api-keys',
  request: {
    query: z.object({
      with_limited_by: SecurityQueryApiKeysWithLimitedByParamsSchema,
      with_profile_uid: SecurityQueryApiKeysWithProfileUidParamsSchema,
      typed_keys: SecurityQueryApiKeysTypedKeysParamsSchema,
    }),
    body: SecurityQueryApiKeysRequestBody,
  },
  responses: { 200: SecurityQueryApiKeys_200Response },
})

