export const putSecurityApiKeyIdRoute = createRoute({
  method: 'put',
  path: '/_security/api_key/{id}',
  tags: ['security'],
  summary: 'Update an API key',
  description:
    "Update attributes of an existing API key.\nThis API supports updates to an API key's access scope, expiration, and metadata.\n\nTo use this API, you must have at least the `manage_own_api_key` cluster privilege.\nUsers can only update API keys that they created or that were granted to them.\nTo update another user’s API key, use the `run_as` feature to submit a request on behalf of another user.\n\nIMPORTANT: It's not possible to use an API key as the authentication credential for this API. The owner user’s credentials are required.\n\nUse this API to update API keys created by the create API key or grant API Key APIs.\nIf you need to apply the same update to many API keys, you can use the bulk update API keys API to reduce overhead.\nIt's not possible to update expired API keys or API keys that have been invalidated by the invalidate API key API.\n\nThe access scope of an API key is derived from the `role_descriptors` you specify in the request and a snapshot of the owner user's permissions at the time of the request.\nThe snapshot of the owner's permissions is updated automatically on every call.\n\nIMPORTANT: If you don't specify `role_descriptors` in the request, a call to this API might still change the API key's access scope.\nThis change can occur if the owner user's permissions have changed since the API key was created or last modified.\n\n## Required authorization\n\n* Cluster privileges: `manage_own_api_key`\n",
  operationId: 'security-update-api-key',
  request: {
    params: z.object({
      id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'id',
          description: 'The ID of the API key to update.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              role_descriptors: z
                .record(z.string(), SecurityTypesRoleDescriptorSchema)
                .exactOptional()
                .openapi({
                  description:
                    "The role descriptors to assign to this API key.\nThe API key's effective permissions are an intersection of its assigned privileges and the point in time snapshot of permissions of the owner user.\nYou can assign new privileges by specifying them in this parameter.\nTo remove assigned privileges, you can supply an empty `role_descriptors` parameter, that is to say, an empty object `{}`.\nIf an API key has no assigned privileges, it inherits the owner user's full permissions.\nThe snapshot of the owner's permissions is always updated, whether you supply the `role_descriptors` parameter or not.\nThe structure of a role descriptor is the same as the request for the create API keys API.",
                }),
              metadata: TypesMetadataSchema.exactOptional().openapi({
                description:
                  'Arbitrary metadata that you want to associate with the API key.\nIt supports a nested data structure.\nWithin the metadata object, keys beginning with `_` are reserved for system usage.\nWhen specified, this value fully replaces the metadata previously associated with the API key.',
              }),
              expiration: TypesDurationSchema.exactOptional().openapi({
                description:
                  'The expiration time for the API key.\nBy default, API keys never expire.\nThis property can be omitted to leave the expiration unchanged.',
              }),
            })
            .openapi({ required: [] }),
          examples: {
            UpdateApiKeyRequestExample1: {
              summary: 'Update role and metadata',
              description:
                'Run `PUT /_security/api_key/VuaCfGcBCdbkQm-e5aOx` to assign new role descriptors and metadata to an API key.\n',
              value:
                '{\n  "role_descriptors": {\n    "role-a": {\n      "indices": [\n        {\n          "names": ["*"],\n          "privileges": ["write"]\n        }\n      ]\n    }\n  },\n  "metadata": {\n    "environment": {\n      "level": 2,\n      "trusted": true,\n      "tags": ["production"]\n    }\n  }\n}',
            },
            UpdateApiKeyRequestExample2: {
              summary: 'Remove permissions',
              description:
                "Run `PUT /_security/api_key/VuaCfGcBCdbkQm-e5aOx` to remove the API key's previously assigned permissions. It will inherit the owner user's full permissions.\n",
              value: '{\n  "role_descriptors": {}\n}',
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              updated: z
                .boolean()
                .openapi({
                  description:
                    "If `true`, the API key was updated.\nIf `false`, the API key didn't change because no change was detected.",
                }),
            })
            .openapi({ required: ['updated'] }),
          examples: {
            UpdateApiKeyResponseExample1: {
              summary: 'Update role and metadata',
              description:
                "A successful response from `PUT /_security/api_key/VuaCfGcBCdbkQm-e5aOx`. The API key's effective permissions after the update will be the intersection of the supplied role descriptors and the owner user's permissions.\n",
              value: '{\n  "updated": true\n}',
            },
          },
        },
      },
    },
  },
})

export const putSecurityCrossClusterApiKeyIdRoute = createRoute({
  method: 'put',
  path: '/_security/cross_cluster/api_key/{id}',
  tags: ['security'],
  summary: 'Update a cross-cluster API key',
  description:
    "Update the attributes of an existing cross-cluster API key, which is used for API key based remote cluster access.\n\nTo use this API, you must have at least the `manage_security` cluster privilege.\nUsers can only update API keys that they created.\nTo update another user's API key, use the `run_as` feature to submit a request on behalf of another user.\n\nIMPORTANT: It's not possible to use an API key as the authentication credential for this API.\nTo update an API key, the owner user's credentials are required.\n\nIt's not possible to update expired API keys, or API keys that have been invalidated by the invalidate API key API.\n\nThis API supports updates to an API key's access scope, metadata, and expiration.\nThe owner user's information, such as the `username` and `realm`, is also updated automatically on every call.\n\nNOTE: This API cannot update REST API keys, which should be updated by either the update API key or bulk update API keys API.\n\nTo learn more about how to use this API, refer to the [Update cross cluter API key API examples page](https://www.elastic.co/docs/reference/elasticsearch/rest-apis/update-cc-api-key-examples).\n\n## Required authorization\n\n* Cluster privileges: `manage_security`\n",
  externalDocs: {
    description: 'About adding remote clusters',
    url: 'https://www.elastic.co/docs/deploy-manage/remote-clusters/remote-clusters-api-key',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/security-api-update-cross-cluster-api-key.html',
  },
  operationId: 'security-update-cross-cluster-api-key',
  request: {
    params: z.object({
      id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'id',
          description: 'The ID of the cross-cluster API key to update.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              access: SecurityTypesAccessSchema.openapi({
                description:
                  'The access to be granted to this API key.\nThe access is composed of permissions for cross cluster search and cross cluster replication.\nAt least one of them must be specified.\nWhen specified, the new access assignment fully replaces the previously assigned access.',
              }),
              expiration: TypesDurationSchema.exactOptional().openapi({
                description:
                  'The expiration time for the API key.\nBy default, API keys never expire. This property can be omitted to leave the value unchanged.',
              }),
              metadata: TypesMetadataSchema.exactOptional().openapi({
                description:
                  'Arbitrary metadata that you want to associate with the API key.\nIt supports nested data structure.\nWithin the metadata object, keys beginning with `_` are reserved for system usage.\nWhen specified, this information fully replaces metadata previously associated with the API key.',
              }),
              certificate_identity: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "The certificate identity to associate with this API key.\nThis field is used to restrict the API key to connections authenticated by a specific TLS certificate.\nThe value should match the certificate's distinguished name (DN) pattern.\nWhen specified, this fully replaces any previously assigned certificate identity.\nTo clear an existing certificate identity, explicitly set this field to `null`.\nWhen omitted, the existing certificate identity remains unchanged.",
                }),
            })
            .openapi({ required: ['access'] }),
          examples: {
            UpdateCrossClusterApiKeyRequestExample1: {
              description:
                'Run `PUT /_security/cross_cluster/api_key/VuaCfGcBCdbkQm-e5aOx` to update a cross-cluster API key, assigning it new access scope and metadata.\n',
              value:
                '{\n  "access": {\n    "replication": [\n      {\n        "names": ["archive"]\n      }\n    ]\n  },\n  "metadata": {\n    "application": "replication"\n  }\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              updated: z
                .boolean()
                .openapi({
                  description:
                    'If `true`, the API key was updated.\nIf `false`, the API key didn’t change because no change was detected.',
                }),
            })
            .openapi({ required: ['updated'] }),
          examples: {
            UpdateCrossClusterApiKeyResponseExample1: {
              description:
                'A successful response from `PUT /_security/cross_cluster/api_key/VuaCfGcBCdbkQm-e5aOx` that indicates that the API key was updated.\n',
              value: '{\n  "updated": true\n}',
            },
          },
        },
      },
    },
  },
})

export const putSecurityProfileUidDataRoute = createRoute({
  method: 'put',
  path: '/_security/profile/{uid}/_data',
  tags: ['security'],
  summary: 'Update user profile data',
  description:
    "Update specific data for the user profile that is associated with a unique ID.\n\nNOTE: The user profile feature is designed only for use by Kibana and Elastic's Observability, Enterprise Search, and Elastic Security solutions.\nIndividual users and external applications should not call this API directly.\nElastic reserves the right to change or remove this feature in future releases without prior notice.\n\nTo use this API, you must have one of the following privileges:\n\n* The `manage_user_profile` cluster privilege.\n* The `update_profile_data` global privilege for the namespaces that are referenced in the request.\n\nThis API updates the `labels` and `data` fields of an existing user profile document with JSON objects.\nNew keys and their values are added to the profile document and conflicting keys are replaced by data that's included in the request.\n\nFor both labels and data, content is namespaced by the top-level fields.\nThe `update_profile_data` global privilege grants privileges for updating only the allowed namespaces.\n\n## Required authorization\n\n* Cluster privileges: `manage_user_profile`\n",
  operationId: 'security-update-user-profile-data',
  request: {
    params: z.object({ uid: SecurityUpdateUserProfileDataUidParamsSchema }),
    query: z.object({
      if_seq_no: SecurityUpdateUserProfileDataIfSeqNoParamsSchema,
      if_primary_term: SecurityUpdateUserProfileDataIfPrimaryTermParamsSchema,
      refresh: SecurityUpdateUserProfileDataRefreshParamsSchema,
    }),
    body: SecurityUpdateUserProfileDataRequestBody,
  },
  responses: { 200: SecurityUpdateUserProfileData_200Response },
})

