export const putSlmPolicyPolicyIdRoute = createRoute({
  method: 'put',
  path: '/_slm/policy/{policy_id}',
  tags: ['slm'],
  summary: 'Create or update a policy',
  description:
    'Create or update a snapshot lifecycle policy.\nIf the policy already exists, this request increments the policy version.\nOnly the latest version of a policy is stored.\n\n## Required authorization\n\n* Index privileges: `manage`\n* Cluster privileges: `manage_slm`\n',
  operationId: 'slm-put-lifecycle',
  request: {
    params: z.object({
      policy_id: TypesNameSchema.openapi({
        param: {
          in: 'path',
          name: 'policy_id',
          description:
            'The identifier for the snapshot lifecycle policy you want to create or update.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Name' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      master_timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'master_timeout',
            description:
              'The period to wait for a connection to the master node.\nIf no response is received before the timeout expires, the request fails and returns an error.\nTo indicate that the request should never timeout, set it to `-1`.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
      timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'timeout',
            description:
              'The period to wait for a response.\nIf no response is received before the timeout expires, the request fails and returns an error.\nTo indicate that the request should never timeout, set it to `-1`.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              config: SlmTypesConfigurationSchema.exactOptional().openapi({
                description: 'Configuration for each snapshot created by the policy.',
              }),
              name: TypesNameSchema.exactOptional().openapi({
                description:
                  'Name automatically assigned to each snapshot created by the policy. Date math is supported. To prevent conflicting snapshot names, a UUID is automatically appended to each snapshot name.',
              }),
              repository: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Repository used to store snapshots created by this policy. This repository must exist prior to the policy’s creation. You can create a repository using the snapshot repository API.',
                }),
              retention: SlmTypesRetentionSchema.exactOptional().openapi({
                description:
                  'Retention rules used to retain and delete snapshots created by the policy.',
              }),
              schedule: WatcherTypesCronExpressionSchema.exactOptional().openapi({
                description:
                  'Periodic or absolute schedule at which the policy creates snapshots. SLM applies schedule changes immediately.',
              }),
            })
            .openapi({ required: [] }),
          examples: {
            'PutSnapshotLifecycleRequestExample1 copy': {
              summary: 'Create a policy',
              description:
                "Run `PUT /_slm/policy/daily-snapshots` to create a lifecycle policy. The `schedule` is when the snapshot should be taken, in this case, 1:30am daily. The `retention` details specify to: keep snapshots for 30 days; always keep at least 5 successful snapshots, even if they're more than 30 days old; keep no more than 50 successful snapshots, even if they're less than 30 days old.\n",
              value:
                '{\n  "schedule": "0 30 1 * * ?",\n  "name": "<daily-snap-{now/d}>",\n  "repository": "my_repository",\n  "config": {\n    "indices": ["data-*", "important"],\n    "ignore_unavailable": false,\n    "include_global_state": false\n  },\n  "retention": {\n    "expire_after": "30d",\n    "min_count": 5,\n    "max_count": 50\n  }\n}',
            },
            PutSnapshotLifecycleRequestExample2: {
              summary: 'Create a policy with intevals',
              description:
                'Run `PUT /_slm/policy/hourly-snapshots` to create a lifecycle policy that uses interval scheduling. It creates a snapshot once every hour. The first snapshot will be created one hour after the policy is modified, with subsequent snapshots every hour afterward.\n',
              value:
                '{\n  "schedule": "1h",\n  "name": "<hourly-snap-{now/d}>",\n  "repository": "my_repository",\n  "config": {\n    "indices": ["data-*", "important"]\n  }\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: TypesAcknowledgedResponseBaseSchema } },
    },
  },
})

