export const getSqlAsyncIdRoute = createRoute({
  method: 'get',
  path: '/_sql/async/{id}',
  tags: ['sql'],
  summary: 'Get async SQL search results',
  description:
    'Get the current status and available results for an async SQL search or stored synchronous SQL search.\n\nIf the Elasticsearch security features are enabled, only the user who first submitted the SQL search can retrieve the search using this API.',
  operationId: 'sql-get-async',
  request: {
    params: z.object({
      id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'id',
          description: 'The identifier for the search.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      delimiter: z
        .string()
        .default(',')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'delimiter',
            description:
              'The separator for CSV results.\nThe API supports this parameter only for CSV responses.',
            deprecated: false,
            schema: { default: ',', type: 'string' },
            style: 'form',
            required: false,
          },
        }),
      format: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'format',
            description:
              'The format for the response.\nYou must specify a format using this parameter or the `Accept` HTTP header.\nIf you specify both, the API uses this parameter.',
            deprecated: false,
            schema: { type: 'string' },
            style: 'form',
            required: false,
          },
        }),
      keep_alive: TypesDurationSchema.default('5d')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'keep_alive',
            description:
              'The retention period for the search and its results.\nIt defaults to the `keep_alive` period for the original SQL search.',
            deprecated: false,
            schema: { default: '5d', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
      wait_for_completion_timeout: TypesDurationSchema.openapi({
        param: {
          in: 'query',
          name: 'wait_for_completion_timeout',
          description:
            'The period to wait for complete results.\nIt defaults to no timeout, meaning the request waits for complete search results.',
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Duration' },
          style: 'form',
          required: false,
        },
      }).exactOptional(),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              id: TypesIdSchema.openapi({
                description:
                  'Identifier for the search.\nThis value is returned only for async and saved synchronous searches.\nFor CSV, TSV, and TXT responses, this value is returned in the `Async-ID` HTTP header.',
              }),
              is_running: z
                .boolean()
                .openapi({
                  description:
                    'If `true`, the search is still running.\nIf `false`, the search has finished.\nThis value is returned only for async and saved synchronous searches.\nFor CSV, TSV, and TXT responses, this value is returned in the `Async-partial` HTTP header.',
                }),
              is_partial: z
                .boolean()
                .openapi({
                  description:
                    'If `true`, the response does not contain complete search results.\nIf `is_partial` is `true` and `is_running` is `true`, the search is still running.\nIf `is_partial` is `true` but `is_running` is `false`, the results are partial due to a failure or timeout.\nThis value is returned only for async and saved synchronous searches.\nFor CSV, TSV, and TXT responses, this value is returned in the `Async-partial` HTTP header.',
                }),
              columns: z
                .array(SqlTypesColumnSchema)
                .exactOptional()
                .openapi({
                  description: 'Column headings for the search results. Each object is a column.',
                }),
              cursor: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The cursor for the next set of paginated results.\nFor CSV, TSV, and TXT responses, this value is returned in the `Cursor` HTTP header.',
                }),
              rows: z
                .array(SqlTypesRowSchema)
                .openapi({ description: 'The values for the search results.' }),
            })
            .openapi({ required: ['id', 'is_running', 'is_partial', 'rows'] }),
        },
      },
    },
  },
})

