export const getSynonymsIdRoute = createRoute({
  method: 'get',
  path: '/_synonyms/{id}',
  tags: ['synonyms'],
  summary: 'Get a synonym set',
  description: '\n\n## Required authorization\n\n* Cluster privileges: `manage_search_synonyms`\n',
  operationId: 'synonyms-get-synonym',
  request: {
    params: z.object({
      id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'id',
          description: 'The synonyms set identifier to retrieve.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      from: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .default(0)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'from',
            description: 'The starting offset for synonym rules to retrieve.',
            deprecated: false,
            schema: { default: 0, type: 'number' },
            style: 'form',
            required: false,
          },
        }),
      size: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'size',
            description: 'The max number of synonym rules to retrieve.',
            deprecated: false,
            schema: { default: 10, type: 'number' },
            style: 'form',
            required: false,
          },
        }),
      search_after: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'search_after',
            description:
              'The synonym rule ID to use as a cursor for pagination.\nThe next page of results will start after this rule ID.\nThis parameter cannot be used with `from`.',
            deprecated: false,
            schema: { type: 'string' },
            'x-state': 'Generally available; Added in 9.5.0',
            style: 'form',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              count: z
                .number()
                .openapi({
                  description: 'The total number of synonyms rules that the synonyms set contains.',
                }),
              synonyms_set: z
                .array(SynonymsTypesSynonymRuleReadSchema)
                .openapi({ description: 'Synonym rule details.' }),
            })
            .openapi({ required: ['count', 'synonyms_set'] }),
          examples: {
            SynonymsGetResponseExample1: {
              description: 'A successful response from `GET _synonyms/my-synonyms-set`.',
              value:
                '{\n  "count": 3,\n  "synonyms_set": [\n    {\n      "id": "test-1",\n      "synonyms": "hello, hi"\n    },\n    {\n      "id": "test-2",\n      "synonyms": "bye, goodbye"\n    },\n    {\n      "id": "test-3",\n      "synonyms": "test => check"\n    }\n  ]\n}',
            },
          },
        },
      },
    },
  },
})

export const putSynonymsIdRoute = createRoute({
  method: 'put',
  path: '/_synonyms/{id}',
  tags: ['synonyms'],
  summary: 'Create or update a synonym set',
  description:
    'Synonym sets are limited to a maximum of 100,000 synonym rules per set by default.\nThis limit is configurable using the `synonyms.max_synonym_rules` cluster setting.\n\nWhen an existing synonyms set is updated, the search analyzers that use the synonyms set are reloaded automatically for all indices.\nThis is equivalent to invoking the reload search analyzers API for all indices that use the synonyms set.\n\nFor practical examples of how to create or update a synonyms set, refer to the External documentation.\n\n## Required authorization\n\n* Cluster privileges: `manage_search_synonyms`\n',
  externalDocs: {
    description: 'About synonym API examples',
    url: 'https://www.elastic.co/docs/solutions/search/full-text/create-update-synonyms-api-example',
    'x-previousVersionUrl':
      'https://www.elastic.co/guide/en/elasticsearch/reference/8.19/put-synonyms-set.html',
  },
  operationId: 'synonyms-put-synonym',
  request: {
    params: z.object({
      id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'id',
          description: 'The ID of the synonyms set to be created or updated.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      refresh: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'refresh',
            description:
              'If `true`, the request will refresh the analyzers with the new synonyms set and wait for the new synonyms to be available before returning.\nIf `false`, analyzers will not be reloaded with the new synonym set',
            deprecated: false,
            schema: { default: true, type: 'boolean' },
            'x-state': 'Generally available; Added in 9.1.0',
            style: 'form',
            required: false,
          },
        }),
      append: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'append',
            description:
              'If `true`, the provided synonym rules are appended to the existing set, with matching IDs overwriting existing rules.\nIf `false`, the entire synonyms set is replaced with the new synonym rules definitions.',
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            'x-state': 'Generally available; Added in 9.5.0',
            style: 'form',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              synonyms_set: z
                .xor([SynonymsTypesSynonymRuleSchema, z.array(SynonymsTypesSynonymRuleSchema)])
                .openapi({ description: 'The synonym rules definitions for the synonyms set.' }),
            })
            .openapi({ required: ['synonyms_set'] }),
          examples: {
            SynonymsPutRequestExample1: {
              description: '',
              value: '\n{\n  "synonyms_set": {\n  "synonyms" : "hello, hi, howdy"\n  }\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              result: TypesResultSchema.openapi({ description: 'The update operation result.' }),
              reload_analyzers_details:
                IndicesReloadSearchAnalyzersReloadResultSchema.exactOptional().openapi({
                  description:
                    'Updating a synonyms set can reload the associated analyzers in case refresh is set to true.\nThis information is the analyzers reloading result.',
                }),
            })
            .openapi({ required: ['result'] }),
        },
      },
    },
    400: {
      description: '\nThe synonym rules are not valid.',
      content: {
        'application/json': {
          schema: TypesErrorResponseBaseSchema,
          examples: {
            SynonymsPutResponseExample1: {
              description:
                'An abbreviated response from `PUT _synonyms/my-synonyms-set`. If any of the synonym rules included is not valid, the API returns an error.\n',
              value:
                '{\n  "error": {\n    "root_cause": [\n      {\n        "type": "action_request_validation_exception",\n        "reason": "Validation Failed: 1: More than one explicit mapping specified in the same synonyms rule: [hello => hi => howdy];",\n        "stack_trace": ...\n      }\n    ],\n    "type": "action_request_validation_exception",\n    "reason": "Validation Failed: 1: More than one explicit mapping specified in the same synonyms rule: [hello => hi => howdy];",\n    "stack_trace": ...\n  },\n  "status": 400\n}',
            },
          },
        },
      },
    },
  },
})

export const deleteSynonymsIdRoute = createRoute({
  method: 'delete',
  path: '/_synonyms/{id}',
  tags: ['synonyms'],
  summary: 'Delete a synonym set',
  description:
    "You can only delete a synonyms set that is not in use by any index analyzer.\n\nSynonyms sets can be used in synonym graph token filters and synonym token filters.\nThese synonym filters can be used as part of search analyzers.\n\nAnalyzers need to be loaded when an index is restored (such as when a node starts, or the index becomes open).\nEven if the analyzer is not used on any field mapping, it still needs to be loaded on the index recovery phase.\n\nIf any analyzers cannot be loaded, the index becomes unavailable and the cluster status becomes red or yellow as index shards are not available.\nTo prevent that, synonyms sets that are used in analyzers can't be deleted.\nA delete request in this case will return a 400 response code.\n\nTo remove a synonyms set, you must first remove all indices that contain analyzers using it.\nYou can migrate an index by creating a new index that does not contain the token filter with the synonyms set, and use the reindex API in order to copy over the index data.\nOnce finished, you can delete the index.\nWhen the synonyms set is not used in analyzers, you will be able to delete it.\n\n## Required authorization\n\n* Cluster privileges: `manage_search_synonyms`\n",
  operationId: 'synonyms-delete-synonym',
  request: {
    params: z.object({
      id: TypesIdSchema.openapi({
        param: {
          in: 'path',
          name: 'id',
          description: 'The synonyms set identifier to delete.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Id' },
          style: 'simple',
        },
      }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: TypesAcknowledgedResponseBaseSchema } },
    },
  },
})

