export const getTransformTransformIdStatsRoute = createRoute({
  method: 'get',
  path: '/_transform/{transform_id}/_stats',
  tags: ['transform'],
  summary: 'Get transform stats',
  description:
    'Get usage information for transforms.\n\n## Required authorization\n\n* Index privileges: `read`,`view_index_metadata`\n* Cluster privileges: `monitor_transform`\n',
  operationId: 'transform-get-transform-stats',
  request: {
    params: z.object({
      transform_id: TypesNamesSchema.openapi({
        param: {
          in: 'path',
          name: 'transform_id',
          description:
            'Identifier for the transform. It can be a transform identifier or a\nwildcard expression. You can get information for all transforms by using\n`_all`, by specifying `*` as the `<transform_id>`, or by omitting the\n`<transform_id>`.',
          required: true,
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Names' },
          style: 'simple',
        },
      }),
    }),
    query: z.object({
      allow_no_match: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'allow_no_match',
            description:
              'Specifies what to do when the request:\n\n1. Contains wildcard expressions and there are no transforms that match.\n2. Contains the _all string or no identifiers and there are no matches.\n3. Contains wildcard expressions and there are only partial matches.\n\nIf this parameter is false, the request returns a 404 status code when\nthere are no matches or only partial matches.',
            deprecated: false,
            schema: { default: true, type: 'boolean' },
            style: 'form',
            required: false,
          },
        }),
      basic: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'basic',
            description:
              "If true, the response includes `id`, `state`, `node`, `stats`, `health`,\nand basic `checkpointing` information (the last and next checkpoint\nnumbers, and the next checkpoint's `position` and `progress`). Skips\nstatistics that require heavy computations to calculate:\n`operations_behind`, `changes_last_detected_at`, `last_search_time`, and\nthe checkpoint timestamps.",
            deprecated: false,
            schema: { default: false, type: 'boolean' },
            'x-state': 'Generally available; Added in 8.13.0',
            style: 'form',
            required: false,
          },
        }),
      from: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .default(0)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'from',
            description: 'Skips the specified number of transforms.',
            deprecated: false,
            schema: { default: 0, type: 'number' },
            style: 'form',
            required: false,
          },
        }),
      size: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'size',
            description: 'Specifies the maximum number of transforms to obtain.',
            deprecated: false,
            schema: { default: 100, type: 'number' },
            style: 'form',
            required: false,
          },
        }),
      timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'timeout',
            description: 'Controls the time to wait for the stats',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              count: z.number(),
              transforms: z.array(TransformGetTransformStatsTransformStatsSchema),
            })
            .openapi({ required: ['count', 'transforms'] }),
          examples: {
            GetTransformStatsResponseExample1: {
              description: 'A successful response that contains usage information for a transform.',
              value:
                '{\n  "count": 1,\n  "transforms": [\n    {\n      "id": "ecommerce-customer-transform",\n      "state": "started",\n      "node": {\n        "id": "cpTIGMsVQ8Gqwqlxxxxxxx",\n        "name": "my.home",\n        "ephemeral_id": "5-L21nFsQxxxxxxxxxx-xx",\n        "transport_address": "127.0.0.1:9300",\n        "attributes": {}\n      },\n      "stats": {\n        "pages_processed": 78,\n        "documents_processed": 6027,\n        "documents_indexed": 68,\n        "documents_deleted": 22,\n        "delete_time_in_ms": 214,\n        "trigger_count": 168,\n        "index_time_in_ms": 412,\n        "index_total": 20,\n        "index_failures": 0,\n        "search_time_in_ms": 353,\n        "search_total": 78,\n        "search_failures": 0,\n        "processing_time_in_ms": 8,\n        "processing_total": 78,\n        "exponential_avg_checkpoint_duration_ms": 97.30637923893185,\n        "exponential_avg_documents_indexed": 2.2064915040974062,\n        "exponential_avg_documents_processed": 179.89419945785045\n      },\n      "checkpointing": {\n        "last": {\n          "checkpoint": 20,\n          "timestamp_millis": 1585344558220,\n          "time_upper_bound_millis": 1585344498220\n        },\n        "changes_last_detected_at": 1585344558219\n      },\n      "health": {\n        "status": "green"\n      }\n    }\n  ]\n}',
            },
          },
        },
      },
    },
  },
})

