export const putWatcherSettingsRoute = createRoute({
  method: 'put',
  path: '/_watcher/settings',
  tags: ['watcher'],
  summary: 'Update Watcher index settings',
  description:
    'Update settings for the Watcher internal index (`.watches`).\nOnly a subset of settings can be modified.\nThis includes `index.auto_expand_replicas`, `index.number_of_replicas`, `index.routing.allocation.exclude.*`,\n`index.routing.allocation.include.*` and `index.routing.allocation.require.*`.\nModification of `index.routing.allocation.include._tier_preference` is an exception and is not allowed as the\nWatcher shards must always be in the `data_content` tier.\n\n## Required authorization\n\n* Cluster privileges: `manage_watcher`\n',
  operationId: 'watcher-update-settings',
  request: {
    query: z.object({
      master_timeout: TypesDurationSchema.default('30s')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'master_timeout',
            description:
              'The period to wait for a connection to the master node.\nIf no response is received before the timeout expires, the request fails and returns an error.',
            deprecated: false,
            schema: { default: '30s', allOf: [{ $ref: '#/components/schemas/_types.Duration' }] },
            style: 'form',
            required: false,
          },
        }),
      timeout: TypesDurationSchema.openapi({
        param: {
          in: 'query',
          name: 'timeout',
          description:
            'The period to wait for a response.\nIf no response is received before the timeout expires, the request fails and returns an error.',
          deprecated: false,
          schema: { $ref: '#/components/schemas/_types.Duration' },
          style: 'form',
          required: false,
        },
      }).exactOptional(),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              'index.auto_expand_replicas': z.string().exactOptional(),
              'index.number_of_replicas': z.number().exactOptional(),
            })
            .openapi({ required: [] }),
          examples: {
            WatcherUpdateSettingsRequestExample1: {
              value: '{\n  "index.auto_expand_replicas": "0-4"\n}',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z.object({ acknowledged: z.boolean() }).openapi({ required: ['acknowledged'] }),
        },
      },
    },
  },
})

